#Requires -Module Pester
<#
.SYNOPSIS
    Pester tests for the AzLocal.UpdateManagement module.

.DESCRIPTION
    Unit tests for the Azure Local Update Management module.
    These tests validate parameter validation, function behavior, and output types
    without requiring actual Azure connectivity (using mocks).

.NOTES
    Run with: Invoke-Pester -Path .\Tests -OutputFormat NUnitXml -OutputFile .\Tests\TestResults.xml
    Generate HTML: .\Tests\Generate-TestReport.ps1
#>

BeforeAll {
    # Import the module from parent directory
    $modulePath = Join-Path -Path $PSScriptRoot -ChildPath '..\AzLocal.UpdateManagement.psd1'
    Import-Module $modulePath -Force -ErrorAction Stop
    
    # Store module info for tests
    $script:ModuleInfo = Get-Module AzLocal.UpdateManagement
}

AfterAll {
    # Clean up
    Remove-Module AzLocal.UpdateManagement -Force -ErrorAction SilentlyContinue
}

Describe 'v0.9.25: Fleet settings, management-group scope, and grouped cluster tag filters' {
    BeforeEach {
        $script:fleetSettingsPath = Join-Path $env:TEMP ("fleet-settings-{0}.yml" -f [guid]::NewGuid())
        $script:savedFleetSettingsPath = $env:AZLOCAL_FLEET_SETTINGS_PATH
        $env:AZLOCAL_FLEET_SETTINGS_PATH = $script:fleetSettingsPath
    }

    AfterEach {
        if ($null -ne $script:savedFleetSettingsPath) { $env:AZLOCAL_FLEET_SETTINGS_PATH = $script:savedFleetSettingsPath }
        else { Remove-Item Env:\AZLOCAL_FLEET_SETTINGS_PATH -ErrorAction SilentlyContinue }
        Remove-Item -LiteralPath $script:fleetSettingsPath -Force -ErrorAction SilentlyContinue
        Remove-Item function:\az -Force -ErrorAction SilentlyContinue
        Remove-Variable capturedAzArgs -Scope Global -ErrorAction SilentlyContinue
    }

    It 'Keeps implicit subscription scope when the file is missing' {
        $settings = Get-AzLocalFleetSettings
        $settings.FileFound | Should -BeFalse
        $settings.ScopeMode | Should -Be 'ImplicitSubscriptions'
        @($settings.ManagementGroups).Count | Should -Be 0
        @($settings.ClusterTagFilters).Count | Should -Be 0
        $settings.ClusterTagFilterMode | Should -Be 'AnyGroup'
        $settings.UpdateStartWindowAllowBeforeMinutes | Should -Be 0
        $settings.UpdateStartWindowAllowAfterMinutes | Should -Be 0
    }

    It 'Keeps defaults when the file is fully commented' {
        @'
# schemaVersion: 1
# scope:
#   managementGroups:
#     - contoso-platform
'@ | Set-Content -LiteralPath $script:fleetSettingsPath -Encoding ASCII

        $settings = Get-AzLocalFleetSettings
        $settings.FileFound | Should -BeTrue
        $settings.ScopeMode | Should -Be 'ImplicitSubscriptions'
        $settings.MaxRowsPerTable | Should -Be 100
        $settings.MaxSummaryBytes | Should -Be 900000
        $settings.MaxIncidentsPerRun | Should -Be 25
        $settings.UpdateStartWindowAllowBeforeMinutes | Should -Be 0
        $settings.UpdateStartWindowAllowAfterMinutes | Should -Be 0
    }

    It 'Parses all supported sections and deduplicates management groups' {
        @'
schemaVersion: 1
scope:
  managementGroups:
    - group-a
    - group-a
    - 'group-b'
reporting:
  maxRowsPerTable: 250
  maxSummaryBytes: 500000
itsm:
  maxIncidentsPerRun: 40
'@ | Set-Content -LiteralPath $script:fleetSettingsPath -Encoding ASCII

        $settings = Get-AzLocalFleetSettings
        $settings.ScopeMode | Should -Be 'ManagementGroups'
        $settings.ManagementGroups | Should -Be @('group-a', 'group-b')
        $settings.MaxRowsPerTable | Should -Be 250
        $settings.MaxSummaryBytes | Should -Be 500000
        $settings.MaxIncidentsPerRun | Should -Be 40
    }

    It 'Accepts reporting.maxRowsPerTable at the 2000-row upper boundary' {
        "schemaVersion: 1`nreporting:`n  maxRowsPerTable: 2000" |
            Set-Content -LiteralPath $script:fleetSettingsPath -Encoding ASCII

        (Get-AzLocalFleetSettings).MaxRowsPerTable | Should -Be 2000
    }

    It 'Parses independent schema v4 UpdateStartWindow allowances' {
        @'
schemaVersion: 4
updateStartWindow:
  allowBeforeMinutes: 20
  allowAfterMinutes: 15
'@ | Set-Content -LiteralPath $script:fleetSettingsPath -Encoding ASCII

        $settings = Get-AzLocalFleetSettings
        $settings.SchemaVersion | Should -Be 4
        $settings.UpdateStartWindowAllowBeforeMinutes | Should -Be 20
        $settings.UpdateStartWindowAllowAfterMinutes | Should -Be 15
    }

    It 'Parses schema v3 tag groups in declared order with AND-within and OR-across semantics' {
        @(
            'schemaVersion: 3'
            'scope:'
            '  managementGroups:'
            '    - group-a'
            '  clusterTagFilters:'
            '    - name: Live'
            '      tags:'
            '        - name: Live-Environment'
            '          value: Yes'
            "        - name: 'ManagedBy'"
            "          value: 'Central IT #1'"
            '    - name: Test'
            '      tags:'
            '        - name: Test-Environment'
            '          value: Yes'
        ) | Set-Content -LiteralPath $script:fleetSettingsPath -Encoding ASCII

        $settings = Get-AzLocalFleetSettings
        $settings.SchemaVersion | Should -Be 3
        $settings.ClusterTagFilterMode | Should -Be 'AnyGroup'
        @($settings.ClusterTagFilters).Count | Should -Be 2
        $settings.ClusterTagFilters[0].Name | Should -Be 'Live'
        @($settings.ClusterTagFilters[0].Tags).Count | Should -Be 2
        $settings.ClusterTagFilters[0].Tags[0].Name | Should -Be 'Live-Environment'
        $settings.ClusterTagFilters[0].Tags[1].Value | Should -Be 'Central IT #1'
        $settings.ClusterTagFilters[1].Name | Should -Be 'Test'
        $settings.ClusterTagFilters[1].Tags[0].Name | Should -Be 'Test-Environment'
        InModuleScope AzLocal.UpdateManagement -Parameters @{ Filters = $settings.ClusterTagFilters } {
            param($Filters)
            ConvertTo-AzLocalClusterTagFilterKqlClause -ClusterTagFilters $Filters | Should -Match "tags\['Live-Environment'\].* and .*tags\['ManagedBy'\].* or .*tags\['Test-Environment'\]"
        }
    }

    It 'Rejects malformed, unsupported, and out-of-range active settings' -TestCases @(
        @{ Content = "scope:`n  managementGroups:`n    - group-a"; Expected = '*must declare schemaVersion*' }
            @{ Content = "schemaVersion: 2"; Expected = '*unsupported schemaVersion*' }
        @{ Content = "schemaVersion: 1`nreporting:`n  maxRowsPerTable: 0"; Expected = '*maxRowsPerTable must be between 1 and 2000*' }
        @{ Content = "schemaVersion: 1`nreporting:`n  maxRowsPerTable: 2001"; Expected = '*maxRowsPerTable must be between 1 and 2000*' }
        @{ Content = "schemaVersion: 1`nreporting:`n  maxSummaryBytes: 9999"; Expected = '*maxSummaryBytes must be between 10000 and 1000000*' }
        @{ Content = "schemaVersion: 1`nitsm:`n  maxIncidentsPerRun: 1001"; Expected = '*maxIncidentsPerRun must be between 0 and 1000*' }
        @{ Content = "schemaVersion: one"; Expected = '*must declare schemaVersion*' }
            @{ Content = "schemaVersion: 1`nscope:`n  clusterTagFilters:`n    - name: Live`n      tags:`n        - name: Environment`n          value: Production"; Expected = '*requires schemaVersion: 3*' }
            @{ Content = "schemaVersion: 3`nscope:`n  clusterTagFilters:"; Expected = '*must contain at least one named group*' }
            @{ Content = "schemaVersion: 3`nscope:`n  clusterTagFilters:`n    - name: Live`n      tags:"; Expected = '*must contain at least one tag*' }
            @{ Content = "schemaVersion: 3`nscope:`n  clusterTagFilters:`n    - name: Live`n      tags:`n        - name: Environment"; Expected = '*requires non-empty name and value*' }
            @{ Content = "schemaVersion: 3`nscope:`n  clusterTagFilters:`n    - name: Live`n      tags:`n        - name: Environment`n          value: Production`n        - name: environment`n          value: Test"; Expected = '*duplicate tag name*Environment*Live*' }
            @{ Content = "schemaVersion: 3`nscope:`n  clusterTagFilters:`n    - name: Live`n      tags:`n        - name: UpdateRing`n          value: Production"; Expected = '*module-owned control tag*UpdateRing*' }
            @{ Content = "schemaVersion: 3`nupdateStartWindow:`n  allowBeforeMinutes: 20"; Expected = '*require schemaVersion: 4*' }
            @{ Content = "schemaVersion: 4`nupdateStartWindow:`n  allowBeforeMinutes: -1"; Expected = '*allowBeforeMinutes must be between 0 and 60*' }
            @{ Content = "schemaVersion: 4`nupdateStartWindow:`n  allowBeforeMinutes: 61"; Expected = '*allowBeforeMinutes must be between 0 and 60*' }
            @{ Content = "schemaVersion: 4`nupdateStartWindow:`n  allowAfterMinutes: -1"; Expected = '*allowAfterMinutes must be between 0 and 60*' }
            @{ Content = "schemaVersion: 4`nupdateStartWindow:`n  allowAfterMinutes: 61"; Expected = '*allowAfterMinutes must be between 0 and 60*' }
    ) {
        param($Content, $Expected)
        Set-Content -LiteralPath $script:fleetSettingsPath -Value $Content -Encoding ASCII
        { Get-AzLocalFleetSettings } | Should -Throw -ExpectedMessage $Expected
    }

    It 'Prefers an explicit path over the environment setting' {
        Set-Content -LiteralPath $script:fleetSettingsPath -Value 'schemaVersion: 3' -Encoding ASCII
        $explicitPath = Join-Path $env:TEMP ("fleet-settings-explicit-{0}.yml" -f [guid]::NewGuid())
        try {
            Set-Content -LiteralPath $explicitPath -Value 'schemaVersion: 1' -Encoding ASCII
            $settings = Get-AzLocalFleetSettings -Path $explicitPath
            $settings.Path | Should -Be ([System.IO.Path]::GetFullPath($explicitPath))
            $settings.SchemaVersion | Should -Be 1
        }
        finally {
            Remove-Item -LiteralPath $explicitPath -Force -ErrorAction SilentlyContinue
        }
    }

    It 'Parses one management group and forwards it to Azure CLI' {
        @'
schemaVersion: 1
scope:
  managementGroups:
    - contoso-platform
'@ | Set-Content -LiteralPath $script:fleetSettingsPath -Encoding ASCII

        $settings = Get-AzLocalFleetSettings
        $settings.ScopeMode | Should -Be 'ManagementGroups'
        @($settings.ManagementGroups).Count | Should -Be 1

        function global:az {
            param([Parameter(ValueFromRemainingArguments = $true)]$Remaining)
            $global:capturedAzArgs = @($Remaining)
            $global:LASTEXITCODE = 0
            return '{"data":[]}'
        }
        InModuleScope AzLocal.UpdateManagement {
            Invoke-AzResourceGraphQuery -Query 'resources | project id' | Out-Null
        }
        $groupSwitchIndex = [array]::IndexOf($global:capturedAzArgs, '--management-groups')
        $groupSwitchIndex | Should -BeGreaterThan -1
        $global:capturedAzArgs[$groupSwitchIndex + 1] | Should -Be 'contoso-platform'
        $global:capturedAzArgs | Should -Not -Contain '--subscriptions'
    }

    It 'Uses explicit subscriptions instead of configured management groups' {
        @'
schemaVersion: 1
scope:
  managementGroups:
    - contoso-platform
'@ | Set-Content -LiteralPath $script:fleetSettingsPath -Encoding ASCII

        function global:az {
            param([Parameter(ValueFromRemainingArguments = $true)]$Remaining)
            $global:capturedAzArgs = @($Remaining)
            $global:LASTEXITCODE = 0
            return '{"data":[]}'
        }
        InModuleScope AzLocal.UpdateManagement {
            Invoke-AzResourceGraphQuery -Query 'resources | project id' -SubscriptionId @('sub-b', 'sub-a') | Out-Null
        }
        $subscriptionSwitchIndex = [array]::IndexOf($global:capturedAzArgs, '--subscriptions')
        $subscriptionSwitchIndex | Should -BeGreaterThan -1
        $global:capturedAzArgs[$subscriptionSwitchIndex + 1] | Should -Be 'sub-b'
        $global:capturedAzArgs[$subscriptionSwitchIndex + 2] | Should -Be 'sub-a'
        $global:capturedAzArgs | Should -Not -Contain '--management-groups'
    }

    It 'Builds escaped KQL with AND within groups and OR across groups' {
        InModuleScope AzLocal.UpdateManagement {
            $filters = @(
                [pscustomobject]@{ Name = 'Live'; Tags = @(
                    [pscustomobject]@{ Name = "Owner's Team"; Value = "O'Brien" }
                    [pscustomobject]@{ Name = 'Environment'; Value = 'Production' }
                ) }
                [pscustomobject]@{ Name = 'Test'; Tags = @(
                    [pscustomobject]@{ Name = 'Environment'; Value = 'Test' }
                ) }
            )

            $clause = ConvertTo-AzLocalClusterTagFilterKqlClause -ClusterTagFilters $filters

            $clause | Should -BeExactly "| where (tostring(tags['Owner''s Team']) =~ 'O''Brien' and tostring(tags['Environment']) =~ 'Production') or (tostring(tags['Environment']) =~ 'Test')"
        }
    }

    It 'Matches one complete group and fails partial groups closed' {
        InModuleScope AzLocal.UpdateManagement {
            $filters = @(
                [pscustomobject]@{ Name = 'Live'; Tags = @(
                    [pscustomobject]@{ Name = 'Live-Environment'; Value = 'Yes' }
                    [pscustomobject]@{ Name = 'ManagedBy'; Value = 'CentralIT' }
                ) }
                [pscustomobject]@{ Name = 'Test'; Tags = @(
                    [pscustomobject]@{ Name = 'Test-Environment'; Value = 'Yes' }
                ) }
            )

            Test-AzLocalClusterMatchesTagFilter -Tags ([ordered]@{ 'live-environment' = 'YES'; ManagedBy = 'centralit' }) -ClusterTagFilters $filters | Should -BeTrue
            Test-AzLocalClusterMatchesTagFilter -Tags ([pscustomobject]@{ 'Test-Environment' = 'Yes' }) -ClusterTagFilters $filters | Should -BeTrue
            Test-AzLocalClusterMatchesTagFilter -Tags ([pscustomobject]@{ 'Live-Environment' = 'Yes' }) -ClusterTagFilters $filters | Should -BeFalse
            Test-AzLocalClusterMatchesTagFilter -Tags $null -ClusterTagFilters $filters | Should -BeFalse
        }
    }

    It 'Injects the global filter into inventory cluster queries without changing the shared ARG transport' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalFleetSettings {
                [pscustomobject]@{
                    ClusterTagFilters = @([pscustomobject]@{ Name = 'Environment'; Value = 'Production' })
                }
            }
            Mock Invoke-AzResourceGraphQuery {
                if ($Query -match "microsoft\.azurestackhci/clusters") {
                    return @([pscustomobject]@{
                        id = '/subscriptions/sub-1/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/cluster-1'
                        name = 'cluster-1'
                        resourceGroup = 'rg'
                        subscriptionId = 'sub-1'
                        tags = [pscustomobject]@{ Environment = 'Production' }
                    })
                }
                return @([pscustomobject]@{ subscriptionId = 'sub-1'; name = 'Subscription 1' })
            }

            $result = @(Get-AzLocalClusterInventory)

            $result.Count | Should -Be 1
            Should -Invoke Invoke-AzResourceGraphQuery -ParameterFilter {
                $Query -match "type =~ 'microsoft\.azurestackhci/clusters'" -and
                $Query -match "tostring\(tags\['Environment'\]\) =~ 'Production'"
            } -Times 1
        }
    }

    It 'Resolves authoritative selected cluster IDs for child-resource joins' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalFleetSettings {
                [pscustomobject]@{
                    ClusterTagFilters = @([pscustomobject]@{ Name = 'Environment'; Value = 'Production' })
                }
            }
            Mock Invoke-AzResourceGraphQuery {
                @(
                    [pscustomobject]@{ id = '/subscriptions/sub-1/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/one'; tags = [pscustomobject]@{ Environment = 'Production' } }
                    [pscustomobject]@{ id = '/subscriptions/sub-1/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/two'; tags = [pscustomobject]@{ Environment = 'Test' } }
                )
            }

            $scope = Get-AzLocalGlobalClusterScope -SubscriptionId 'sub-1' -IncludeReportedNodes

            $scope.Enabled | Should -BeTrue
            @($scope.ClusterIds).Count | Should -Be 1
            $scope.ClusterById.ContainsKey('/SUBSCRIPTIONS/SUB-1/RESOURCEGROUPS/RG/PROVIDERS/MICROSOFT.AZURESTACKHCI/CLUSTERS/ONE') | Should -BeTrue
            Should -Invoke Invoke-AzResourceGraphQuery -ParameterFilter {
                $SubscriptionId -eq 'sub-1' -and
                $Query -match "tags\['Environment'\]" -and
                $Query -match ', properties'
            } -Times 1
        }
    }

    It 'Fails closed when an explicit cluster resource ID is outside global scope' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalFleetSettings {
                [pscustomobject]@{
                    ClusterTagFilters = @([pscustomobject]@{ Name = 'Environment'; Value = 'Production' })
                }
            }
            Mock Invoke-AzResourceGraphQuery { @() }

            Test-AzLocalClusterResourceInGlobalScope -ClusterResourceId '/subscriptions/sub-1/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/one' | Should -BeFalse
            Should -Invoke Invoke-AzResourceGraphQuery -ParameterFilter {
                $SubscriptionId -eq 'sub-1' -and $Query -match "tags\['Environment'\]"
            } -Times 1
        }
    }

    It 'Batches 81 values into three ARG calls and retains every row' {
        InModuleScope AzLocal.UpdateManagement {
            $script:batchQueries = [System.Collections.Generic.List[string]]::new()
            Mock Invoke-AzResourceGraphQuery {
                [void]$script:batchQueries.Add($Query)
                $firstValue = (($script:batchQueries.Count - 1) * 40) + 1
                $lastValue = [Math]::Min($firstValue + 39, 81)
                for ($valueNumber = $firstValue; $valueNumber -le $lastValue; $valueNumber++) {
                    [pscustomobject]@{ Value = "cluster-$valueNumber" }
                }
            }

            $values = 1..81 | ForEach-Object { "cluster-$_" }
            $rows = Invoke-AzLocalResourceGraphValueBatches -Value $values -QueryTemplate 'resources | where name in~ ({0}) | project name' -BatchSize 40

            $script:batchQueries.Count | Should -Be 3
            @($rows).Count | Should -Be 81
            $rows[0].Value | Should -Be 'cluster-1'
            $rows[80].Value | Should -Be 'cluster-81'
        }
    }

    It 'queries large resource-ID fleets in bounded subscription batches and exact-filters candidates' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Invoke-AzResourceGraphQuery {
                if ($SubscriptionId -contains 'sub-1') {
                    @(
                        [pscustomobject]@{ ClusterResourceId_ = '/subscriptions/sub-1/resourcegroups/rg/providers/microsoft.azurestackhci/clusters/cluster-1'; Value = 'admitted' }
                        [pscustomobject]@{ ClusterResourceId_ = '/subscriptions/sub-1/resourcegroups/rg/providers/microsoft.azurestackhci/clusters/outside-scope'; Value = 'outside' }
                        $null
                    )
                }
            }

            $values = 1..201 | ForEach-Object {
                "/subscriptions/sub-$_/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/cluster-$_"
            }
            $template = "resources | extend ClusterResourceId_ = tolower(id) | where ClusterResourceId_ in~ ({0}) | project ClusterResourceId_"
            $rows = Invoke-AzLocalResourceGraphValueBatches -Value $values -QueryTemplate $template -ExactResourceIdProperty 'ClusterResourceId_' -BatchSize 40

            @($rows).Count | Should -Be 1
            $rows[0].Value | Should -Be 'admitted'
            Assert-MockCalled Invoke-AzResourceGraphQuery -Times 6 -Exactly
            Assert-MockCalled Invoke-AzResourceGraphQuery -ParameterFilter {
                @($SubscriptionId).Count -le 40 -and $Query -notmatch 'ClusterResourceId_ in~'
            } -Times 6 -Exactly
        }
    }
}

Describe 'Module: AzLocal.UpdateManagement' {
    
    Context 'Module Load' {
        It 'Should load the module without errors' {
            $script:ModuleInfo | Should -Not -BeNullOrEmpty
        }

        It 'Should have version 0.9.31' {
            $script:ModuleInfo.Version | Should -Be '0.9.31'
        }

        It 'Module version constants are in sync between .psm1 and .psd1' {
            # v0.7.67: regression guard for the drift bug where
            # $script:ModuleVersion in AzLocal.UpdateManagement.psm1 was '0.7.66'
            # while the manifest had been bumped to '0.7.67'. The script-scope
            # constant is the value emitted in run-log headers and stamped into
            # exported fleet-state JSON, so drift silently misreports the
            # generator version to consumers. Both must match.
            $manifestPath = Join-Path -Path $PSScriptRoot -ChildPath '..\AzLocal.UpdateManagement.psd1'
            $manifestVersion = (Import-PowerShellDataFile -Path $manifestPath).ModuleVersion
            $scriptVersion = InModuleScope AzLocal.UpdateManagement { $script:ModuleVersion }
            $scriptVersion | Should -Be $manifestVersion -Because '$script:ModuleVersion in the .psm1 must match ModuleVersion in the .psd1'
        }

        It 'README.md Latest Version banner matches manifest ModuleVersion' {
            # v0.7.67 polish: regression guard for the drift bug where
            # README.md still advertised "Latest Version: v0.7.66" after the
            # manifest had been bumped to 0.7.67 and v0.7.67 was published to
            # the PowerShell Gallery. The README banner and the gallery link
            # on the same line are the first thing a consumer reads, so
            # silent drift is a credibility bug. Both must match the manifest.
            $manifestPath = Join-Path -Path $PSScriptRoot -ChildPath '..\AzLocal.UpdateManagement.psd1'
            $readmePath   = Join-Path -Path $PSScriptRoot -ChildPath '..\README.md'
            $manifestVersion = (Import-PowerShellDataFile -Path $manifestPath).ModuleVersion
            $readmeContent = Get-Content -Path $readmePath -Raw
            $pattern = '\*\*Latest Version:\*\*\s+v(?<displayed>\d+\.\d+\.\d+)\s+-\s+\[Published in PowerShell Gallery\]\(https://www\.powershellgallery\.com/packages/AzLocal\.UpdateManagement/(?<urlversion>\d+\.\d+\.\d+)\)'
            $match = [regex]::Match($readmeContent, $pattern)
            $match.Success | Should -BeTrue -Because "README.md must contain a parseable '**Latest Version:** vX.Y.Z - [Published in PowerShell Gallery](https://www.powershellgallery.com/packages/AzLocal.UpdateManagement/X.Y.Z)' line"
            $match.Groups['displayed'].Value | Should -Be $manifestVersion -Because 'the displayed version in the README banner must match the manifest ModuleVersion'
            $match.Groups['urlversion'].Value | Should -Be $manifestVersion -Because 'the PowerShell Gallery URL in the README banner must point at the manifest ModuleVersion'
        }

        It 'README.md TOC "What''s New in vX.Y.Z" entry matches manifest ModuleVersion' {
            # v0.7.67 polish: companion to the Latest Version banner guard.
            # The TOC's main-body "What's New in vX.Y.Z" link must always
            # point at the current manifest version - prior versions live
            # under the Release History sub-list.
            $manifestPath = Join-Path -Path $PSScriptRoot -ChildPath '..\AzLocal.UpdateManagement.psd1'
            $readmePath   = Join-Path -Path $PSScriptRoot -ChildPath '..\README.md'
            $manifestVersion = (Import-PowerShellDataFile -Path $manifestPath).ModuleVersion
            $manifestVersionAnchor = $manifestVersion -replace '\.',''
            $readmeContent = Get-Content -Path $readmePath -Raw
            # Match the top-level TOC link: "- [What's New in vX.Y.Z](#whats-new-in-vXYZ)"
            # (this is the main-body link, NOT the indented Release History sub-entry).
            # Note: do NOT anchor with trailing $ - .NET (?m)$ matches before \n but not
            # before \r, so on CRLF files \)$ never matches; use a CRLF-tolerant lookahead.
            $pattern = "(?m)^- \[What's New in v(?<displayed>\d+\.\d+\.\d+)\]\(#whats-new-in-v(?<anchor>\d+)\)(?=\r?\n|\z)"
            $match = [regex]::Match($readmeContent, $pattern)
            $match.Success | Should -BeTrue -Because "README.md TOC must contain a main-body '- [What's New in vX.Y.Z](#whats-new-in-vXYZ)' entry"
            $match.Groups['displayed'].Value | Should -Be $manifestVersion -Because 'the TOC main-body What''s New entry must point at the current manifest ModuleVersion'
            $match.Groups['anchor'].Value | Should -Be $manifestVersionAnchor -Because "the TOC anchor must collapse to the manifest ModuleVersion (#whats-new-in-v$manifestVersionAnchor)"
            # The TOC must list ONLY the current release's What's New entry.
            # Prior versions live under the Release History sub-list (as
            # indented `  - [...]` entries, which this top-level `^- ` pattern
            # does not match). Stale top-level entries (e.g. a leftover
            # "What's New in v0.8.7" from an earlier bump) must be removed.
            $allTocMatches = [regex]::Matches($readmeContent, $pattern)
            $allTocMatches.Count | Should -Be 1 -Because "the TOC must list only the current release What's New entry; prior versions belong under Release History (found: $(($allTocMatches | ForEach-Object { $_.Groups['displayed'].Value }) -join ', '))"
        }

        It 'README.md main body has exactly one "## What''s New" section, pointing at manifest ModuleVersion' {
            # v0.7.67 polish: regression guard for the drift bug where prior
            # release "What's New" sections were left at `##` level in the
            # main body (v0.7.66 release missed moving v0.7.65 to Release
            # History; v0.7.67 publish missed moving v0.7.66). The current-
            # release section is the only one that should be `##` in the main
            # body; every prior section MUST live under `## Release History`
            # as `### What's New in vX.Y.Z`.
            $manifestPath = Join-Path -Path $PSScriptRoot -ChildPath '..\AzLocal.UpdateManagement.psd1'
            $readmePath   = Join-Path -Path $PSScriptRoot -ChildPath '..\README.md'
            $manifestVersion = (Import-PowerShellDataFile -Path $manifestPath).ModuleVersion
            # Force array context with @(...) - Select-String returning a single match
            # otherwise collapses to a scalar string and $h2Matches[0] returns the first
            # CHARACTER of that string ('#') rather than the line text.
            $h2Matches = @(Select-String -Path $readmePath -Pattern "^## What's New in v\d+\.\d+\.\d+" -CaseSensitive |
                           ForEach-Object { $_.Line })
            $h2Matches.Count | Should -Be 1 -Because "exactly one '## What's New' section must exist in the README main body (found: $($h2Matches -join '; '))"
            $h2Matches[0] | Should -Be "## What's New in v$manifestVersion" -Because 'the sole main-body What''s New section must match the current manifest ModuleVersion'
        }

        It 'CHANGELOG.md first "## [X.Y.Z]" heading matches manifest ModuleVersion' {
            # v0.7.71 polish: regression guard for the drift bug pattern where
            # a release ships to PSGallery but CHANGELOG.md still has the
            # PRIOR version as its first entry (because someone forgot to
            # prepend the new section). The most-recent CHANGELOG.md "##
            # [X.Y.Z] - YYYY-MM-DD" entry MUST match the manifest ModuleVersion.
            $manifestPath  = Join-Path -Path $PSScriptRoot -ChildPath '..\AzLocal.UpdateManagement.psd1'
            $changelogPath = Join-Path -Path $PSScriptRoot -ChildPath '..\CHANGELOG.md'
            $manifestVersion = (Import-PowerShellDataFile -Path $manifestPath).ModuleVersion
            $changelogContent = Get-Content -Path $changelogPath -Raw
            $match = [regex]::Match($changelogContent, '(?m)^## \[(?<v>\d+\.\d+\.\d+)\]')
            $match.Success | Should -BeTrue -Because 'CHANGELOG.md must contain at least one "## [X.Y.Z] - YYYY-MM-DD" entry'
            $match.Groups['v'].Value | Should -Be $manifestVersion -Because 'the first (most-recent) CHANGELOG.md "## [X.Y.Z]" heading must match the manifest ModuleVersion - did you forget to prepend the new release section?'
        }

        It 'psd1 ReleaseNotes first "## Version X.Y.Z" heading matches manifest ModuleVersion' {
            # v0.7.71 polish: regression guard for the drift bug pattern where
            # the manifest ModuleVersion is bumped but the PSData.ReleaseNotes
            # here-string still leads with the PRIOR version's heading. The
            # ReleaseNotes block is what PSGallery renders on the module page,
            # so drift here means the gallery advertises stale notes for the
            # new release. The first "## Version X.Y.Z" heading MUST match
            # the manifest ModuleVersion.
            $manifestPath = Join-Path -Path $PSScriptRoot -ChildPath '..\AzLocal.UpdateManagement.psd1'
            $manifestData = Import-PowerShellDataFile -Path $manifestPath
            $manifestVersion = $manifestData.ModuleVersion
            $releaseNotes    = $manifestData.PrivateData.PSData.ReleaseNotes
            $releaseNotes | Should -Not -BeNullOrEmpty -Because 'psd1 PrivateData.PSData.ReleaseNotes must be populated'
            $match = [regex]::Match($releaseNotes, '(?m)^## Version (?<v>\d+\.\d+\.\d+)\b')
            $match.Success | Should -BeTrue -Because 'psd1 ReleaseNotes must contain at least one "## Version X.Y.Z" heading'
            $match.Groups['v'].Value | Should -Be $manifestVersion -Because 'the first "## Version X.Y.Z" heading in psd1 ReleaseNotes must match the manifest ModuleVersion - did you forget to prepend the new release section?'
        }

        It 'All bundled <Platform> *.yml pipeline samples pin GENERATED_AGAINST_MODULE_VERSION to manifest ModuleVersion' -ForEach @(
            @{ Platform = 'github-actions' }
            @{ Platform = 'azure-devops' }
        ) {
            # v0.7.71 polish: regression guard for the drift bug pattern that
            # caught v0.7.70 - the manifest ships at version X.Y.Z+1 but the
            # bundled pipeline samples are still pinned to X.Y.Z in their
            # GENERATED_AGAINST_MODULE_VERSION constant. Operators who run
            # Update-AzLocalPipelineExample after the upgrade get YAMLs
            # that disagree with the module they just installed. Every
            # bundled *.yml sample (both platforms) must pin to the current
            # manifest ModuleVersion. v0.8.7 de-numbered the filenames and
            # setup-validate-and-inventory.yml (the merged setup workflow) also
            # consumes the module, so every sample (no exemptions) carries the pin.
            $manifestPath = Join-Path -Path $PSScriptRoot -ChildPath '..\AzLocal.UpdateManagement.psd1'
            $manifestVersion = (Import-PowerShellDataFile -Path $manifestPath).ModuleVersion
            $samplesDir = Join-Path -Path $PSScriptRoot -ChildPath "..\Automation-Pipeline-Examples\$Platform"
            Test-Path $samplesDir | Should -BeTrue -Because "the $Platform sample folder must exist at $samplesDir"
            $yamls = @(Get-ChildItem -Path $samplesDir -Filter '*.yml' -File)
            $yamls.Count | Should -BeGreaterThan 0 -Because "$samplesDir must ship at least one *.yml sample"
            # GitHub Actions form (single line):
            #   GENERATED_AGAINST_MODULE_VERSION: '0.7.71'
            # Azure DevOps form (two lines under a `variables:` list entry):
            #   - name: GENERATED_AGAINST_MODULE_VERSION
            #     value: '0.7.71'
            # The regex matches either shape and captures the pinned version.
            $pattern = "(?m)(?:^\s*GENERATED_AGAINST_MODULE_VERSION:\s*'(?<gh>\d+\.\d+\.\d+)'|^\s*-?\s*name:\s*GENERATED_AGAINST_MODULE_VERSION\s*\r?\n\s*value:\s*'(?<ado>\d+\.\d+\.\d+)')"
            foreach ($yaml in $yamls) {
                $content = Get-Content -Path $yaml.FullName -Raw
                $match = [regex]::Match($content, $pattern)
                $match.Success | Should -BeTrue -Because "$($yaml.Name) must declare GENERATED_AGAINST_MODULE_VERSION (single-line GH form or two-line ADO form)"
                $pinned = if ($match.Groups['gh'].Success) { $match.Groups['gh'].Value } else { $match.Groups['ado'].Value }
                $pinned | Should -Be $manifestVersion -Because "$($yaml.Name) pins GENERATED_AGAINST_MODULE_VERSION='$pinned' but manifest ModuleVersion='$manifestVersion' - did you forget to bump the pipeline sample?"
            }
        }

