            }
        }

        It "Should have ReleaseNotes within the PSGallery character limit" {
            # PSGallery enforces a maximum of 10000 characters on the ReleaseNotes field
            # (publish fails with "Tags, ReleaseNotes, ... cannot exceed 10000 characters").
            # This test guards against accidental regressions when the release notes grow.
            $manifestPath = Join-Path -Path $PSScriptRoot -ChildPath '..\AzLocal.UpdateManagement.psd1'
            $data = Import-PowerShellDataFile -Path $manifestPath
            $releaseNotes = $data.PrivateData.PSData.ReleaseNotes
            $releaseNotes | Should -Not -BeNullOrEmpty
            $releaseNotes.Length | Should -BeLessOrEqual 10000 -Because "PSGallery rejects ReleaseNotes longer than 10000 characters"
        }
    }

    Context 'Pipeline YAML version pin (v0.7.66)' {
        # Every sample pipeline that installs AzLocal.UpdateManagement at runtime
        # also declares GENERATED_AGAINST_MODULE_VERSION so the install step can
        # detect drift between the YAML's expected version and what is installed
        # from PSGallery. The pin MUST match the current module manifest version,
        # otherwise the runtime drift detector will emit a noisy warning on every
        # pipeline run for end users. This test guards against forgetting to bump
        # the pin in Automation-Pipeline-Examples/**/*.yml when releasing a new
        # module version.
        It 'Every pipeline YAML that installs the module pins GENERATED_AGAINST_MODULE_VERSION to the manifest version' {
            $manifestVersion = $script:ModuleInfo.Version.ToString()
            $examplesRoot    = Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples'
            $examplesRoot    = (Resolve-Path -Path $examplesRoot).Path

            $ymlFiles = Get-ChildItem -Path $examplesRoot -Recurse -Filter '*.yml' -File
            $ymlFiles.Count | Should -BeGreaterThan 0 -Because 'sample pipeline YAMLs ship under Automation-Pipeline-Examples/{github-actions,azure-devops}/'

            $issues = New-Object System.Collections.Generic.List[string]
            foreach ($yml in $ymlFiles) {
                $content = Get-Content -LiteralPath $yml.FullName -Raw

                # The drift detector only runs in pipelines that install the
                # module at runtime. Auth-smoke-test YAMLs and ITSM sample YAMLs
                # do not install the module, so they are not expected to carry
                # a pin. Use the presence of 'Install-Module AzLocal.UpdateManagement'
                # as the discriminator.
                $installsModule = $content -match 'Install-Module\s+AzLocal\.UpdateManagement'

                # Two pin shapes are supported by the YAML examples:
                # 1) Inline (GH Actions env, or ADO inline variable):
                #      GENERATED_AGAINST_MODULE_VERSION: '0.7.65'
                # 2) ADO variables block, name/value pair on two lines:
                #      - name: GENERATED_AGAINST_MODULE_VERSION
                #        value: '0.7.65'
                $pin     = $null
                $inline  = [regex]::Match($content, "GENERATED_AGAINST_MODULE_VERSION\s*:\s*'([^']+)'")
                $twoLine = [regex]::Match($content, "(?ms)-\s*name\s*:\s*GENERATED_AGAINST_MODULE_VERSION\s*\r?\n\s*value\s*:\s*'([^']+)'")
                if ($inline.Success)       { $pin = $inline.Groups[1].Value }
                elseif ($twoLine.Success)  { $pin = $twoLine.Groups[1].Value }

                $relPath = $yml.FullName.Substring($examplesRoot.Length).TrimStart('\','/')

                if ($installsModule -and -not $pin) {
                    $issues.Add("${relPath}: installs the module but is MISSING the GENERATED_AGAINST_MODULE_VERSION pin")
                    continue
                }

                if ($pin -and $pin -ne $manifestVersion) {
                    $issues.Add("${relPath}: pinned to '$pin' but manifest is '$manifestVersion'")
                }
            }

            if ($issues.Count -gt 0) {
                $detail = ($issues -join [Environment]::NewLine)
            } else {
                $detail = '(no mismatches)'
            }
            $issues.Count | Should -Be 0 -Because "every pipeline YAML under Automation-Pipeline-Examples/ that installs AzLocal.UpdateManagement must pin GENERATED_AGAINST_MODULE_VERSION to the current manifest version $manifestVersion. Bumping the manifest version requires the same bump in every sample YAML. Findings:$([Environment]::NewLine)$detail"
        }
    }

    Context 'Pipeline YAML installed-older-than-generated guard (v0.7.66)' {
        # v0.7.66: every pipeline YAML that installs the module at runtime must
        # warn when the runtime-installed module version is OLDER than
        # GENERATED_AGAINST_MODULE_VERSION. The existing version-check block
        # already handles 'installed -gt generated' (YAML stale) and
        # 'latest -gt installed' (newer module on PSGallery), but the
        # 'installed -lt generated' branch was missing. That is exactly the
        # case that matters during a staged unlisted-release flow (publish
        # candidate, immediately unlist, pin REQUIRED_MODULE_VERSION in the
        # test repo, validate, then list) and during emergency rollbacks. A
        # YAML that references cmdlets / parameters added in the generated-
        # against version would otherwise fail with a confusing
        # 'parameter not found' or 'cmdlet not recognized' error mid-job
        # instead of a clear warning at install time.
        It 'Every pipeline YAML that installs the module also warns when installed < generated' {
            $examplesRoot = Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples'
            $examplesRoot = (Resolve-Path -Path $examplesRoot).Path

            $ymlFiles = Get-ChildItem -Path $examplesRoot -Recurse -Filter '*.yml' -File
            $ymlFiles.Count | Should -BeGreaterThan 0 -Because 'sample pipeline YAMLs ship under Automation-Pipeline-Examples/{github-actions,azure-devops}/'

            $issues = New-Object System.Collections.Generic.List[string]
            foreach ($yml in $ymlFiles) {
                $content = Get-Content -LiteralPath $yml.FullName -Raw

                # The drift detector only runs in pipelines that install the
                # module at runtime. Auth-smoke-test YAMLs and ITSM sample
                # YAMLs do not install the module, so they are not expected to
                # carry the check.
                $installsModule = $content -match 'Install-Module\s+@installArgs'
                if (-not $installsModule) { continue }

                # The drift guard has three equally valid emitter shapes:
                #   GH Actions inline: '::warning title=AzLocal.UpdateManagement is older than workflow YAML expects'
                #   Azure DevOps inline: '##vso[task.logissue type=warning]AzLocal.UpdateManagement v$installed is OLDER'
                #   v0.8.5 thin-YAML: Add-AzLocalPipelineVersionBanner (Public cmdlet that performs
                #                     the '$installed -lt $generated' comparison internally and emits
                #                     the warning via Write-AzLocalPipelineWarning).
                $hasComparison = $content -match '\$installed\s+-lt\s+\$generated'
                # Ignore the cmdlet name when it appears only inside a YAML comment
                # (lines beginning with optional whitespace then '#').
                $cmdletInvocationLines = ($content -split "`r?`n") | Where-Object {
                    ($_ -notmatch '^\s*#') -and ($_ -match 'Add-AzLocalPipelineVersionBanner')
                }
                $hasCmdlet = ($cmdletInvocationLines.Count -gt 0)

                $relPath = $yml.FullName.Substring($examplesRoot.Length).TrimStart('\','/')

                if ((-not $hasComparison) -and (-not $hasCmdlet)) {
                    $issues.Add("${relPath}: installs the module but is MISSING the 'installed -lt generated' drift guard (neither inline comparison nor Add-AzLocalPipelineVersionBanner call found)")
                }
            }

            if ($issues.Count -gt 0) {
                $detail = ($issues -join [Environment]::NewLine)
            } else {
                $detail = '(no findings)'
            }
            $issues.Count | Should -Be 0 -Because "every pipeline YAML under Automation-Pipeline-Examples/ that installs AzLocal.UpdateManagement must warn when the installed module version is older than GENERATED_AGAINST_MODULE_VERSION. Findings:$([Environment]::NewLine)$detail"
        }
    }

    Context 'Schedule-audit pipeline_path default is consumer-friendly (v0.7.66 regression)' {
        # v0.7.66 regression guard: apply-updates-schedule-audit.yml (GH + ADO)
        # shipped with a default pipeline_path of
        # 'AzLocal.UpdateManagement/Automation-Pipeline-Examples' - a path that
        # only exists in this module's source repo. In a consumer repo (where
        # apply-updates.yml lives under .github/workflows or .azure-pipelines),
        # the default-trigger run failed with
        #   PipelineYamlPath '...' does not exist on the runner
        # before the schedule advisor could emit JUnit XML. The defaults are
        # now '.github/workflows' on GH and '.azure-pipelines' on ADO.
        # This test guards both files from ever regressing to the in-source path.
        It 'Neither apply-updates-schedule-audit.yml defaults to the in-source examples folder' {
            $examplesRoot = Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples'
            $examplesRoot = (Resolve-Path -Path $examplesRoot).Path

            $auditYamls = @(
                Join-Path $examplesRoot 'github-actions\apply-updates-schedule-audit.yml'
                Join-Path $examplesRoot 'azure-devops\apply-updates-schedule-audit.yml'
            )

            $offenders = New-Object System.Collections.Generic.List[string]
            foreach ($yml in $auditYamls) {
                if (-not (Test-Path -LiteralPath $yml)) {
                    $offenders.Add("${yml}: file is missing (expected for the schedule-audit pair)")
                    continue
                }
                $content = Get-Content -LiteralPath $yml -Raw
                if ($content -match "AzLocal\.UpdateManagement/Automation-Pipeline-Examples") {
                    $offenders.Add("${yml}: still references the in-source path 'AzLocal.UpdateManagement/Automation-Pipeline-Examples'")
                }
            }

            $detail = if ($offenders.Count -gt 0) { $offenders -join [Environment]::NewLine } else { '(no offenders)' }
            $offenders.Count | Should -Be 0 -Because "the schedule-audit pipelines must default pipeline_path/pipelinePath to a consumer-realistic path (.github/workflows or .azure-pipelines), not to the in-source examples folder. Findings:$([Environment]::NewLine)$detail"
        }
    }

    Context 'Inline JUnit XML emitters carry a numeric time attribute (v0.7.93 NaNms regression)' {
        # NaNms regression guard: dorny/test-reporter (and most JUnit
        # renderers) parse the <testsuite>/<testcase> 'time' attribute as a
        # number. When the attribute is absent the renderer prints 'NaNms' in
        # the duration column and the column alignment breaks. The module's
        # own helper (Private/Export-ResultsToJUnitXml.ps1) emits time=
        # correctly, but the pipeline YAMLs under Automation-Pipeline-Examples/
        # hand-roll their own StringBuilder writers (one per Step.X yml) and
        # five of them (Step.0, Step.3, Step.4, Step.7, Step.9 - both GH and
        # ADO) shipped without time= on every emission. This test statically
        # scans every yml for <testsuite>/<testcase> lines and asserts each
        # carries time=. A single regex check that would have caught all 12
        # bug sites on day one.
        It 'Every <testsuites>/<testsuite>/<testcase> emission in every pipeline yml has a time= attribute' {
            $examplesRoot = Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples'
            $examplesRoot = (Resolve-Path -Path $examplesRoot).Path

            $ymlFiles = Get-ChildItem -Path $examplesRoot -Recurse -Filter '*.yml' -File
            $ymlFiles.Count | Should -BeGreaterThan 0 -Because 'sample pipeline YAMLs ship under Automation-Pipeline-Examples/{github-actions,azure-devops}/'

            $offenders = New-Object System.Collections.Generic.List[string]
            # Matches a JUnit opening tag through its closing '>' or '/>'.
            # We tolerate backtick-escaped quotes (PowerShell double-quoted
            # strings inside YAML run: blocks) and bare quotes (single-quoted
            # PowerShell strings or here-strings).
            $tagPattern = '<(?:testsuites|testsuite|testcase)\b[^>]*?/?>'
            foreach ($yml in $ymlFiles) {
                $relPath = $yml.FullName.Substring($examplesRoot.Length).TrimStart('\','/')
                $lineNo  = 0
                foreach ($line in (Get-Content -LiteralPath $yml.FullName)) {
                    $lineNo++
                    # Skip pure-comment lines and prose mentions of the tag.
                    $trim = $line.TrimStart()
                    if ($trim.StartsWith('#')) { continue }
                    foreach ($m in [regex]::Matches($line, $tagPattern)) {
                        if ($m.Value -notmatch 'time=') {
                            $offenders.Add(("{0}:{1}: missing time= attribute -> {2}" -f $relPath, $lineNo, $m.Value.Trim()))
                        }
                    }
                }
            }

            $detail = if ($offenders.Count -gt 0) { $offenders -join [Environment]::NewLine } else { '(no offenders)' }
            $offenders.Count | Should -Be 0 -Because "every <testsuites>/<testsuite>/<testcase> element emitted by an inline pipeline writer must carry a time= attribute (use time=`"0`" if no real duration is measured), otherwise dorny/test-reporter renders 'NaNms' in the duration column of the JUnit summary. Findings:$([Environment]::NewLine)$detail"
        }
    }

    Context 'v0.8.4 Node.js 24 opt-in across all GitHub Actions yml' {
        # v0.8.4: every bundled GitHub Actions workflow declares the
        # FORCE_JAVASCRIPT_ACTIONS_TO_NODE24 env var at the workflow level
        # so JavaScript actions (actions/checkout, azure/login,
        # actions/upload-artifact, dorny/test-reporter, etc.) execute under
        # Node 24 ahead of GitHub's platform-wide cutover. This drift test
        # guards against a future Copy-AzLocalPipelineExample / refresh
        # silently dropping the opt-in from any of the bundled yml templates.
        It 'Every GitHub Actions yml declares FORCE_JAVASCRIPT_ACTIONS_TO_NODE24: true at workflow scope' {
            $ghRoot = Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples\github-actions'
            $ghRoot = (Resolve-Path -Path $ghRoot).Path

            $ymlFiles = Get-ChildItem -Path $ghRoot -Filter '*.yml' -File
            $ymlFiles.Count | Should -BeGreaterOrEqual 10 -Because 'all 10 de-numbered pipeline templates are expected under Automation-Pipeline-Examples/github-actions/'

            $offenders = New-Object System.Collections.Generic.List[string]
            foreach ($yml in $ymlFiles) {
                $content = Get-Content -LiteralPath $yml.FullName -Raw
                if ($content -notmatch 'FORCE_JAVASCRIPT_ACTIONS_TO_NODE24\s*:\s*(?:true|''true''|"true")') {
                    $offenders.Add($yml.Name)
                }
            }

            $detail = if ($offenders.Count -gt 0) { $offenders -join ', ' } else { '(none)' }
            $offenders.Count | Should -Be 0 -Because "every GitHub Actions yml under Automation-Pipeline-Examples/github-actions/ must declare FORCE_JAVASCRIPT_ACTIONS_TO_NODE24: true so JavaScript actions execute under Node 24 ahead of GitHub's platform-wide deprecation cutover. Missing from: $detail"
        }
    }

    Context 'v0.8.4 module-version banner across every install step' {
        # v0.8.4: every install step in every bundled pipeline yml (GH + ADO)
        # emits a "Pipeline YAML v<g> | Module v<i> installed (<pin>) |
        # PSGallery latest <l> | <verdict>" banner to the rendered Summary
        # (GITHUB_STEP_SUMMARY on GH, ##vso[task.uploadsummary] on ADO).
        # This makes the version triple obvious in the Summary view fleet
        # operators open first, rather than buried in annotations.
        # v0.8.5 thin-YAML: ports replace the ~50-line inline banner block
        # with a single Add-AzLocalPipelineVersionBanner call (Public cmdlet
        # that produces the same banner string internally). Either form is
        # acceptable for these guards.
        It 'Every GitHub Actions install step contains the version banner string' {
            $ghRoot = Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples\github-actions'
            $ghRoot = (Resolve-Path -Path $ghRoot).Path
            $ymlFiles = Get-ChildItem -Path $ghRoot -Filter '*.yml' -File

            $bannerLiteral = [regex]::Escape('Pipeline YAML v$generated | Module v$installed installed')
            $cmdletCall    = [regex]::Escape('Add-AzLocalPipelineVersionBanner')
            $offenders = New-Object System.Collections.Generic.List[string]
            foreach ($yml in $ymlFiles) {
                $content = Get-Content -LiteralPath $yml.FullName -Raw
                if (($content -notmatch $bannerLiteral) -and ($content -notmatch $cmdletCall)) {
                    $offenders.Add($yml.Name)
                }
            }

            $detail = if ($offenders.Count -gt 0) { $offenders -join ', ' } else { '(none)' }
            $offenders.Count | Should -Be 0 -Because "every GitHub Actions yml install step must either inline the v0.8.4 banner string or call Add-AzLocalPipelineVersionBanner (v0.8.5 thin-YAML). Missing from: $detail"
        }

        It 'Every Azure DevOps yml install site contains the version banner string (Step.6 second install deliberately skips upload to avoid duplicate banner)' {
            $adoRoot = Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples\azure-devops'
            $adoRoot = (Resolve-Path -Path $adoRoot).Path
            $ymlFiles = Get-ChildItem -Path $adoRoot -Filter '*.yml' -File

            $bannerPattern = [regex]::Escape('Pipeline YAML v$generated | Module v$installed installed')
            $cmdletPattern = [regex]::Escape('Add-AzLocalPipelineVersionBanner')
            $totalSites = 0
            # Every Step.X.yml emits exactly ONE banner to the build Summary.
            # Step.6 has TWO install steps (CheckReadiness + ApplyUpdates) but
            # the second one deliberately skips ##vso[task.uploadsummary] so the
            # banner does not appear twice in the rendered Summary.
            # v0.8.5 thin-YAML: ported YAMLs replace the inline banner block
            # with one Add-AzLocalPipelineVersionBanner call - count either
            # form as a banner emit.
            $perFileExpect = @{
                'setup-validate-and-inventory.yml'  = 2
                'manage-updatering-tags.yml'        = 1
                'apply-updates-schedule-audit.yml' = 1
                'fleet-connectivity-status.yml'    = 1
                'assess-update-readiness.yml'      = 1
                'apply-updates.yml'                = 1
                'monitor-updates.yml'              = 1
                'fleet-update-status.yml'          = 1
                'fleet-health-status.yml'          = 1
                'sideload-updates.yml'             = 1
            }
            $offenders = New-Object System.Collections.Generic.List[string]
            foreach ($yml in $ymlFiles) {
                $content = Get-Content -LiteralPath $yml.FullName -Raw
                # Count cmdlet hits only on non-comment lines so a comment that
                # mentions Add-AzLocalPipelineVersionBanner does not double-count.
                $nonCommentLines = ($content -split "`r?`n") | Where-Object { $_ -notmatch '^\s*#' }
                $nonCommentText  = $nonCommentLines -join "`n"
                $bannerHits = ([regex]::Matches($nonCommentText, $bannerPattern)).Count
                $cmdletHits = ([regex]::Matches($nonCommentText, $cmdletPattern)).Count
                # The cmdlet call produces 1 banner per invocation; the inline
                # block produces 1 banner per Out-File of the literal. Count
                # both signals as banner emits.
                $count = $bannerHits + $cmdletHits
                $totalSites += $count
                if ($perFileExpect.ContainsKey($yml.Name)) {
                    $want = $perFileExpect[$yml.Name]
                    if ($count -ne $want) {
                        $offenders.Add(("{0}: expected {1} banner emit(s), found {2} (inline={3}, cmdlet={4})" -f $yml.Name, $want, $count, $bannerHits, $cmdletHits))
                    }
                }
            }

            $detail = if ($offenders.Count -gt 0) { $offenders -join [Environment]::NewLine } else { '(no mismatches)' }
            $offenders.Count | Should -Be 0 -Because "every ADO yml uploads exactly 1 version banner to the build Summary - via ##vso[task.uploadsummary] for the v0.8.4 inline form, or via Add-AzLocalPipelineVersionBanner for the v0.8.5 thin-YAML form. Step.6 has 2 install steps but the second (ApplyUpdates stage) deliberately skips the upload so the banner is not duplicated. Findings:$([Environment]::NewLine)$detail"
            $totalSites | Should -Be 11 -Because "total ADO Summary banner emits should be 11 (1 per yml; the apply-updates pipeline's second install step skips upload)"
        }
    }

    Context 'v0.8.5 Step.6 thin-YAML: apply-updates pipeline calls shared cmdlets' {
