            $content | Should -Match 'Add-AzLocalApplyUpdatesStepSummary' -Because 'ADO Step.6 Generate Summary task must call the apply-updates step-summary cmdlet'
            $content | Should -Match 'ApplyResultsJsonPath\s*=\s*"\$\(Build\.ArtifactStagingDirectory\)/apply-results\.json"' -Because 'ADO Step.6 Summary must pass apply-results.json so the Cluster Actions table can be rendered'
            $content | Should -Match 'ReadinessCsvPath\s*=\s*"\$\(Build\.ArtifactStagingDirectory\)/readiness-report\.csv"' -Because 'ADO Step.6 Summary must pass readiness-report.csv so the Clusters Skipped at Readiness Gate table can be rendered'
        }

        It 'GitHub Actions Step.6 yml invokes the schedule-resolver, readiness-gate, no-ready, and ITSM cmdlets in their respective steps' {
            $yml = Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples\github-actions\apply-updates.yml'
            $yml = (Resolve-Path -Path $yml).Path
            $content = Get-Content -LiteralPath $yml -Raw
            $content | Should -Match 'Resolve-AzLocalPipelineUpdateRing'        -Because 'Step.6 GH resolve-ring step must call Resolve-AzLocalPipelineUpdateRing (replaces the ~80-line inline resolver script)'
            $content | Should -Match 'Export-AzLocalClusterReadinessGateReport' -Because 'Step.6 GH readiness step must call Export-AzLocalClusterReadinessGateReport (replaces the ~80-line inline readiness gate script)'
            $content | Should -Match 'Add-AzLocalNoReadyClustersStepSummary'    -Because 'Step.6 GH no-clusters-ready job must call Add-AzLocalNoReadyClustersStepSummary (replaces the ~25-line inline summary script)'
            $content | Should -Match 'Invoke-AzLocalItsmTicketingFromArtifact'  -Because 'Step.6 GH Raise ITSM tickets step must call Invoke-AzLocalItsmTicketingFromArtifact (replaces the ~45-line inline ITSM script)'
        }

        It 'Azure DevOps Step.6 yml invokes the schedule-resolver, readiness-gate, no-ready, and ITSM cmdlets in their respective tasks' {
            $yml = Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples\azure-devops\apply-updates.yml'
            $yml = (Resolve-Path -Path $yml).Path
            $content = Get-Content -LiteralPath $yml -Raw
            $content | Should -Match 'Resolve-AzLocalPipelineUpdateRing'
            $content | Should -Match 'Export-AzLocalClusterReadinessGateReport'
            $content | Should -Match 'Add-AzLocalNoReadyClustersStepSummary'
            $content | Should -Match 'Invoke-AzLocalItsmTicketingFromArtifact'
        }
    }

    Context 'v0.8.5 Step.6 manual schedule-file input' {
        # v0.8.5: Step.6 (GH + ADO) gains two manual-run inputs that let an
        # operator trigger the apply-updates pipeline by hand BUT have it
        # resolve UpdateRing + AllowedUpdateVersions from apply-updates-schedule.yml
        # exactly as a scheduled run would (use_schedule_file / useScheduleFile),
        # optionally for a future UTC date (resolve_for_date_utc / resolveForDateUtc)
        # to preview a future cycleWeek/dayOfWeek. The pre-existing manual ring-name
        # path must still work verbatim when the new input is false (back-compat),
        # and the resolver must throw a helpful error when BOTH paths are empty.
        BeforeAll {
            $script:S6Gh  = (Resolve-Path (Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples\github-actions\apply-updates.yml')).Path
            $script:S6Ado = (Resolve-Path (Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples\azure-devops\apply-updates.yml')).Path
            $script:S6GhContent  = Get-Content -LiteralPath $script:S6Gh  -Raw
            $script:S6AdoContent = Get-Content -LiteralPath $script:S6Ado -Raw
        }

        It 'GH Step.6 declares the use_schedule_file workflow_dispatch input (boolean choice)' {
            $script:S6GhContent | Should -Match '(?m)^\s*use_schedule_file:\s*$' -Because 'v0.8.5 GH Step.6 must declare the new use_schedule_file input under workflow_dispatch.inputs'
            $script:S6GhContent | Should -Match "use_schedule_file:[\s\S]{0,400}?type:\s*choice[\s\S]{0,200}?-\s*'false'[\s\S]{0,100}?-\s*'true'" -Because 'use_schedule_file must be a choice between false and true'
        }

        It 'GH Step.6 declares the resolve_for_date_utc workflow_dispatch input' {
            $script:S6GhContent | Should -Match '(?m)^\s*resolve_for_date_utc:\s*$' -Because 'v0.8.5 GH Step.6 must declare the new resolve_for_date_utc input'
            $script:S6GhContent | Should -Match "resolve_for_date_utc:[\s\S]{0,400}?default:\s*''" -Because 'resolve_for_date_utc must default to empty (today UTC)'
        }

        It 'GH Step.6 update_ring is NO LONGER required (v0.8.5 drops required:true so use_schedule_file=true can stand alone)' {
            # match the update_ring block specifically, capturing through the next blank line / next input
            if ($script:S6GhContent -match "update_ring:\s*[\s\S]{0,800}?(?:\n\s*\n|\n      \w)") {
                $block = $Matches[0]
                $block | Should -Not -Match 'required:\s*true' -Because 'update_ring must NOT have required:true in v0.8.5 - use_schedule_file=true is an alternative path'
            } else {
                throw 'Could not locate update_ring block in GH Step.6'
            }
        }

        It 'GH Step.6 resolver step exposes USE_SCHEDULE_FILE and RESOLVE_FOR_DATE_UTC env vars' {
            $script:S6GhContent | Should -Match 'USE_SCHEDULE_FILE:\s*\$\{\{\s*github\.event\.inputs\.use_schedule_file\s*\}\}'
            $script:S6GhContent | Should -Match 'RESOLVE_FOR_DATE_UTC:\s*\$\{\{\s*github\.event\.inputs\.resolve_for_date_utc\s*\}\}'
        }

        It 'GH Step.6 resolver step invokes Resolve-AzLocalPipelineUpdateRing (v0.8.5 thin-YAML)' {
            # The ~80-line inline resolver block was replaced by a single
            # Resolve-AzLocalPipelineUpdateRing call. The cmdlet preserves
            # all prior behaviours byte-for-byte (back-compat manual ring,
            # schedule-file resolve, future-date preview via -ResolveForDateUtc,
            # hard-throw on missing schedule, per-host notice/warning when
            # no row matches today). Those behaviours are asserted in the
            # cmdlet-level Pester suite, not here.
            $script:S6GhContent | Should -Match 'Resolve-AzLocalPipelineUpdateRing' -Because 'Step.6 GH resolver step must call the v0.8.5 thin-YAML cmdlet'
        }

        It 'ADO Step.6 declares the useScheduleFile boolean parameter' {
            $script:S6AdoContent | Should -Match '(?m)^\s*-\s*name:\s*useScheduleFile' -Because 'v0.8.5 ADO Step.6 must declare the new useScheduleFile parameter'
            $script:S6AdoContent | Should -Match "useScheduleFile[\s\S]{0,400}?type:\s*boolean[\s\S]{0,200}?default:\s*false" -Because 'useScheduleFile must be a boolean defaulting to false'
        }

        It 'ADO Step.6 declares the resolveForDateUtc string parameter' {
            $script:S6AdoContent | Should -Match '(?m)^\s*-\s*name:\s*resolveForDateUtc'
            $script:S6AdoContent | Should -Match "resolveForDateUtc[\s\S]{0,400}?default:\s*''"
        }

        It 'ADO Step.6 resolveRing task exposes USE_SCHEDULE_FILE and RESOLVE_FOR_DATE_UTC env vars' {
            $script:S6AdoContent | Should -Match 'USE_SCHEDULE_FILE:\s*\$\{\{\s*parameters\.useScheduleFile\s*\}\}'
            $script:S6AdoContent | Should -Match 'RESOLVE_FOR_DATE_UTC:\s*\$\{\{\s*parameters\.resolveForDateUtc\s*\}\}'
        }

        It 'ADO Step.6 resolveRing task invokes Resolve-AzLocalPipelineUpdateRing (v0.8.5 thin-YAML)' {
            $script:S6AdoContent | Should -Match 'Resolve-AzLocalPipelineUpdateRing' -Because 'ADO Step.6 resolveRing task must call the v0.8.5 thin-YAML cmdlet'
        }
    }

    Context 'v0.8.79 Step.7 break-glass: force_immediate_update / forceImmediateUpdate' {
        # v0.8.79 introduces an operator-only override that bypasses the per-cluster
        # UpdateStartWindow / UpdateExclusionsWindow gate (Step 3c of Start-AzLocalClusterUpdate).
        # The override MUST NOT be reachable from the apply-updates-schedule.yml configuration
        # file - this is enforced by per-host wiring guards below.
        BeforeAll {
            $script:S6Gh78  = (Resolve-Path (Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples\github-actions\apply-updates.yml')).Path
            $script:S6Ado78 = (Resolve-Path (Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples\azure-devops\apply-updates.yml')).Path
            $script:S6Gh78Content  = Get-Content -LiteralPath $script:S6Gh78  -Raw
            $script:S6Ado78Content = Get-Content -LiteralPath $script:S6Ado78 -Raw
        }

        It 'GH Step.7 declares the force_immediate_update workflow_dispatch input (choice false/true, defaults false)' {
            $script:S6Gh78Content | Should -Match '(?m)^\s*force_immediate_update:\s*$' -Because 'v0.8.79 GH apply-updates must expose force_immediate_update as a workflow_dispatch input'
            $script:S6Gh78Content | Should -Match "force_immediate_update:[\s\S]{0,600}?type:\s*choice[\s\S]{0,200}?-\s*'false'[\s\S]{0,100}?-\s*'true'" -Because 'force_immediate_update must be a choice between false and true'
            $script:S6Gh78Content | Should -Match "force_immediate_update:[\s\S]{0,600}?default:\s*'false'" -Because 'force_immediate_update must default to false (opt-in only)'
        }

        It 'GH Step.7 input description starts with WARNING and flags MANUAL RUNS ONLY' {
            $script:S6Gh78Content | Should -Match "force_immediate_update:[\s\S]{0,200}?description:\s*'WARNING:" -Because 'GUI label must visibly call out the override risk'
            $script:S6Gh78Content | Should -Match 'force_immediate_update[\s\S]{0,600}?MANUAL RUNS ONLY' -Because 'description must state that schedule-triggered runs ignore the flag'
        }

        It 'GH Step.7 apply step env: clamps force_immediate_update to false on non-workflow_dispatch events (anti-injection)' {
            # The conditional MUST collapse to 'false' for any event other than workflow_dispatch
            # so a scheduled cron firing can never honour the override even if a YAML config
            # change ever tried to flip the default.
            $script:S6Gh78Content | Should -Match "INPUT_FORCE_IMMEDIATE_UPDATE:\s*\$\{\{\s*github\.event_name\s*==\s*'workflow_dispatch'\s*&&\s*github\.event\.inputs\.force_immediate_update\s*\|\|\s*'false'\s*\}\}" -Because 'env wiring must collapse to false for any non-workflow_dispatch trigger'
        }

        It 'GH Step.7 apply pwsh forwards INPUT_FORCE_IMMEDIATE_UPDATE to the cmdlet as -ForceImmediateUpdate' {
            $script:S6Gh78Content | Should -Match "if\s*\(\s*\`$env:INPUT_FORCE_IMMEDIATE_UPDATE\s*-eq\s*'true'\s*\)\s*\{\s*\`$params\['ForceImmediateUpdate'\]\s*=\s*\`$true\s*\}"
        }

        It 'ADO Step.7 declares the forceImmediateUpdate boolean parameter (defaults false)' {
            $script:S6Ado78Content | Should -Match '(?m)^\s*-\s*name:\s*forceImmediateUpdate' -Because 'v0.8.79 ADO apply-updates must expose forceImmediateUpdate as a top-level parameter'
            $script:S6Ado78Content | Should -Match "forceImmediateUpdate[\s\S]{0,600}?type:\s*boolean[\s\S]{0,200}?default:\s*false" -Because 'forceImmediateUpdate must be a boolean defaulting to false'
        }

        It 'ADO Step.7 forceImmediateUpdate displayName starts with WARNING and flags MANUAL QUEUE ONLY' {
            $script:S6Ado78Content | Should -Match "forceImmediateUpdate[\s\S]{0,300}?displayName:\s*'WARNING:" -Because 'GUI label must visibly call out the override risk'
            $script:S6Ado78Content | Should -Match 'forceImmediateUpdate[\s\S]{0,600}?MANUAL QUEUE ONLY' -Because 'displayName must state that schedule-triggered runs ignore the flag'
        }

        It 'ADO Step.7 apply task env: exposes FORCE_IMMEDIATE_UPDATE_PARAM and BUILD_REASON' {
            $script:S6Ado78Content | Should -Match 'FORCE_IMMEDIATE_UPDATE_PARAM:\s*\$\{\{\s*parameters\.forceImmediateUpdate\s*\}\}'
            $script:S6Ado78Content | Should -Match 'BUILD_REASON:\s*\$\(Build\.Reason\)'
        }

        It 'ADO Step.7 apply task pwsh enforces Build.Reason -eq Manual before honouring the override (anti-injection)' {
            # The runtime guard MUST verify Build.Reason='Manual' before flipping the switch;
            # any other reason (Schedule, IndividualCI, PullRequest, etc.) must log a warning
            # and skip the override regardless of the parameter value.
            $script:S6Ado78Content | Should -Match "if\s*\(\s*\`$env:FORCE_IMMEDIATE_UPDATE_PARAM\s*-eq\s*'True'\s*\)\s*\{[\s\S]{0,400}?\`$env:BUILD_REASON\s*-eq\s*'Manual'[\s\S]{0,200}?\`$params\['ForceImmediateUpdate'\]\s*=\s*\`$true"
        }

        It 'v0.9.15 GH resolve-ring step forwards force_immediate_update to the resolver (clamped to workflow_dispatch) so the allow-list is honoured' {
            # The resolve-ring step must clamp force to workflow_dispatch, exactly
            # like the apply step, so a scheduled firing can never activate it.
            $script:S6Gh78Content | Should -Match "INPUT_FORCE_IMMEDIATE_UPDATE:\s*\$\{\{\s*github\.event_name\s*==\s*'workflow_dispatch'\s*&&\s*github\.event\.inputs\.force_immediate_update\s*\|\|\s*'false'\s*\}\}" -Because 'the resolve-ring step must also clamp force to workflow_dispatch'
            $script:S6Gh78Content | Should -Match "if\s*\(\s*\`$env:INPUT_FORCE_IMMEDIATE_UPDATE\s*-eq\s*'true'\s*\)\s*\{\s*\`$params\['ForceImmediateUpdate'\]\s*=\s*\`$true\s*\}" -Because 'the resolve-ring step must forward the flag to Resolve-AzLocalPipelineUpdateRing'
        }

        It 'v0.9.15 ADO resolveRing task forwards forceImmediateUpdate (gated Build.Reason=Manual) to the resolver so the allow-list is honoured' {
            $script:S6Ado78Content | Should -Match 'FORCE_IMMEDIATE_UPDATE_PARAM:\s*\$\{\{\s*parameters\.forceImmediateUpdate\s*\}\}'
            $script:S6Ado78Content | Should -Match "\`$env:FORCE_IMMEDIATE_UPDATE_PARAM[\s\S]{0,300}?\`$env:BUILD_REASON\s*-eq\s*'Manual'[\s\S]{0,200}?\`$params\['ForceImmediateUpdate'\]\s*=\s*\`$true" -Because 'the resolveRing task must gate on Build.Reason=Manual before forwarding force'
        }

        It 'apply-updates-schedule.yml does NOT expose a force_immediate / forceImmediate field (override must be unreachable from the schedule config)' {
            # The schedule config GENERATOR and AUDIT must never learn about this
            # override - it must be unreachable from the apply-updates-schedule.yml
            # configuration file. Sweep those artefacts to make sure no future
            # refactor leaks the flag into the config surface.
            #
            # NOTE (v0.9.15): Resolve-AzLocalPipelineUpdateRing is DELIBERATELY
            # excluded from this sweep. The resolver now consumes an operator-
            # supplied -ForceImmediateUpdate PIPELINE parameter (gated to
            # workflow_dispatch / Build.Reason=Manual in the YAML) so that a
            # FORCE run still HONOURS the allowedUpdateVersions allow-list
            # instead of silently overriding it. The flag is never sourced from
            # the schedule config file itself - see the dedicated resolver
            # assertions below.
            $candidates = @(
                (Join-Path -Path $PSScriptRoot -ChildPath '..\Public\New-AzLocalApplyUpdatesScheduleConfig.ps1'),
                (Join-Path -Path $PSScriptRoot -ChildPath '..\Public\Get-AzLocalApplyUpdatesScheduleAudit.ps1')
            ) | Where-Object { Test-Path -LiteralPath $_ }
            foreach ($f in $candidates) {
                $raw = Get-Content -LiteralPath $f -Raw
                $raw | Should -Not -Match '(?i)force[_-]?immediate' -Because "$([IO.Path]::GetFileName($f)) must NOT reference the break-glass override (it is operator-only)"
            }
        }

        It 'v0.9.15 resolver honours the allow-list under force but never sources the force flag from the schedule config file' {
            $resolverPath = (Join-Path -Path $PSScriptRoot -ChildPath '..\Public\Resolve-AzLocalPipelineUpdateRing.ps1')
            $raw = Get-Content -LiteralPath $resolverPath -Raw
            # Consumes an operator-supplied pipeline switch...
            $raw | Should -Match '\[switch\]\$ForceImmediateUpdate' -Because 'the resolver must accept the operator-supplied force switch'
            # ...and uses it to resolve the ring-scoped allow-list (never to alter the ring).
            $raw | Should -Match 'Resolve-AzLocalForceAllowList' -Because 'force resolution must delegate to the ring-scoped allow-list helper'
            # The force flag must NOT be read out of the parsed schedule config object.
            $raw | Should -Not -Match '(?i)\$(cfg|forceCfg|Schedule)\.[A-Za-z]*force' -Because 'the force flag must never be sourced from the schedule config'
        }
    }

    Context 'v0.8.4 RBAC custom role display name rename' {
        # v0.8.4: the bundled custom role definition is renamed from
        # 'Azure Stack HCI Update Operator' to
        # 'Azure Stack HCI Update Operator (custom)' so the role's
        # customer-managed status is obvious in the Azure portal and pre-empts
        # collision with any future Microsoft built-in of the same brand name.
        # All currently-shipping docs (bundled JSON + Automation-Pipeline-Examples
        # README + Automation-Pipeline-Examples appendix + docs/rbac.md +
        # top-level README) must use the new name. CHANGELOG.md and
        # docs/release-history.md historical entries are intentionally
        # preserved verbatim (they describe what shipped at the time).
        It 'Bundled custom role JSON Name field is "Azure Stack HCI Update Operator (custom)"' {
            $jsonPath = Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples\azlocal-update-management-custom-role.json'
            $jsonPath = (Resolve-Path -Path $jsonPath).Path
            $role = Get-Content -LiteralPath $jsonPath -Raw | ConvertFrom-Json
            $role.Name | Should -BeExactly 'Azure Stack HCI Update Operator (custom)'
        }

        It 'New role display name appears in Automation-Pipeline-Examples/README.md, docs/rbac.md, and the top-level README' {
            $repoRoot = Join-Path -Path $PSScriptRoot -ChildPath '..'
            $files = @(
                'Automation-Pipeline-Examples\README.md',
                'docs\rbac.md',
                'README.md'
            )
            foreach ($f in $files) {
                $full = Join-Path -Path $repoRoot -ChildPath $f
                $content = Get-Content -LiteralPath $full -Raw
                $content | Should -Match 'Azure Stack HCI Update Operator \(custom\)' -Because "$f must reference the new role display name"
            }
        }

        It 'No currently-shipping doc references the bare pre-v0.8.4 role name without "(custom)" suffix' {
            # Allowlist: CHANGELOG.md and docs/release-history.md describe
            # historical releases and are preserved verbatim. The migration-tip
            # blockquote in Automation-Pipeline-Examples/README.md intentionally
            # quotes the pre-rename Name verbatim so consumers understand what
            # is being renamed - lines that contain 'pre-v0.8.4' are explicit
            # migration documentation and excluded from the check.
            $examplesRoot = Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples'
            $examplesRoot = (Resolve-Path -Path $examplesRoot).Path
            $docsRoot     = Join-Path -Path $PSScriptRoot -ChildPath '..\docs'
            $docsRoot     = (Resolve-Path -Path $docsRoot).Path

            $files = @()
            $files += Get-ChildItem -Path $examplesRoot -Recurse -Include '*.md' -File
            $files += Get-ChildItem -Path $docsRoot     -Recurse -Include '*.md' -File |
                Where-Object { $_.Name -ne 'release-history.md' }

            $offenders = New-Object System.Collections.Generic.List[string]
            foreach ($f in $files) {
                $relPath = $f.FullName.Substring((Split-Path $examplesRoot -Parent).Length).TrimStart('\','/')
                $lineNo = 0
                foreach ($line in (Get-Content -LiteralPath $f.FullName)) {
                    $lineNo++
                    # Match the bare role name only when NOT followed by ' (custom)'
                    if ($line -match 'Azure Stack HCI Update Operator(?! \(custom\))') {
                        # Allow explicit migration-tip references that document the rename.
                        if ($line -match 'pre-v0\.8\.4') { continue }
                        $offenders.Add(("{0}:{1}: {2}" -f $relPath, $lineNo, $line.Trim()))
                    }
                }
            }

            $detail = if ($offenders.Count -gt 0) { $offenders -join [Environment]::NewLine } else { '(no offenders)' }
            $offenders.Count | Should -Be 0 -Because "currently-shipping docs (Automation-Pipeline-Examples/**/*.md + docs/*.md except release-history.md) must reference the renamed role as 'Azure Stack HCI Update Operator (custom)' - except in migration-tip lines that contain 'pre-v0.8.4'. Findings:$([Environment]::NewLine)$detail"
        }
    }

    Context 'v0.8.92 RBAC checkUpdates action - granted via the updateSummaries/* wildcard' {
        # The "Check for updates" refresh - Sync-AzLocalClusterUpdateSummary and the
        # Export-AzLocalClusterUpdateReadinessReport stale-assessment auto-scan, which
        # the Update: 1 - Assess Update Readiness pipeline (assess-update-readiness.yml)
        # exercises - POSTs the ARM action
        # Microsoft.AzureStackHCI/clusters/updateSummaries/default/checkUpdates. Azure
        # ENFORCES the RBAC action
        # 'Microsoft.AzureStackHCI/clusters/updateSummaries/checkUpdates/action'
        # (confirmed verbatim from a live 403 AuthorizationFailed body). As of
        # 2026-06-18 that explicit leaf is NOT YET published in the
        # Microsoft.AzureStackHCI provider operations catalog (verified with az
        # provider operation show), and az role definition create/update REJECTS an
        # explicit unregistered action. The bundled least-privilege role therefore does
        # NOT enumerate the checkUpdates leaf directly; instead it grants the wildcard
        # 'Microsoft.AzureStackHCI/clusters/updateSummaries/*', which az ACCEPTS (its
        # prefix resolves to the registered updateSummaries/read) and which Azure
        # matches against the enforced checkUpdates/action at authorization time. The
        # wildcard also subsumes updateSummaries/read.
        #
        # These assertions are the tripwire that keeps the role JSON, the embedded role
        # blocks, and the RBAC docs consistent: the role must carry the wildcard, must
        # still grant the three explicit updates/* actions, and must NOT list the
        # checkUpdates leaf as an explicit Actions[] element (az would reject it).
        BeforeAll {
            $script:checkUpdatesAction = 'Microsoft.AzureStackHCI/clusters/updateSummaries/checkUpdates/action'
            $script:updateSummariesWildcard = 'Microsoft.AzureStackHCI/clusters/updateSummaries/*'
            $script:roleJsonPath = (Resolve-Path -Path (Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples\azlocal-update-management-custom-role.json')).Path
            $script:roleActions = (Get-Content -LiteralPath $script:roleJsonPath -Raw | ConvertFrom-Json).Actions
        }

        It 'Bundled role grants the updateSummaries/* wildcard plus the three explicit update actions (the documented minimum)' {
            $required = @(
                'Microsoft.AzureStackHCI/clusters/updateSummaries/*',
                'Microsoft.AzureStackHCI/clusters/updates/read',
                'Microsoft.AzureStackHCI/clusters/updates/apply/action',
                'Microsoft.AzureStackHCI/clusters/updates/updateRuns/read'
            )
            foreach ($action in $required) {
                $script:roleActions | Should -Contain $action -Because "the least-privilege role must grant the registered update action $action"
            }
        }

        It 'Bundled role grants checkUpdates via the wildcard, not as an explicit (catalog-unregistered) leaf' {
            # TRIPWIRE: the role must carry the updateSummaries/* wildcard (which Azure
            # matches against the enforced checkUpdates/action) but must NOT list the
            # explicit checkUpdates leaf, because az role definition create/update
            # rejects an action that is not yet in the Microsoft.AzureStackHCI
            # operations catalog (checked 2026-06-18). If checkUpdates later GAs you may
            # optionally swap the wildcard for the two explicit leaves - update this
            # test and docs/rbac.md, the Automation README, the top-level README, and
            # docs/cmdlet-reference.md together.
            $script:roleActions | Should -Contain $script:updateSummariesWildcard -Because 'the updateSummaries/* wildcard is how the least-privilege role grants the preview checkUpdates/action that Azure enforces but the operations catalog does not yet publish'
            $script:roleActions | Should -Not -Contain $script:checkUpdatesAction -Because 'the explicit checkUpdates leaf is not in the Microsoft.AzureStackHCI operations catalog (checked 2026-06-18), so az role definition create/update would reject it; it is granted via the updateSummaries/* wildcard instead'
        }

        It 'No bundled-role-adjacent JSON block (docs/rbac.md, Automation README) lists checkUpdates as an Actions[] element' {
            # The action string legitimately appears in PROSE notes (backtick-wrapped);
            # this check targets only the JSON array-element form ("...action") so a
            # stray addition to any embedded role JSON is caught without false matches
            # on the explanatory notes.
            $repoRoot = (Resolve-Path -Path (Join-Path -Path $PSScriptRoot -ChildPath '..')).Path
            $docFiles = @(
                'docs\rbac.md',
                'Automation-Pipeline-Examples\README.md'
            )
            $jsonElementPattern = '(?m)^\s*"Microsoft\.AzureStackHCI/clusters/updateSummaries/checkUpdates/action"'
            $offenders = New-Object System.Collections.Generic.List[string]
            foreach ($rel in $docFiles) {
                $content = Get-Content -LiteralPath (Join-Path -Path $repoRoot -ChildPath $rel) -Raw
                if ($content -match $jsonElementPattern) {
                    $offenders.Add($rel)
                }
            }
            $offenders.ToArray() | Should -BeNullOrEmpty -Because 'checkUpdates must not appear as a role JSON Actions[] element while it is absent from the bundled role and the operations catalog - keep the embedded role blocks consistent with azlocal-update-management-custom-role.json'
        }
    }
}

