Describe 'Regression: Get-AzLocalClusterInventory ValidatePattern shadowing' {
    # Repro for the bug where a local variable named $updateRingValue
    # inside Get-AzLocalClusterInventory aliased the function's
    # [ValidatePattern(...)] $UpdateRingValue parameter (PowerShell is
    # case-insensitive on variable names). Any cluster returned by ARG
    # without an UpdateRing tag caused Get-TagValue to return $null/''
    # and the assignment threw "The variable cannot be validated because
    # the value is not a valid value for the UpdateRingValue variable."
    # This bricked -AllClusters against any fleet missing the tag.

    It 'Should not throw "cannot be validated" when a cluster has no UpdateRing tag (-AllClusters)' {
        InModuleScope AzLocal.UpdateManagement {
            function global:az {
                param()
                $global:LASTEXITCODE = 0
                if ($args -contains 'show') {
                    return '{"id":"00000000-0000-0000-0000-000000000000","name":"sub"}'
                }
                return '{}'
            }
            Mock Test-AzCliAvailable { return $true }
            Mock Install-AzGraphExtension { return $true }
            # ARG returns two clusters - one with the tag, one without.
            Mock Invoke-AzResourceGraphQuery {
                return @(
                    [PSCustomObject]@{
                        id             = '/subscriptions/s/resourceGroups/r/providers/Microsoft.AzureStackHCI/clusters/tagged'
                        name           = 'tagged'
                        resourceGroup  = 'r'
                        subscriptionId = 's'
                        tags           = @{ UpdateRing = 'Wave1' }
                    },
                    [PSCustomObject]@{
                        id             = '/subscriptions/s/resourceGroups/r/providers/Microsoft.AzureStackHCI/clusters/untagged'
                        name           = 'untagged'
                        resourceGroup  = 'r'
                        subscriptionId = 's'
                        tags           = $null
                    }
                )
            }

            $result = $null
            { $script:inventoryResult = Get-AzLocalClusterInventory -PassThru } | Should -Not -Throw
            $result = $script:inventoryResult
            $result | Should -HaveCount 2
            ($result | Where-Object ClusterName -eq 'tagged').UpdateRing | Should -Be 'Wave1'
            ($result | Where-Object ClusterName -eq 'tagged').HasUpdateRingTag | Should -Be 'Yes'
            ($result | Where-Object ClusterName -eq 'untagged').UpdateRing | Should -Be ''
            ($result | Where-Object ClusterName -eq 'untagged').HasUpdateRingTag | Should -Be 'No'
        }
    }
}

Describe 'v0.8.83: Get-AzLocalClusterInventory preserves raw ARM tag bag on PassThru' {
    # v0.8.82 shipped Export-AzLocalUpdateRunMonitorReport's UpdateLastAttempt
    # reconciliation pass, which reads $inv.tags via PSObject.Properties['tags']
    # to find the audit tag. The Get-AzLocalClusterInventory projection in
    # v0.8.82 didn't carry .tags, so the reconciliation was silently always-empty
    # in production. v0.8.83 surfaces the raw .tags bag on every inventory row.
    # In-memory only - the on-disk CSV/JSON export uses an explicit $selectColumns
    # whitelist that excludes .tags, so this regression test also confirms that
    # exported CSV does NOT contain a 'tags' column.

    It 'PassThru output exposes raw ARM tags property on every cluster row' {
        InModuleScope AzLocal.UpdateManagement {
            function global:az {
                param()
                $global:LASTEXITCODE = 0
                if ($args -contains 'show') {
                    return '{"id":"00000000-0000-0000-0000-000000000000","name":"sub"}'
                }
                return '{}'
            }
            Mock Test-AzCliAvailable { return $true }
            Mock Install-AzGraphExtension { return $true }
            Mock Invoke-AzResourceGraphQuery {
                return @(
                    [PSCustomObject]@{
                        id             = '/subscriptions/s/resourceGroups/r/providers/Microsoft.AzureStackHCI/clusters/c1'
                        name           = 'c1'
                        resourceGroup  = 'r'
                        subscriptionId = 's'
                        tags           = @{
                            UpdateRing        = 'Wave1'
                            UpdateLastAttempt = '2026-06-14T21:28:23Z;UpdateStarted;Solution12.2605.1003.210;Update initiated successfully'
                            UpdateWindow      = 'Mon|18-22'
                        }
                    },
                    [PSCustomObject]@{
                        id             = '/subscriptions/s/resourceGroups/r/providers/Microsoft.AzureStackHCI/clusters/c2'
                        name           = 'c2'
                        resourceGroup  = 'r'
                        subscriptionId = 's'
                        tags           = $null
                    }
                )
            }

            $result = Get-AzLocalClusterInventory -PassThru
            $result | Should -HaveCount 2
            $c1 = $result | Where-Object ClusterName -eq 'c1'
            $c1.PSObject.Properties['tags'] | Should -Not -BeNullOrEmpty
            $c1.tags                        | Should -Not -BeNullOrEmpty
            $c1.tags['UpdateRing']          | Should -Be 'Wave1'
            $c1.tags['UpdateLastAttempt']   | Should -Be '2026-06-14T21:28:23Z;UpdateStarted;Solution12.2605.1003.210;Update initiated successfully'
            $c1.tags['UpdateWindow']        | Should -Be 'Mon|18-22'

            # Untagged cluster still gets a .tags property; value is $null/empty bag.
            $c2 = $result | Where-Object ClusterName -eq 'c2'
            $c2.PSObject.Properties['tags'] | Should -Not -BeNullOrEmpty
        }
    }

    It 'CSV/JSON export uses explicit $selectColumns whitelist that excludes the raw tags bag' {
        $src = Get-Content -Raw -LiteralPath "$PSScriptRoot/../Public/Get-AzLocalClusterInventory.ps1"
        # The whitelist must exist and must NOT name 'tags' (would leak the raw bag to artefacts).
        $src | Should -Match '\$selectColumns\s*='
        $whitelistMatch = [regex]::Match($src, '\$selectColumns\s*=\s*@\(([\s\S]*?)\)')
        $whitelistMatch.Success | Should -BeTrue -Because 'Get-AzLocalClusterInventory must declare an explicit $selectColumns whitelist for CSV/JSON export'
        $whitelistMatch.Groups[1].Value | Should -Not -Match "'tags'"
    }
}

Describe 'v0.8.84: Step.08 attempt-gap callout includes URP cluster-group recovery snippet' {
    # v0.8.84 extends the "What this means" callout under the
    # "Recent update attempts with no observable updateRun" section of
    # Export-AzLocalUpdateRunMonitorReport with a 3-step diagnosis flow
    # plus a fenced powershell block showing Get-ClusterGroup / Move-ClusterGroup
    # / Stop+Start-ClusterGroup recovery for the two URP cluster groups.
    # Source-level assertions (no end-to-end run needed) so this regression
    # catches accidental wording drift across releases.

    BeforeAll {
        $script:srcMonitor = Get-Content -Raw -LiteralPath "$PSScriptRoot/../Public/Export-AzLocalUpdateRunMonitorReport.ps1"
    }

    It 'Renders a numbered "Diagnosis (in order)" list' {
        $script:srcMonitor | Should -Match '\*\*Diagnosis \(in order\):\*\*'
        $script:srcMonitor | Should -Match '1\. \*\*Azure portal -> cluster blade -> Activity Log\*\*'
        $script:srcMonitor | Should -Match '2\. \*\*Azure portal -> cluster blade -> Updates\*\*'
        $script:srcMonitor | Should -Match '3\. \*\*URP service health'
    }

    It 'Names both URP cluster groups in the recovery snippet' {
        $script:srcMonitor | Should -Match "Azure Stack HCI Update Service Cluster Group"
        $script:srcMonitor | Should -Match "Azure Stack HCI Orchestrator Service Cluster Group"
    }

    It 'Recommends Get-ClusterGroup | Format-Table OwnerNode, State before any action' {
        # Source contains PS-escaped single quotes ('') because the markdown lines
        # are themselves built inside single-quoted strings. Allow one-or-two quote
        # characters in the regex so the assertion tolerates either rendering.
        $script:srcMonitor | Should -Match "Get-ClusterGroup\s+''?Azure Stack HCI Update Service Cluster Group''?,\s+''?Azure Stack HCI Orchestrator Service Cluster Group''?"
        $script:srcMonitor | Should -Match 'Format-Table Name, OwnerNode, State'
    }

    It 'Recommends Move-ClusterGroup for multi-node clusters' {
        $script:srcMonitor | Should -Match "Move-ClusterGroup ''?Azure Stack HCI Update Service Cluster Group''?"
    }

    It 'Recommends Stop-ClusterGroup + Start-ClusterGroup for single-node or as fallback' {
        $script:srcMonitor | Should -Match 'Stop-ClusterGroup'
        $script:srcMonitor | Should -Match 'Start-ClusterGroup'
    }

    It 'Warns that ECE Orchestrator group must NOT be bounced during a healthy in-flight run' {
        $script:srcMonitor | Should -Match 'only if no updateRun is actively in progress'
    }

    It 'Does NOT pass -Verbose to the cluster-group cmdlets (Format-Table is more diagnostic)' {
        # -Verbose adds noise but does not surface OwnerNode/State; the Format-Table line does.
        # Catch regressions where someone adds -Verbose back to Move/Stop/Start-ClusterGroup.
        $callsiteMatches = [regex]::Matches($script:srcMonitor, '(Move-ClusterGroup|Stop-ClusterGroup|Start-ClusterGroup)\s+-Verbose')
        $callsiteMatches.Count | Should -Be 0 -Because '-Verbose was intentionally dropped from the URP recovery snippet in v0.8.84'
    }
}

Describe 'Function: Set-AzLocalClusterUpdateRingTag' {
    
    Context 'Parameter Validation' {
        BeforeAll {
            $command = Get-Command Set-AzLocalClusterUpdateRingTag
        }

        It 'Should have ClusterResourceIds parameter' {
            $command.Parameters.Keys | Should -Contain 'ClusterResourceIds'
        }

        It 'Should have UpdateRingValue parameter' {
