        }

        It 'Should support ShouldProcess' {
            $attr = $command.ScriptBlock.Attributes | Where-Object { $_.TypeId.Name -eq 'CmdletBindingAttribute' }
            $attr.SupportsShouldProcess | Should -Be $true
        }
    }

    Context 'Parameter Sets' {
        BeforeAll {
            $command = Get-Command Set-AzLocalClusterUpdateRingTag
        }

        It 'Should have ByResourceId parameter set' {
            $command.ParameterSets.Name | Should -Contain 'ByResourceId'
        }

        It 'Should have ByCsv parameter set' {
            $command.ParameterSets.Name | Should -Contain 'ByCsv'
        }

        It 'ClusterResourceIds should be mandatory in ByResourceId parameter set' {
            $param = $command.Parameters['ClusterResourceIds']
            $attr = $param.Attributes | Where-Object { $_.TypeId.Name -eq 'ParameterAttribute' -and $_.ParameterSetName -eq 'ByResourceId' }
            $attr.Mandatory | Should -Be $true
        }

        It 'InputCsvPath should be mandatory in ByCsv parameter set' {
            $param = $command.Parameters['InputCsvPath']
            $attr = $param.Attributes | Where-Object { $_.TypeId.Name -eq 'ParameterAttribute' -and $_.ParameterSetName -eq 'ByCsv' }
            $attr.Mandatory | Should -Be $true
        }
    }

    Context 'OutputType' {
        It 'Should have OutputType of PSObject[]' {
            $outputTypes = (Get-Command Set-AzLocalClusterUpdateRingTag).OutputType
            $outputTypes.Type.FullName | Should -Contain 'System.Management.Automation.PSObject[]'
        }
    }

    Context 'v0.7.69 logging contract' {
        # Source-level checks - the function performs Azure CLI calls so deep
        # behavioral mocking is fragile. These pin the new logging surface that
        # operators see in the Step.2 pipeline output.
        BeforeAll {
            $script:setRingSource = Get-Content -Raw -LiteralPath (Join-Path $PSScriptRoot '..\Public\Set-AzLocalClusterUpdateRingTag.ps1')
        }

        It 'Emits a friendly "Processing: <clusterName>" header derived from the resource ID' {
            $script:setRingSource | Should -Match 'Processing:\s*\$headerClusterName'
            $script:setRingSource | Should -Match '\$headerClusterName\s*=\s*\(\$resourceId\s*-split\s*''/''\)\[-1\]'
        }

        It 'Emits the full ARM Resource ID on a dedicated line for traceability' {
            $script:setRingSource | Should -Match 'ARM Resource ID:\s*\$resourceId'
        }

        It 'Logs Info (not Warning) when the existing UpdateRing tag matches the target' {
            # The flip is gated on `if ($previousTagValue -eq $currentUpdateRingValue) { ... Level Info }`
            $script:setRingSource | Should -Match '\$previousTagValue\s*-eq\s*\$currentUpdateRingValue'
            $script:setRingSource | Should -Match "matches target.*-Level\s+Info"
        }

        It 'Still emits Warning when the existing UpdateRing tag differs from the target' {
            $script:setRingSource | Should -Match "differs from target.*-Level\s+Warning"
        }

        It 'Steady-state skip path logs Info (not Warning) when UpdateRing matches AND no schedule diff' {
            # The misleading "use -Force to overwrite" warning previously fired even when
            # the cluster had nothing to overwrite (UpdateRing already correct, schedule
            # tags already correct). The skip branch now splits on $previousTagValue eq target.
            $script:setRingSource | Should -Match 'All managed tags already match desired state.*-Level\s+Info'
            $script:setRingSource | Should -Match '\$action\s*=\s*"NoChange"'
            $script:setRingSource | Should -Match '\$status\s*=\s*"AlreadyInSync"'
        }

        It 'Overwrite-blocked skip path still emits Warning + -Force hint when UpdateRing differs and no schedule diff' {
            $script:setRingSource | Should -Match 'UpdateRing differs from target.*use -Force.*-Level\s+Warning'
        }

        It 'Summary section tallies AlreadyInSync as its own bucket' {
            $script:setRingSource | Should -Match '\$alreadyInSync\s*=\s*@\(\$results\s*\|\s*Where-Object\s*\{\s*\$_\.Status\s*-eq\s*"AlreadyInSync"\s*\}\)\.Count'
            $script:setRingSource | Should -Match 'Already in sync \(no change needed\):'
        }

        It 'Force mode short-circuits when all managed tags already match (no wasted PATCH)' {
            $script:setRingSource | Should -Match 'Force mode enabled but all managed tags already match desired state'
            $script:setRingSource | Should -Match '-Force PATCH skipped'
        }

        It 'Per-cluster Message names the tags that actually changed (v0.8.6 regression guard)' {
            # v0.8.6 fix: when only a schedule tag (e.g. UpdateExcluded) changed, the
            # message previously read "UpdateRing tag updated successfully" which was
            # misleading. The success message now includes the actual per-tag deltas
            # computed from $currentTags vs $tagsToMerge.
            $script:setRingSource | Should -Match '\$tagDeltas\s*=\s*New-Object\s+System\.Collections\.Generic\.List\[string\]'
            $script:setRingSource | Should -Match 'foreach\s*\(\s*\$tagName\s+in\s+\$tagsToMerge\.Keys\s*\)'
            $script:setRingSource | Should -Match "Tags \$\(\`$action\.ToLower\(\)\): "
        }

        It 'Format-Table output is routed to Out-Host so formatter objects do not leak into -PassThru (v0.8.6 regression guard)' {
            # v0.8.6 fix: $results | Format-Table -AutoSize was leaking format-table
            # wrapper objects (header / row / footer) into the function's pipeline
            # output. Caller `$results = @(Set-AzLocal... )` then saw ~1.2x as many
            # objects as real cluster rows, inflating Step.2 summary counts (44 vs
            # 20 on a 20-row CSV). Fix: pipe Format-Table to Out-Host explicitly.
            $script:setRingSource | Should -Match 'Format-Table[^|]+-AutoSize\s*\|\s*Out-Host'
        }
    }
}

