Describe 'Helper Function: Get-AzLocalRunEndTime (Internal)' {

    It 'Should return progress.endTimeUtc when present (preferred source)' {
        InModuleScope AzLocal.UpdateManagement {
            $props = [PSCustomObject]@{
                state           = 'Succeeded'
                lastUpdatedTime = '2026-04-25T00:48:30Z'
                progress        = [PSCustomObject]@{ endTimeUtc = '2026-04-25T00:48:10Z' }
            }
            $r = Get-AzLocalRunEndTime -props $props
            $r | Should -Not -BeNullOrEmpty
            $r.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss') | Should -Be '2026-04-25T00:48:10'
        }
    }

    It 'Should fall back to lastUpdatedTime when progress.endTimeUtc is missing' {
        InModuleScope AzLocal.UpdateManagement {
            $props = [PSCustomObject]@{
                state           = 'Failed'
                lastUpdatedTime = '2026-04-09T15:30:00Z'
                progress        = [PSCustomObject]@{ endTimeUtc = $null }
            }
            $r = Get-AzLocalRunEndTime -props $props
            $r | Should -Not -BeNullOrEmpty
            $r.ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ss') | Should -Be '2026-04-09T15:30:00'
        }
    }

    It 'Should return $null for InProgress runs (no terminal end yet)' {
        InModuleScope AzLocal.UpdateManagement {
            $props = [PSCustomObject]@{
                state           = 'InProgress'
                lastUpdatedTime = '2026-04-25T01:00:00Z'
                progress        = [PSCustomObject]@{ endTimeUtc = $null }
            }
            $r = Get-AzLocalRunEndTime -props $props
            $r | Should -BeNullOrEmpty
        }
    }

    It 'Should return $null when both sources are missing' {
        InModuleScope AzLocal.UpdateManagement {
            $props = [PSCustomObject]@{ state = 'Succeeded' }
            $r = Get-AzLocalRunEndTime -props $props
            $r | Should -BeNullOrEmpty
        }
    }
}

Describe 'Helper Function: Format-AzLocalUpdateRun (Internal)' {

    It 'Should populate EndTime from progress.endTimeUtc and use ARM duration' {
        InModuleScope AzLocal.UpdateManagement {
            $run = [PSCustomObject]@{
                id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/c1/updates/Solution12.2604/updateRuns/abc123'
                name       = 'abc123'
                properties = [PSCustomObject]@{
                    state           = 'Succeeded'
                    timeStarted     = '2026-04-24T16:10:24Z'
                    lastUpdatedTime = '2026-04-25T00:48:30Z'
                    duration        = 'PT8H37M58S'
                    progress        = [PSCustomObject]@{
                        endTimeUtc = '2026-04-25T00:48:10Z'
                        steps      = @([PSCustomObject]@{ name = 'Step1'; status = 'Success' })
                    }
                    location        = 'eastus'
                }
            }
            $f = Format-AzLocalUpdateRun -run $run -clusterName 'c1'
            # EndTime is rendered in local time; compare via parse + UTC normalize
            ([datetime]::ParseExact($f.EndTime, 'yyyy-MM-dd HH:mm', $null)).ToUniversalTime().ToString('yyyy-MM-dd HH:mm') | Should -Be '2026-04-25 00:48'
            ([datetime]::ParseExact($f.StartTime, 'yyyy-MM-dd HH:mm', $null)).ToUniversalTime().ToString('yyyy-MM-dd HH:mm') | Should -Be '2026-04-24 16:10'
            $f.State | Should -Be 'Succeeded'
            $f.Duration | Should -Match '8 hours'
        }
    }

    It 'Should leave EndTime blank for InProgress runs' {
        InModuleScope AzLocal.UpdateManagement {
            $run = [PSCustomObject]@{
                id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/c1/updates/Solution12.2604/updateRuns/abc123'
                name       = 'abc123'
                properties = [PSCustomObject]@{
                    state           = 'InProgress'
                    timeStarted     = (Get-Date).AddMinutes(-30).ToUniversalTime().ToString('o')
                    lastUpdatedTime = $null
                    duration        = $null
                    progress        = [PSCustomObject]@{
                        endTimeUtc = $null
                        steps      = @([PSCustomObject]@{ name = 'Step1'; status = 'InProgress' })
                    }
                    location        = 'eastus'
                }
            }
            $f = Format-AzLocalUpdateRun -run $run -clusterName 'c1'
            $f.EndTime | Should -BeNullOrEmpty
            $f.Duration | Should -Match 'running'
        }
    }

    It 'Should surface Status from properties.progress.status (v0.7.96)' {
        InModuleScope AzLocal.UpdateManagement {
            $run = [PSCustomObject]@{
                id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/c1/updates/Solution12.2604/updateRuns/r1'
                name       = 'r1'
                properties = [PSCustomObject]@{
                    state           = 'InProgress'
                    timeStarted     = (Get-Date).AddMinutes(-30).ToUniversalTime().ToString('o')
                    lastUpdatedTime = $null
                    duration        = $null
                    progress        = [PSCustomObject]@{
                        status = 'Error'
                        steps  = @([PSCustomObject]@{ name = 'Start update'; status = 'Error'; errorMessage = '' })
                    }
                    location        = 'eastus'
                }
            }
            $f = Format-AzLocalUpdateRun -run $run -clusterName 'c1'
            $f.Status | Should -Be 'Error'
            $f.State  | Should -Be 'InProgress'
        }
    }

    It 'Should leave Status empty when progress has no status field (v0.7.96)' {
        InModuleScope AzLocal.UpdateManagement {
            $run = [PSCustomObject]@{
                id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/c1/updates/Solution12.2604/updateRuns/r2'
                name       = 'r2'
                properties = [PSCustomObject]@{
                    state           = 'Succeeded'
                    timeStarted     = '2026-04-24T16:10:24Z'
                    lastUpdatedTime = '2026-04-24T17:10:24Z'
                    duration        = 'PT1H'
                    progress        = [PSCustomObject]@{
                        endTimeUtc = '2026-04-24T17:10:24Z'
                        steps      = @([PSCustomObject]@{ name = 'Step1'; status = 'Success' })
                    }
                    location        = 'eastus'
                }
            }
            $f = Format-AzLocalUpdateRun -run $run -clusterName 'c1'
            $f.Status | Should -BeNullOrEmpty
        }
    }

    It 'Should walk steps tree to find deepest ErrorMessage (v0.7.96)' {
        InModuleScope AzLocal.UpdateManagement {
            $run = [PSCustomObject]@{
                id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/c1/updates/Solution12.2604/updateRuns/r3'
                name       = 'r3'
                properties = [PSCustomObject]@{
                    state           = 'Failed'
                    timeStarted     = '2026-04-24T16:10:24Z'
                    lastUpdatedTime = '2026-04-24T17:10:24Z'
                    duration        = 'PT1H'
                    progress        = [PSCustomObject]@{
                        status = 'Error'
                        steps  = @(
                            [PSCustomObject]@{
                                name         = 'Outer'
                                status       = 'Failed'
                                errorMessage = 'outer rolled-up'
                                steps        = @(
                                    [PSCustomObject]@{
                                        name         = 'Inner'
                                        status       = 'Error'
                                        errorMessage = 'deep root cause message'
                                    }
                                )
                            }
                        )
                    }
                    location        = 'eastus'
                }
            }
            $f = Format-AzLocalUpdateRun -run $run -clusterName 'c1'
            $f.ErrorMessage | Should -Be 'deep root cause message'
        }
    }

    It 'Should leave ErrorMessage empty when no step is Error/Failed (v0.7.96)' {
        InModuleScope AzLocal.UpdateManagement {
            $run = [PSCustomObject]@{
                id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/c1/updates/Solution12.2604/updateRuns/r4'
                name       = 'r4'
                properties = [PSCustomObject]@{
                    state           = 'InProgress'
                    timeStarted     = (Get-Date).AddMinutes(-30).ToUniversalTime().ToString('o')
                    lastUpdatedTime = $null
                    duration        = $null
                    progress        = [PSCustomObject]@{
                        status = 'InProgress'
                        steps  = @([PSCustomObject]@{ name = 'Step1'; status = 'InProgress' })
                    }
                    location        = 'eastus'
                }
            }
            $f = Format-AzLocalUpdateRun -run $run -clusterName 'c1'
            $f.ErrorMessage | Should -BeNullOrEmpty
        }
    }

    It 'CurrentStep reflects the deepest InProgress step, not the top-level wrapper (Step.7 monitor fix)' {
        InModuleScope AzLocal.UpdateManagement {
            # Real Azure Local progress trees nest a coarse top-level wrapper step
            # (e.g. "Start update") that stays InProgress for the whole run. CurrentStep
            # must dig to the deepest active leaf so the in-flight monitor shows the real
            # current activity instead of always showing the wrapper name.
            $run = [PSCustomObject]@{
                id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/c1/updates/Solution12.2604/updateRuns/rDeep'
                name       = 'rDeep'
                properties = [PSCustomObject]@{
                    state           = 'InProgress'
                    timeStarted     = (Get-Date).AddMinutes(-30).ToUniversalTime().ToString('o')
                    lastUpdatedTime = $null
                    duration        = $null
                    progress        = [PSCustomObject]@{
                        status = 'InProgress'
                        steps  = @(
                            [PSCustomObject]@{
                                name   = 'Start update'
                                status = 'InProgress'
                                steps  = @(
                                    [PSCustomObject]@{
                                        name   = 'Update Cluster'
                                        status = 'InProgress'
                                        steps  = @(
                                            [PSCustomObject]@{ name = 'Update Node 2'; status = 'InProgress' }
                                        )
                                    }
                                )
                            }
                        )
                    }
                    location        = 'eastus'
                }
            }
            $f = Format-AzLocalUpdateRun -run $run -clusterName 'c1'
            $f.CurrentStep | Should -Be 'Update Node 2'
        }
    }

    It 'CurrentStep reflects the deepest Failed step with (FAILED) suffix, not the top-level wrapper (Step.7 monitor fix)' {
        InModuleScope AzLocal.UpdateManagement {
            $run = [PSCustomObject]@{
                id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/c1/updates/Solution12.2604/updateRuns/rDeepFail'
                name       = 'rDeepFail'
                properties = [PSCustomObject]@{
                    state           = 'Failed'
                    timeStarted     = '2026-04-24T16:10:24Z'
                    lastUpdatedTime = '2026-04-24T17:10:24Z'
                    duration        = 'PT1H'
                    progress        = [PSCustomObject]@{
                        status = 'Error'
                        steps  = @(
                            [PSCustomObject]@{
                                name   = 'Start update'
                                status = 'Error'
                                steps  = @(
                                    [PSCustomObject]@{
                                        name         = 'Run Pre Update Validation'
                                        status       = 'Error'
                                        errorMessage = 'validation failed'
                                    }
                                )
                            }
                        )
                    }
                    location        = 'eastus'
                }
            }
            $f = Format-AzLocalUpdateRun -run $run -clusterName 'c1'
            $f.CurrentStep | Should -Be 'Run Pre Update Validation (FAILED)'
        }
    }

    Context 'Strict-mode: tolerates failed-run properties missing location / steps / progress (v0.9.17)' {

        It 'Does not throw when properties omits location (regression: Arizona retry)' {
            InModuleScope AzLocal.UpdateManagement {
                $run = [PSCustomObject]@{
                    id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/c1/updates/Solution12.2604/updateRuns/rNoLoc'
                    name       = 'rNoLoc'
                    properties = [PSCustomObject]@{
                        state       = 'Failed'
                        timeStarted = '2026-04-24T16:10:24Z'
                        duration    = 'PT1H'
                        progress    = [PSCustomObject]@{
                            status = 'Error'
                            steps  = @([PSCustomObject]@{ name = 'Step1'; status = 'Error'; errorMessage = 'boom' })
                        }
                        # NOTE: no 'location' property (real failed runs can omit it).
                    }
                }
                $f = Format-AzLocalUpdateRun -run $run -clusterName 'c1'
                $f.Location     | Should -Be ''
                $f.ErrorMessage | Should -Be 'boom'
            }
        }

        It 'Does not throw when progress omits steps (regression: Tacoma retry)' {
            InModuleScope AzLocal.UpdateManagement {
                $run = [PSCustomObject]@{
                    id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/c1/updates/Solution12.2604/updateRuns/rNoSteps'
                    name       = 'rNoSteps'
                    properties = [PSCustomObject]@{
                        state       = 'Failed'
                        timeStarted = '2026-04-24T16:10:24Z'
                        duration    = 'PT1H'
                        location    = 'eastus'
                        progress    = [PSCustomObject]@{
                            status = 'Error'
                            # NOTE: no 'steps' property (progress present but empty).
                        }
                    }
                }
                $f = Format-AzLocalUpdateRun -run $run -clusterName 'c1'
                $f.Status   | Should -Be 'Error'
                $f.Progress | Should -Be ''
            }
        }

        It 'Does not throw when properties omits progress entirely' {
            InModuleScope AzLocal.UpdateManagement {
                $run = [PSCustomObject]@{
                    id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/c1/updates/Solution12.2604/updateRuns/rNoProg'
                    name       = 'rNoProg'
                    properties = [PSCustomObject]@{
                        state       = 'Failed'
                        timeStarted = '2026-04-24T16:10:24Z'
                        duration    = 'PT1H'
                        location    = 'eastus'
                        # NOTE: no 'progress' property at all.
                    }
                }
                $f = Format-AzLocalUpdateRun -run $run -clusterName 'c1'
                $f.Status   | Should -BeNullOrEmpty
                $f.Location | Should -Be 'eastus'
            }
        }

        It 'Does not throw when progress.steps holds LEAF steps that omit the steps child (regression: Tacoma bae9704e / v0.9.18)' {
            InModuleScope AzLocal.UpdateManagement {
                # Set strict mode inside module scope to mirror the production caller
                # Invoke-AzLocalReadinessGatedFailedUpdateRetry (line 98), which is what
                # made the recursive step-walkers throw on Tacoma's real failed run whose
                # top-level steps are LEAF nodes with NO `steps` property.
                Set-StrictMode -Version Latest
                $run = [PSCustomObject]@{
                    id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/Tacoma/updates/Solution12.2606/updateRuns/rLeaf'
                    name       = 'rLeaf'
                    properties = [PSCustomObject]@{
                        state       = 'Failed'
                        timeStarted = '2026-07-02T23:42:12Z'
                        duration    = 'PT10M'
                        location    = 'eastus'
                        progress    = [PSCustomObject]@{
                            status = 'Error'
                            steps  = @(
                                [PSCustomObject]@{ name = 'Downloading update'; status = 'Success' }        # no 'steps' child
                                [PSCustomObject]@{ name = 'Update is blocked due to health check failure'; status = 'Failed'; errorMessage = 'health check failed' }  # no 'steps' child
                                [PSCustomObject]@{ name = 'Initiating update installation.'; status = 'NotStarted' }  # no 'steps' child
                            )
                        }
                    }
                }
                { Format-AzLocalUpdateRun -run $run -clusterName 'Tacoma' } | Should -Not -Throw
                $f = Format-AzLocalUpdateRun -run $run -clusterName 'Tacoma'
                $f.CurrentStep  | Should -Be 'Update is blocked due to health check failure (FAILED)'
                $f.ErrorMessage | Should -Be 'health check failed'
            }
        }

        It 'The recursive step-walkers do not throw on leaf steps missing the steps child (v0.9.18)' {
            InModuleScope AzLocal.UpdateManagement {
                Set-StrictMode -Version Latest
                $steps = @(
                    $null
                    [PSCustomObject]@{ name = 'a'; status = 'Success' }
                    [PSCustomObject]@{
                        name = 'parent'; status = 'Failed'
                        steps = @($null, [PSCustomObject]@{ name = 'b'; status = 'Failed'; errorMessage = 'boom' })
                    }
                )
                $active = $null
                { $active = Get-DeepestActiveStep -Steps $steps } | Should -Not -Throw
                (Get-DeepestActiveStep -Steps $steps).name | Should -Be 'b'
                { Get-CurrentStepPath -Steps $steps -IncludeErrorMessage } | Should -Not -Throw
                (Get-CurrentStepPath -Steps $steps -IncludeErrorMessage) | Should -Match 'b : boom'
                { Get-DeepestErrorMessage -Steps $steps } | Should -Not -Throw
                (Get-DeepestErrorMessage -Steps $steps) | Should -Be 'boom'
            }
        }
    }

    Context 'Progress reflects deep leaf steps, not the top-level wrapper (v0.8.74)' {

        It 'Progress counts deep leaf steps and a percentage, not the coarse top-level 1/2' {
            InModuleScope AzLocal.UpdateManagement {
                # Real Azure Local runs expose only 2 top-level steps ("Prepare update" Success
                # + "Start update" InProgress), so the OLD top-level count always rendered
                # "1/2 steps" for the whole multi-hour run. The deep tree below has 4 leaf steps
                # (3 Success + 1 InProgress) -> Progress must read 3/4 (75%).
                $run = [PSCustomObject]@{
                    id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/c1/updates/Sol/updateRuns/rProg'
                    name       = 'rProg'
                    properties = [PSCustomObject]@{
                        state    = 'InProgress'
                        progress = [PSCustomObject]@{
                            status = 'InProgress'
                            steps  = @(
                                [PSCustomObject]@{ name = 'Prepare update'; status = 'Success' }
                                [PSCustomObject]@{
                                    name   = 'Start update'
                                    status = 'InProgress'
                                    steps  = @(
                                        [PSCustomObject]@{
                                            name   = 'Update Cluster'
                                            status = 'InProgress'
                                            steps  = @(
                                                [PSCustomObject]@{ name = 'Update Node 1'; status = 'Success' }
                                                [PSCustomObject]@{ name = 'Update Node 2'; status = 'Success' }
                                                [PSCustomObject]@{ name = 'Update Node 3'; status = 'InProgress' }
                                            )
                                        }
                                    )
                                }
                            )
                        }
                        location = 'eastus'
                    }
                }
                $f = Format-AzLocalUpdateRun -run $run -clusterName 'c1'
                $f.Progress | Should -Be '3/4 steps (75%)'
            }
        }

        It 'Progress appends a failed-leaf count when the deep tree has Error/Failed leaves' {
            InModuleScope AzLocal.UpdateManagement {
                $run = [PSCustomObject]@{
                    id         = '/subscriptions/x/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/c1/updates/Sol/updateRuns/rFail'
                    name       = 'rFail'
                    properties = [PSCustomObject]@{
                        state    = 'Failed'
                        progress = [PSCustomObject]@{
                            status = 'Error'
                            steps  = @(
                                [PSCustomObject]@{ name = 'Prepare update'; status = 'Success' }
                                [PSCustomObject]@{
                                    name   = 'Start update'
                                    status = 'Error'
                                    steps  = @(
                                        [PSCustomObject]@{ name = 'Step A'; status = 'Success' }
                                        [PSCustomObject]@{ name = 'Step B'; status = 'Error' }
                                    )
                                }
                            )
                        }
                        location = 'eastus'
                    }
                }
                $f = Format-AzLocalUpdateRun -run $run -clusterName 'c1'
                $f.Progress | Should -Be '2/3 steps (67%), 1 failed'
            }
        }
    }
}

Describe 'Helper Function: Get-AzLocalUpdateRunStepStats (Internal)' {

    It 'Should return all-zero stats for an empty steps array' {
        InModuleScope AzLocal.UpdateManagement {
            $s = Get-AzLocalUpdateRunStepStats -Steps @()
            $s.TotalLeaf | Should -Be 0
            $s.CompletedLeaf | Should -Be 0
            $s.InProgressLeaf | Should -Be 0
            $s.FailedLeaf | Should -Be 0
        }
    }

    It 'Should ignore null elements at top-level and nested step arrays' {
        InModuleScope AzLocal.UpdateManagement {
            Set-StrictMode -Version Latest
            $steps = @(
                $null
                [PSCustomObject]@{ name = 'a'; status = 'Success' }
                [PSCustomObject]@{
                    name = 'parent'; status = 'InProgress'
                    steps = @($null, [PSCustomObject]@{ name = 'b'; status = 'Failed' })
                }
            )
            $s = Get-AzLocalUpdateRunStepStats -Steps $steps
            $s.TotalLeaf | Should -Be 2
            $s.CompletedLeaf | Should -Be 1
            $s.FailedLeaf | Should -Be 1
        }
    }

    It 'Should count only leaf steps, excluding parent/wrapper steps' {
        InModuleScope AzLocal.UpdateManagement {
            # Wrapper "P" (Success) has 2 children; only the children are leaves.
            $steps = @(
                [PSCustomObject]@{
                    name   = 'P'
                    status = 'Success'
                    steps  = @(
                        [PSCustomObject]@{ name = 'a'; status = 'Success' }
                        [PSCustomObject]@{ name = 'b'; status = 'InProgress' }
                    )
                }
            )
            $s = Get-AzLocalUpdateRunStepStats -Steps $steps
            $s.TotalLeaf | Should -Be 2
            $s.CompletedLeaf | Should -Be 1
            $s.InProgressLeaf | Should -Be 1
        }
    }

    It 'Should count Skipped leaves as completed so a finished run can reach 100 percent' {
        InModuleScope AzLocal.UpdateManagement {
            $steps = @(
                [PSCustomObject]@{ name = 'a'; status = 'Success' }
                [PSCustomObject]@{ name = 'b'; status = 'Skipped' }
            )
            $s = Get-AzLocalUpdateRunStepStats -Steps $steps
            $s.TotalLeaf | Should -Be 2
            $s.CompletedLeaf | Should -Be 2
        }
    }

    It 'Should count Error and Failed leaves as failed' {
        InModuleScope AzLocal.UpdateManagement {
            $steps = @(
                [PSCustomObject]@{ name = 'a'; status = 'Error' }
                [PSCustomObject]@{ name = 'b'; status = 'Failed' }
                [PSCustomObject]@{ name = 'c'; status = 'Success' }
            )
            $s = Get-AzLocalUpdateRunStepStats -Steps $steps
            $s.FailedLeaf | Should -Be 2
            $s.CompletedLeaf | Should -Be 1
        }
    }

    It 'Should count blank/NotStarted leaves in Total only (remaining work)' {
        InModuleScope AzLocal.UpdateManagement {
            $steps = @(
                [PSCustomObject]@{ name = 'a'; status = 'Success' }
                [PSCustomObject]@{ name = 'b'; status = '' }
                [PSCustomObject]@{ name = 'c' }
            )
            $s = Get-AzLocalUpdateRunStepStats -Steps $steps
            $s.TotalLeaf | Should -Be 3
            $s.CompletedLeaf | Should -Be 1
            $s.InProgressLeaf | Should -Be 0
            $s.FailedLeaf | Should -Be 0
        }
    }

    It 'Should aggregate leaves recursively across a deeply nested tree' {
        InModuleScope AzLocal.UpdateManagement {
            $steps = @(
                [PSCustomObject]@{ name = 'Prepare update'; status = 'Success' }
                [PSCustomObject]@{
                    name   = 'Start update'
                    status = 'InProgress'
                    steps  = @(
                        [PSCustomObject]@{
                            name   = 'Update Cluster'
                            status = 'InProgress'
                            steps  = @(
                                [PSCustomObject]@{ name = 'Node 1'; status = 'Success' }
                                [PSCustomObject]@{ name = 'Node 2'; status = 'Success' }
                                [PSCustomObject]@{ name = 'Node 3'; status = 'InProgress' }
                            )
                        }
                    )
                }
            )
            $s = Get-AzLocalUpdateRunStepStats -Steps $steps
            # Leaves: Prepare update, Node 1, Node 2, Node 3 = 4 (Start update + Update Cluster are wrappers)
            $s.TotalLeaf | Should -Be 4
            $s.CompletedLeaf | Should -Be 3
            $s.InProgressLeaf | Should -Be 1
        }
    }
}

Describe 'Helper Function: Get-DeepestErrorMessage (Internal)' {

    It 'Should return empty string when steps array is empty' {
        InModuleScope AzLocal.UpdateManagement {
            (Get-DeepestErrorMessage -Steps @()) | Should -BeNullOrEmpty
        }
    }

    It 'Should return empty string when no step has Error/Failed status' {
        InModuleScope AzLocal.UpdateManagement {
            $steps = @(
                [PSCustomObject]@{ name = 's1'; status = 'Success';    errorMessage = 'ignored' },
                [PSCustomObject]@{ name = 's2'; status = 'InProgress'; errorMessage = 'ignored' }
            )
            (Get-DeepestErrorMessage -Steps $steps) | Should -BeNullOrEmpty
        }
    }

    It 'Should prefer the deepest Error/Failed message over an outer one' {
        InModuleScope AzLocal.UpdateManagement {
            $steps = @(
                [PSCustomObject]@{
                    name         = 'L1'
                    status       = 'Failed'
                    errorMessage = 'L1 message'
                    steps        = @(
                        [PSCustomObject]@{
                            name         = 'L2'
                            status       = 'Error'
                            errorMessage = 'L2 message'
                            steps        = @(
                                [PSCustomObject]@{
                                    name         = 'L3'
                                    status       = 'Error'
                                    errorMessage = 'L3 deepest'
                                }
                            )
                        }
                    )
                }
            )
            (Get-DeepestErrorMessage -Steps $steps) | Should -Be 'L3 deepest'
        }
    }

    It 'Should fall back to outer message when deepest Error step has no errorMessage' {
        InModuleScope AzLocal.UpdateManagement {
            $steps = @(
                [PSCustomObject]@{
                    name         = 'L1'
                    status       = 'Failed'
                    errorMessage = 'L1 message'
                    steps        = @(
                        [PSCustomObject]@{
                            name         = 'L2'
                            status       = 'Error'
                            errorMessage = ''
                        }
                    )
                }
            )
            (Get-DeepestErrorMessage -Steps $steps) | Should -Be 'L1 message'
        }
    }
}

