#region Pre-Update Health Validation Tests (v0.6.1)

Describe 'Function: Test-AzLocalClusterHealth' {
    
    Context 'Parameter Validation' {
        BeforeAll {
            $command = Get-Command Test-AzLocalClusterHealth
        }

        It 'Should have ClusterResourceIds parameter' {
            $command.Parameters.Keys | Should -Contain 'ClusterResourceIds'
        }

        It 'Should have ClusterNames parameter' {
            $command.Parameters.Keys | Should -Contain 'ClusterNames'
        }

        It 'Should have ScopeByUpdateRingTag parameter' {
            $command.Parameters.Keys | Should -Contain 'ScopeByUpdateRingTag'
        }

        It 'Should have UpdateRingValue parameter' {
            $command.Parameters.Keys | Should -Contain 'UpdateRingValue'
        }

        It 'Should have BlockingOnly parameter' {
            $command.Parameters.Keys | Should -Contain 'BlockingOnly'
        }

        It 'Should have ApiVersion parameter' {
            $command.Parameters.Keys | Should -Contain 'ApiVersion'
        }

        It 'Should have ExportPath parameter' {
            $command.Parameters.Keys | Should -Contain 'ExportPath'
        }

        It 'Should have ResourceGroupName parameter' {
            $command.Parameters.Keys | Should -Contain 'ResourceGroupName'
        }

        It 'Should have SubscriptionId parameter' {
            $command.Parameters.Keys | Should -Contain 'SubscriptionId'
        }
    }

    Context 'Parameter Sets' {
        BeforeAll {
            $command = Get-Command Test-AzLocalClusterHealth
        }

        It 'Should have ByResourceId parameter set' {
            $command.ParameterSets.Name | Should -Contain 'ByResourceId'
        }

        It 'Should have ByName parameter set' {
            $command.ParameterSets.Name | Should -Contain 'ByName'
        }

        It 'Should have ByTag parameter set' {
            $command.ParameterSets.Name | Should -Contain 'ByTag'
        }

        It 'Should have ClusterResourceIds mandatory in ByResourceId set' {
            $param = $command.Parameters['ClusterResourceIds']
            $attr = $param.Attributes | Where-Object { $_ -is [System.Management.Automation.ParameterAttribute] -and $_.ParameterSetName -eq 'ByResourceId' }
            $attr.Mandatory | Should -Be $true
        }

        It 'Should have ClusterNames mandatory in ByName set' {
            $param = $command.Parameters['ClusterNames']
            $attr = $param.Attributes | Where-Object { $_ -is [System.Management.Automation.ParameterAttribute] -and $_.ParameterSetName -eq 'ByName' }
            $attr.Mandatory | Should -Be $true
        }

        It 'Should have ScopeByUpdateRingTag mandatory in ByTag set' {
            $param = $command.Parameters['ScopeByUpdateRingTag']
            $attr = $param.Attributes | Where-Object { $_ -is [System.Management.Automation.ParameterAttribute] -and $_.ParameterSetName -eq 'ByTag' }
            $attr.Mandatory | Should -Be $true
        }
    }

    Context 'Output Type' {
        BeforeAll {
            $command = Get-Command Test-AzLocalClusterHealth
        }

        It 'Should have OutputType declared' {
            $command.OutputType | Should -Not -BeNullOrEmpty
        }
    }

    Context 'Naming Convention' {
        It 'Should use AzLocal noun prefix' {
            $noun = 'Test-AzLocalClusterHealth'.Split('-')[1]
            $noun | Should -BeLike 'AzLocal*'
        }
    }

    Context 'v0.8.77 strict-mode regression: missing properties.healthCheckResult' {
        # Production Step.05/06 (Azure/AzLocal.UpdateManagement) emitted
        # `Checking: <ClusterName>... Error: The property 'healthCheckResult'
        # cannot be found on this object.` for clusters whose ARM update
        # summary genuinely had no `healthCheckResult` field (typical for
        # clusters that had not been probed yet). Bare
        # $summary.properties.healthCheckResult under Set-StrictMode -Version
        # Latest THROWS, the catch block flagged the cluster
        # HealthState=Error / Passed=$false, and the readiness gate then
        # falsely blocked Arizona / Sydney from updates. Fix uses
        # PSObject.Properties[] indexing to guard the property read so the
        # function returns 'No Data' / Passed=$true instead of throwing.
        It 'Should classify a cluster with no healthCheckResult as "No Data" (Passed=$true) and NOT throw' {
            InModuleScope AzLocal.UpdateManagement {
                $resourceId = '/subscriptions/s/resourceGroups/r/providers/Microsoft.AzureStackHCI/clusters/no-hcr'

                # Summary row mirrors the ARG `updatesummaries` projection
                # shape Test-AzLocalClusterHealth consumes (id / name /
                # properties / ClusterResourceId_). DELIBERATELY omits the
                # `healthCheckResult` property from `properties`.
                $summaryRow = [PSCustomObject]@{
                    id                  = "$resourceId/updateSummaries/default"
                    name                = 'default'
                    properties          = [PSCustomObject]@{ state = 'AppliedSuccessfully' }
                    ClusterResourceId_  = $resourceId.ToLower()
                }

                function global:az { $global:LASTEXITCODE = 0; return '{}' }
                Mock Test-AzCliAvailable         { return $true }
                Mock Install-AzGraphExtension    { return $true }
                Mock Invoke-AzResourceGraphQuery { return @($summaryRow) }

                $result = $null
                # Note: assignment inside the Should -Not -Throw scriptblock
                # runs in its own scope and does NOT propagate; call once for
                # the throw assertion then capture again for property asserts.
                { Test-AzLocalClusterHealth `
                    -ClusterResourceIds @($resourceId) -PassThru 6>$null | Out-Null } | Should -Not -Throw
                $result = Test-AzLocalClusterHealth -ClusterResourceIds @($resourceId) -PassThru 6>$null

                $result             | Should -Not -BeNullOrEmpty
                $result.HealthState | Should -Be 'No Data'
                $result.Passed      | Should -Be $true
            }
        }

        It 'Reports missing health data as unknown and non-blocking instead of fully healthy' {
            InModuleScope AzLocal.UpdateManagement {
                $resourceId = '/subscriptions/s/resourceGroups/r/providers/Microsoft.AzureStackHCI/clusters/no-hcr-summary'
                $summaryRow = [PSCustomObject]@{
                    properties         = [PSCustomObject]@{ state = 'AppliedSuccessfully' }
                    ClusterResourceId_ = $resourceId.ToLower()
                }
                function global:az { $global:LASTEXITCODE = 0; return '{}' }
                Mock Test-AzCliAvailable { return $true }
                Mock Install-AzGraphExtension { return $true }
                Mock Invoke-AzResourceGraphQuery { return @($summaryRow) }
                Mock Write-Log { }

                $result = Test-AzLocalClusterHealth -ClusterResourceIds @($resourceId) -PassThru 6>$null

                $result.Passed | Should -BeTrue
                Assert-MockCalled Write-Log -Scope It -ParameterFilter {
                    $Message -like 'Unknown:*no health data*non-blocking*'
                }
                Assert-MockCalled Write-Log -Scope It -ParameterFilter {
                    $Message -like 'HEALTH VALIDATION PASSED WITH UNKNOWN DATA*'
                }
                Assert-MockCalled Write-Log -Scope It -Times 0 -ParameterFilter {
                    $Message -like '*All clusters are ready for updates*'
                }
            }
        }
    }

    Context 'Fleet-scale ARG query batching' {
        It 'Routes more than one value batch of cluster IDs through the shared batch helper' {
            InModuleScope AzLocal.UpdateManagement {
                $resourceIds = @(1..41 | ForEach-Object {
                    "/subscriptions/sub/resourceGroups/rg/providers/Microsoft.AzureStackHCI/clusters/cluster-$_"
                })
                Mock Test-AzCliAvailable { return $true }
                Mock Install-AzGraphExtension { return $true }
                Mock Invoke-AzLocalResourceGraphValueBatches { return @() }

                $result = Test-AzLocalClusterHealth -ClusterResourceIds $resourceIds -PassThru 6>$null

                $result | Should -HaveCount 41
                Assert-MockCalled Invoke-AzLocalResourceGraphValueBatches -Times 1 -Exactly -Scope It -ParameterFilter {
                    $Value.Count -eq 41 -and $QueryTemplate -match '\| where ClusterResourceId_ in~ \(\{0\}\)'
                }
            }
        }
    }
}

#endregion Pre-Update Health Validation Tests

#region Internal Helper: Invoke-AzResourceGraphQuery

Describe 'Internal Helper: Invoke-AzResourceGraphQuery' {

    Context 'Pagination behaviour' {

        It 'Should merge rows across multiple pages by following skip_token' {
            InModuleScope AzLocal.UpdateManagement {
                # Override the external 'az' executable with an in-scope function so
                # we can feed canned ARG responses without touching the network.
                $script:TestCallIndex = 0
                function az {
                    $script:TestCallIndex++
                    switch ($script:TestCallIndex) {
                        1 {
                            # First page returns 2 rows + continuation token
                            return '{"count":2,"data":[{"id":"a"},{"id":"b"}],"skip_token":"tok1","total_records":3}'
                        }
                        2 {
                            # Second page returns final row and no token
                            return '{"count":1,"data":[{"id":"c"}],"total_records":3}'
                        }
                        default {
                            throw "Unexpected extra page call index $($script:TestCallIndex)"
                        }
                    }
                }
                $global:LASTEXITCODE = 0

                $rows = Invoke-AzResourceGraphQuery -Query 'resources | project id'

                $rows | Should -HaveCount 3
                $rows[0].id | Should -Be 'a'
                $rows[1].id | Should -Be 'b'
                $rows[2].id | Should -Be 'c'
                $script:TestCallIndex | Should -Be 2
            }
        }

        It 'Should return an empty array when the single-page response has no data' {
            InModuleScope AzLocal.UpdateManagement {
                function az { return '{"count":0,"data":[],"total_records":0}' }
                $global:LASTEXITCODE = 0

                $diagnosticOutput = @(& {
                    $script:diagnosticRows = Invoke-AzResourceGraphQuery -Query "resources | where name == 'do-not-log-this-query-value'" -Verbose
                } 4>&1)
                ,$script:diagnosticRows | Should -BeOfType ([object[]])
                $script:diagnosticRows.Count | Should -Be 0
                $verboseText = @($diagnosticOutput | Where-Object { $_ -is [System.Management.Automation.VerboseRecord] }) -join "`n"
                $verboseText | Should -Match 'ARG query start: table=resources; fingerprint=[a-f0-9]{12}; chars=\d+; scope=ImplicitSubscriptions; scopeCount=0'
                $verboseText | Should -Match 'ARG query empty result: table=resources; fingerprint=[a-f0-9]{12}; rows=0; pages=1'
                $verboseText | Should -Not -Match 'do-not-log-this-query-value'
            }
        }

        It 'Should omit null rows while preserving valid ARG rows' {
            InModuleScope AzLocal.UpdateManagement {
                function az { return '{"count":2,"data":[null,{"id":"a"}],"total_records":2}' }
                $global:LASTEXITCODE = 0

                $rows = Invoke-AzResourceGraphQuery -Query 'resources | project id'
                $rows | Should -HaveCount 1
                $rows[0].id | Should -Be 'a'
            }
        }

        It 'Should throw when the CLI reports a non-zero exit code' {
            InModuleScope AzLocal.UpdateManagement {
                function az { return 'FATAL: query syntax error' }
                $global:LASTEXITCODE = 1

                { Invoke-AzResourceGraphQuery -Query 'bad query' } | Should -Throw -ExpectedMessage '*Azure Resource Graph query failed*'
            }
        }

        It 'Should stop at the MaxPages safety cap and emit a warning' {
            InModuleScope AzLocal.UpdateManagement {
                # Always return a continuation token to simulate an infinite loop.
                function az { return '{"count":1,"data":[{"id":"x"}],"skip_token":"never-ends"}' }
                $global:LASTEXITCODE = 0

                $warnings = @()
                $rows = Invoke-AzResourceGraphQuery -Query 'resources' -MaxPages 3 -WarningVariable warnings -WarningAction SilentlyContinue
                $rows | Should -HaveCount 3
                ($warnings -join ' ') | Should -Match 'safety cap'
            }
        }

        It 'Should reduce page size on ResponsePayloadTooLarge and retain it across continuation pages' {
            InModuleScope AzLocal.UpdateManagement {
                $script:PayloadCalls = [System.Collections.Generic.List[object]]::new()
                function az {
                    [void]$script:PayloadCalls.Add(@($args))
                    $firstIndex = [Array]::IndexOf($args, '--first')
                    $requestedFirst = [int]$args[$firstIndex + 1]
                    if ($script:PayloadCalls.Count -eq 1) {
                        Write-Error -ErrorAction Continue 'ERROR: (ResponsePayloadTooLarge) Response payload size is 171679930 and exceeded the limit of 16777216.'
                        $global:LASTEXITCODE = 1
                        return
                    }
                    $global:LASTEXITCODE = 0
                    if ($script:PayloadCalls.Count -eq 2) {
                        $requestedFirst | Should -Be 500
                        return '{"count":2,"data":[{"id":"a"},{"id":"b"}],"skip_token":"tok1","total_records":3}'
                    }
                    $requestedFirst | Should -Be 500
                    $args | Should -Contain 'tok1'
                    return '{"count":1,"data":[{"id":"c"}],"total_records":3}'
                }

                $rows = Invoke-AzResourceGraphQuery -Query 'resources | project id | order by id asc' -WarningAction SilentlyContinue

                $rows | Should -HaveCount 3
                @($rows.id) | Should -Be @('a', 'b', 'c')
                $script:PayloadCalls | Should -HaveCount 3
                $script:LastResourceGraphPayloadReduced | Should -BeTrue
                $script:LastResourceGraphPayloadRetryCount | Should -Be 1
                $script:LastResourceGraphEffectivePageSize | Should -Be 500
                $script:LastResourceGraphThrottled | Should -BeFalse
                $script:LastResourceGraphTransientNetwork | Should -BeFalse
            }
        }

        It 'Should require a leaner projection when one row exceeds the payload limit' {
            InModuleScope AzLocal.UpdateManagement {
                $script:SingleRowPayloadCalls = 0
                function az {
                    $script:SingleRowPayloadCalls++
                    Write-Error -ErrorAction Continue 'ERROR: code=ResponsePayloadTooLarge; response payload size exceeded the limit of 16777216.'
                    $global:LASTEXITCODE = 1
                }

                {
                    Invoke-AzResourceGraphQuery -Query 'resources | project properties' -First 1 -WarningAction SilentlyContinue
                } | Should -Throw -ExpectedMessage '*one result row exceeds*Project fewer or smaller fields*'
                $script:SingleRowPayloadCalls | Should -Be 1
                $script:LastResourceGraphPayloadReduced | Should -BeTrue
                $script:LastResourceGraphPayloadRetryCount | Should -Be 0
                $script:LastResourceGraphEffectivePageSize | Should -Be 1
            }
        }

        It 'Should reset payload diagnostics at the start of every call' {
            InModuleScope AzLocal.UpdateManagement {
                $script:PayloadResetCalls = 0
                function az {
                    $script:PayloadResetCalls++
                    if ($script:PayloadResetCalls -eq 1) {
                        Write-Error -ErrorAction Continue 'ERROR: ResponsePayloadTooLarge - response payload size exceeded the limit.'
                        $global:LASTEXITCODE = 1
                        return
                    }
                    $global:LASTEXITCODE = 0
                    return '{"count":0,"data":[],"total_records":0}'
                }
                [void](Invoke-AzResourceGraphQuery -Query 'resources | project id | order by id asc' -WarningAction SilentlyContinue)
                $script:LastResourceGraphPayloadReduced | Should -BeTrue
                $script:LastResourceGraphEffectivePageSize | Should -Be 500

                function az {
                    $global:LASTEXITCODE = 0
                    return '{"count":0,"data":[],"total_records":0}'
                }
                [void](Invoke-AzResourceGraphQuery -Query 'resources | project id | order by id asc' -First 200)
                $script:LastResourceGraphPayloadReduced | Should -BeFalse
                $script:LastResourceGraphPayloadRetryCount | Should -Be 0
                $script:LastResourceGraphEffectivePageSize | Should -Be 200
            }
        }
    }

    Context 'cp1252 stderr WARNING does not corrupt JSON parse (v0.7.66 regression)' {
        # v0.7.66 regression guard: on hosted Windows runners (windows-latest,
        # windows-2022) the Azure CLI's Python layer can emit
        # 'WARNING: Unable to encode the output with cp1252 encoding...' to
        # stderr before emitting the JSON body to stdout. The helper captures
        # the merged stream via 2>&1, so without explicit stream-type filtering
        # the WARNING line gets prepended to the JSON body and ConvertFrom-Json
        # throws 'Unexpected character encountered while parsing value: W.'
        # The fix: split the captured stream by element type (stderr lines
        # surface as ErrorRecord, stdout lines as String) and feed only the
        # string stream to ConvertFrom-Json. See matching hardening in
        # Invoke-AzRestJson (v0.7.2).
        It 'Should ignore stderr ErrorRecord lines when parsing the JSON body' {
            InModuleScope AzLocal.UpdateManagement {
                # Simulate the Azure CLI emitting both a stderr WARNING and a
                # valid JSON body on stdout. Write-Error makes the line surface
                # as an ErrorRecord under 2>&1; the trailing 'return' emits
                # the JSON to the output (stdout) stream. Pre-v0.7.66 the
                # helper would call ConvertFrom-Json on 'WARNING: ...\n{...}'
                # and throw.
                function az {
                    Write-Error 'WARNING: Unable to encode the output with cp1252 encoding. Unsupported characters are discarded.'
                    return '{"count":1,"data":[{"id":"row-after-warning"}],"total_records":1}'
                }
                $global:LASTEXITCODE = 0

                $rows = Invoke-AzResourceGraphQuery -Query 'resources | project id' -ErrorAction SilentlyContinue
                $rows | Should -HaveCount 1
                $rows[0].id | Should -Be 'row-after-warning'
            }
        }

        It 'Should restore PYTHONIOENCODING after a successful call' {
            InModuleScope AzLocal.UpdateManagement {
                function az { return '{"count":0,"data":[],"total_records":0}' }
                $global:LASTEXITCODE = 0
                $before = $env:PYTHONIOENCODING
                try {
                    $env:PYTHONIOENCODING = 'sentinel-before'
                    [void](Invoke-AzResourceGraphQuery -Query 'resources | where 1==0')
                    $env:PYTHONIOENCODING | Should -Be 'sentinel-before'
                }
                finally {
                    $env:PYTHONIOENCODING = $before
                }
            }
        }

        It 'Should restore PYTHONIOENCODING after a throwing call' {
            InModuleScope AzLocal.UpdateManagement {
                function az { return 'FATAL: oops' }
                $global:LASTEXITCODE = 1
                $before = $env:PYTHONIOENCODING
                try {
                    $env:PYTHONIOENCODING = 'sentinel-throw'
                    { Invoke-AzResourceGraphQuery -Query 'bad' } | Should -Throw
                    $env:PYTHONIOENCODING | Should -Be 'sentinel-throw'
                }
                finally {
                    $env:PYTHONIOENCODING = $before
                }
            }
        }
    }

    Context 'Throttle handling (v0.7.68)' {
        # v0.7.68 introduced a per-page retry loop for ARG 429 / RateLimitingException
        # responses. The retry budget is -MaxRetries (default 5); the backoff is
        # exponential with +/-20% jitter; non-throttle errors are NOT retried; and
        # two module-scope diagnostic flags ($script:LastResourceGraphThrottled,
        # $script:LastResourceGraphRetryCount) are reset per call and readable
        # by callers/tests.

        It 'Should retry on 429 / RateLimitingException and eventually succeed' {
            InModuleScope AzLocal.UpdateManagement {
                $script:ThrottleCalls = 0
                function az {
                    $script:ThrottleCalls++
                    if ($script:ThrottleCalls -le 2) {
                        # -ErrorAction Continue bypasses Pester v5's $ErrorActionPreference='Stop'
                        # It-block default, which would otherwise turn this Write-Error into a
                        # terminating exception and abort before $LASTEXITCODE is set. The real
                        # az.exe writes throttle messages to stderr without raising a PowerShell
                        # error; this mock simulates that non-terminating behaviour.
                        Write-Error -ErrorAction Continue 'ERROR: RateLimitingException (429): Too many requests. Please retry after some time.'
                        $global:LASTEXITCODE = 1
                        return
                    }
                    $global:LASTEXITCODE = 0
                    return '{"count":1,"data":[{"id":"recovered"}],"total_records":1}'
                }

                $rows = Invoke-AzResourceGraphQuery -Query 'resources' -RetryBaseSeconds 0.1 -WarningAction SilentlyContinue
                $rows | Should -HaveCount 1
                $rows[0].id | Should -Be 'recovered'
                $script:ThrottleCalls | Should -Be 3
                $script:LastResourceGraphThrottled | Should -BeTrue
                $script:LastResourceGraphRetryCount | Should -Be 2
            }
        }

        It 'Should give up and throw once -MaxRetries is exhausted on persistent throttling' {
            InModuleScope AzLocal.UpdateManagement {
                function az {
                    # -ErrorAction Continue bypasses Pester v5 It-block 'Stop' default; see
                    # comment in the preceding test for the full rationale.
                    Write-Error -ErrorAction Continue 'ERROR: 429 TooManyRequests - rate limit exceeded'
                    $global:LASTEXITCODE = 1
                    return
                }

                {
                    Invoke-AzResourceGraphQuery -Query 'resources' -MaxRetries 2 -RetryBaseSeconds 0.1 -WarningAction SilentlyContinue
                } | Should -Throw -ExpectedMessage '*Azure Resource Graph query failed*'
                $script:LastResourceGraphThrottled | Should -BeTrue
                $script:LastResourceGraphRetryCount | Should -Be 2
            }
        }

        It 'Should NOT retry on non-throttle errors (auth, bad KQL, permissions)' {
            InModuleScope AzLocal.UpdateManagement {
                $script:NonThrottleCalls = 0
                function az {
                    $script:NonThrottleCalls++
                    # -ErrorAction Continue bypasses Pester v5 It-block 'Stop' default; see
                    # comment in the 'Should retry on 429' test for the full rationale.
                    Write-Error -ErrorAction Continue 'ERROR: AuthenticationFailed - the access token is invalid'
                    $global:LASTEXITCODE = 1
                    return
                }

                {
                    Invoke-AzResourceGraphQuery -Query 'resources' -MaxRetries 5 -RetryBaseSeconds 0.1
                } | Should -Throw -ExpectedMessage '*Azure Resource Graph query failed*'
                $script:NonThrottleCalls | Should -Be 1
                $script:LastResourceGraphThrottled | Should -BeFalse
                $script:LastResourceGraphRetryCount | Should -Be 0
            }
        }

        It 'Renews GitHub OIDC authentication and retries an expired assertion once' {
            InModuleScope AzLocal.UpdateManagement {
                $script:AuthCalls = 0
                function az {
                    $script:AuthCalls++
                    if ($script:AuthCalls -eq 1) {
                        Write-Error -ErrorAction Continue 'ERROR: AADSTS700024: Client assertion is not within its valid time range.'
                        $global:LASTEXITCODE = 1
                        return
                    }
                    $global:LASTEXITCODE = 0
                    return '{"count":1,"data":[{"id":"renewed"}],"total_records":1}'
                }
                Mock Repair-AzLocalAzureCliAuthentication { return $true }

                $rows = Invoke-AzResourceGraphQuery -Query 'resources' -WarningAction SilentlyContinue

                $rows | Should -HaveCount 1
                $rows[0].id | Should -Be 'renewed'
                $script:AuthCalls | Should -Be 2
                Assert-MockCalled Repair-AzLocalAzureCliAuthentication -Times 1 -Exactly
            }
        }

        It 'Should reset throttle diagnostic flags at the start of every call' {
            InModuleScope AzLocal.UpdateManagement {
                # First call: triggers a throttle + retry to set flags TRUE / >0.
                $script:Phase1Calls = 0
                function az {
                    $script:Phase1Calls++
                    if ($script:Phase1Calls -eq 1) {
                        # -ErrorAction Continue bypasses Pester v5 It-block 'Stop' default; see
                        # comment in the 'Should retry on 429' test for the full rationale.
                        Write-Error -ErrorAction Continue 'ERROR: 429 throttled'
                        $global:LASTEXITCODE = 1
                        return
                    }
                    $global:LASTEXITCODE = 0
                    return '{"count":0,"data":[],"total_records":0}'
                }
                [void](Invoke-AzResourceGraphQuery -Query 'resources' -RetryBaseSeconds 0.1 -WarningAction SilentlyContinue)
                $script:LastResourceGraphThrottled | Should -BeTrue
                $script:LastResourceGraphRetryCount | Should -Be 1

                # Second call: clean (no throttle). Flags must reset back to FALSE / 0.
                function az {
                    $global:LASTEXITCODE = 0
                    return '{"count":0,"data":[],"total_records":0}'
                }
                [void](Invoke-AzResourceGraphQuery -Query 'resources')
                $script:LastResourceGraphThrottled | Should -BeFalse
                $script:LastResourceGraphRetryCount | Should -Be 0
            }
        }
    }

    Context 'Transient network / connection-reset handling (v0.8.95)' {
        # v0.8.95 extended the per-page retry loop to cover transient network
        # failures (TCP connection reset mid-request). Two production GitHub
        # Actions runs (Fleet Update Status run 28008708678 and Apply Updates
        # run 27964791090) both failed when 'az graph query' hit a
        # ConnectionResetError(10054) / "Connection broken", which the
        # resource-graph extension then mis-handled into a Python traceback
        # ("'NoneType' object has no attribute 'error'") and exit 1. These are
        # transient and now retried. They are tracked SEPARATELY from throttle
        # via $script:LastResourceGraphTransientNetwork /
        # $script:LastResourceGraphTransientRetryCount, and they do NOT arm the
        # cross-call throttle cooldown.
        #
        # The exact error text the production runs emitted is reproduced inline
        # in each test (as a local here-string) so the classifier is exercised
        # against the real-world string. NOTE: it must be defined INSIDE the
        # InModuleScope block - a $script:-scoped variable declared at Context
        # level is not visible inside InModuleScope, where $script: resolves to
        # the MODULE's scope, not the test file's.

        It 'Should retry on a connection reset (10054) and eventually succeed' {
            InModuleScope AzLocal.UpdateManagement {
                $script:ResetCalls = 0
                $errText = @'
ERROR: The command failed with an unexpected error. Here is the traceback:
ERROR: 'NoneType' object has no attribute 'error'
azure.core.exceptions.HttpResponseError: ("Connection broken: ConnectionResetError(10054, 'An existing connection was forcibly closed by the remote host', None, 10054, None)", ConnectionResetError(10054, 'An existing connection was forcibly closed by the remote host', None, 10054, None))
AttributeError: 'NoneType' object has no attribute 'error'
'@
                function az {
                    $script:ResetCalls++
                    if ($script:ResetCalls -le 2) {
                        # -ErrorAction Continue bypasses Pester v5's It-block 'Stop'
                        # default so $LASTEXITCODE is still set; mirrors how real
                        # az.exe writes the traceback to stderr without raising a
                        # terminating PowerShell error.
                        Write-Error -ErrorAction Continue $errText
                        $global:LASTEXITCODE = 1
                        return
                    }
                    $global:LASTEXITCODE = 0
                    return '{"count":1,"data":[{"id":"recovered"}],"total_records":1}'
                }

                $rows = Invoke-AzResourceGraphQuery -Query 'resources' -RetryBaseSeconds 0.1 -WarningAction SilentlyContinue
                $rows | Should -HaveCount 1
                $rows[0].id | Should -Be 'recovered'
                $script:ResetCalls | Should -Be 3
                $script:LastResourceGraphTransientNetwork | Should -BeTrue
                $script:LastResourceGraphTransientRetryCount | Should -Be 2
                # A connection reset is NOT a throttle - throttle flags stay clean.
                $script:LastResourceGraphThrottled | Should -BeFalse
                $script:LastResourceGraphRetryCount | Should -Be 0
            }
        }

        It 'Should give up and throw once -MaxRetries is exhausted on persistent resets' {
            InModuleScope AzLocal.UpdateManagement {
                $errText = @'
ERROR: The command failed with an unexpected error. Here is the traceback:
azure.core.exceptions.HttpResponseError: ("Connection broken: ConnectionResetError(10054, 'An existing connection was forcibly closed by the remote host', None, 10054, None)", ConnectionResetError(10054, 'An existing connection was forcibly closed by the remote host', None, 10054, None))
'@
                function az {
                    Write-Error -ErrorAction Continue $errText
                    $global:LASTEXITCODE = 1
                    return
                }

                {
                    Invoke-AzResourceGraphQuery -Query 'resources' -MaxRetries 2 -RetryBaseSeconds 0.1 -WarningAction SilentlyContinue
                } | Should -Throw -ExpectedMessage '*Azure Resource Graph query failed*'
                $script:LastResourceGraphTransientNetwork | Should -BeTrue
                $script:LastResourceGraphTransientRetryCount | Should -Be 2
            }
        }

        It 'Should NOT arm the cross-call throttle cooldown on a connection reset' {
            InModuleScope AzLocal.UpdateManagement {
                # Reset cooldown state so the assertion is unambiguous.
                $script:ArgCrossCallCooldownUntil = [DateTime]::MinValue
                $script:ArgConsecutiveThrottledCalls = 0
                $errText = @'
azure.core.exceptions.HttpResponseError: ("Connection broken: ConnectionResetError(10054, 'An existing connection was forcibly closed by the remote host', None, 10054, None)", ConnectionResetError(10054, 'An existing connection was forcibly closed by the remote host', None, 10054, None))
'@
                $script:ResetThenOk = 0
                function az {
                    $script:ResetThenOk++
                    if ($script:ResetThenOk -eq 1) {
                        Write-Error -ErrorAction Continue $errText
                        $global:LASTEXITCODE = 1
                        return
                    }
                    $global:LASTEXITCODE = 0
                    return '{"count":0,"data":[],"total_records":0}'
                }

                [void](Invoke-AzResourceGraphQuery -Query 'resources' -RetryBaseSeconds 0.1 -WarningAction SilentlyContinue)
                # Connection resets must leave the cross-call throttle cooldown untouched.
                $script:ArgConsecutiveThrottledCalls | Should -Be 0
                $script:ArgCrossCallCooldownUntil | Should -Be ([DateTime]::MinValue)
            }
        }

        It 'Should still NOT retry genuine non-transient errors (auth / bad KQL)' {
            InModuleScope AzLocal.UpdateManagement {
                $script:AuthCalls = 0
                function az {
                    $script:AuthCalls++
                    Write-Error -ErrorAction Continue 'ERROR: AuthenticationFailed - the access token is invalid'
                    $global:LASTEXITCODE = 1
                    return
                }

                {
                    Invoke-AzResourceGraphQuery -Query 'resources' -MaxRetries 5 -RetryBaseSeconds 0.1
                } | Should -Throw -ExpectedMessage '*Azure Resource Graph query failed*'
                $script:AuthCalls | Should -Be 1
                $script:LastResourceGraphTransientNetwork | Should -BeFalse
                $script:LastResourceGraphTransientRetryCount | Should -Be 0
            }
        }

        It 'Should reset transient-network diagnostic flags at the start of every call' {
            InModuleScope AzLocal.UpdateManagement {
                $errText = @'
azure.core.exceptions.HttpResponseError: ("Connection broken: ConnectionResetError(10054, 'An existing connection was forcibly closed by the remote host', None, 10054, None)", ConnectionResetError(10054, 'An existing connection was forcibly closed by the remote host', None, 10054, None))
'@
                $script:T1Calls = 0
                function az {
                    $script:T1Calls++
                    if ($script:T1Calls -eq 1) {
                        Write-Error -ErrorAction Continue $errText
                        $global:LASTEXITCODE = 1
                        return
                    }
                    $global:LASTEXITCODE = 0
                    return '{"count":0,"data":[],"total_records":0}'
                }
                [void](Invoke-AzResourceGraphQuery -Query 'resources' -RetryBaseSeconds 0.1 -WarningAction SilentlyContinue)
                $script:LastResourceGraphTransientNetwork | Should -BeTrue
                $script:LastResourceGraphTransientRetryCount | Should -Be 1

                # Second, clean call: flags must reset back to FALSE / 0.
                function az {
                    $global:LASTEXITCODE = 0
                    return '{"count":0,"data":[],"total_records":0}'
                }
                [void](Invoke-AzResourceGraphQuery -Query 'resources')
                $script:LastResourceGraphTransientNetwork | Should -BeFalse
                $script:LastResourceGraphTransientRetryCount | Should -Be 0
            }
        }
    }

    Context 'Cross-call throttle coordination (v0.7.84)' {
        # v0.7.84 added a module-scope cross-call cooldown so that a throttle
        # event observed in call N causes call N+1 to sleep out a short
        # voluntary window on entry. This complements the v0.7.68 per-page
        # retry loop (which only handles bursts WITHIN one call). The cooldown
        # state lives in $script:ArgCrossCallCooldownUntil and
        # $script:ArgConsecutiveThrottledCalls; each call exposes how long it
        # actually slept on entry via $script:LastResourceGraphCrossCallCooldownSeconds.
        # The -DisableCrossCallCooldown switch opts out (used in tests and by
        # callers that have their own rate-limiting upstream).

        It 'Sets the cross-call cooldown window after observing throttling' {
            InModuleScope AzLocal.UpdateManagement {
                # Reset state so this test doesn't inherit cooldown from a prior test.
                $script:ArgCrossCallCooldownUntil = [DateTime]::MinValue
                $script:ArgConsecutiveThrottledCalls = 0

                $script:Phase = 0
                function az {
                    $script:Phase++
                    if ($script:Phase -eq 1) {
                        Write-Error -ErrorAction Continue 'ERROR: 429 throttled'
                        $global:LASTEXITCODE = 1
                        return
                    }
                    $global:LASTEXITCODE = 0
                    return '{"count":0,"data":[],"total_records":0}'
                }
                $before = Get-Date
                [void](Invoke-AzResourceGraphQuery -Query 'resources' -RetryBaseSeconds 0.1 -DisableCrossCallCooldown -WarningAction SilentlyContinue)
                # After a throttle event, the cooldown window must be set to a
                # future instant relative to the start of the call.
                $script:ArgCrossCallCooldownUntil | Should -BeGreaterThan $before
                $script:ArgConsecutiveThrottledCalls | Should -BeGreaterThan 0
            }
        }

        It 'Sleeps on entry when a previous call set a cross-call cooldown window' {
            InModuleScope AzLocal.UpdateManagement {
                # Manually arm a 300ms cooldown window. A subsequent clean call
                # must wait it out on entry and report the wait via the
                # per-call diagnostic flag.
                $script:ArgCrossCallCooldownUntil = (Get-Date).AddMilliseconds(300)
                function az {
                    $global:LASTEXITCODE = 0
                    return '{"count":0,"data":[],"total_records":0}'
                }
                $sw = [System.Diagnostics.Stopwatch]::StartNew()
                [void](Invoke-AzResourceGraphQuery -Query 'resources')
                $sw.Stop()
                # Elapsed must be at least the cooldown (allow generous slack
                # for slow CI; minimum guarantee is ~250ms).
                $sw.Elapsed.TotalMilliseconds | Should -BeGreaterThan 250
                $script:LastResourceGraphCrossCallCooldownSeconds | Should -BeGreaterThan 0
                # Reset for downstream tests.
                $script:ArgCrossCallCooldownUntil = [DateTime]::MinValue
                $script:ArgConsecutiveThrottledCalls = 0
            }
        }

        It '-DisableCrossCallCooldown bypasses the cooldown wait on entry' {
            InModuleScope AzLocal.UpdateManagement {
                # Arm a 500ms cooldown. With -DisableCrossCallCooldown the
                # call must NOT sleep and must report 0 cooldown applied.
                $script:ArgCrossCallCooldownUntil = (Get-Date).AddMilliseconds(500)
                function az {
                    $global:LASTEXITCODE = 0
                    return '{"count":0,"data":[],"total_records":0}'
                }
                $sw = [System.Diagnostics.Stopwatch]::StartNew()
                [void](Invoke-AzResourceGraphQuery -Query 'resources' -DisableCrossCallCooldown)
                $sw.Stop()
                # Must complete fast - well under the 500ms cooldown.
                $sw.Elapsed.TotalMilliseconds | Should -BeLessThan 250
                $script:LastResourceGraphCrossCallCooldownSeconds | Should -Be 0
                # Reset for downstream tests.
                $script:ArgCrossCallCooldownUntil = [DateTime]::MinValue
                $script:ArgConsecutiveThrottledCalls = 0
            }
        }

        It 'Decays the consecutive-throttle counter on a clean call' {
            InModuleScope AzLocal.UpdateManagement {
                # Pretend we are 3 throttled calls deep. A clean call must
                # decrement the counter to 2 (and not below 0).
                $script:ArgConsecutiveThrottledCalls = 3
                $script:ArgCrossCallCooldownUntil = [DateTime]::MinValue
                function az {
                    $global:LASTEXITCODE = 0
                    return '{"count":0,"data":[],"total_records":0}'
                }
                [void](Invoke-AzResourceGraphQuery -Query 'resources' -DisableCrossCallCooldown)
                $script:ArgConsecutiveThrottledCalls | Should -Be 2

                # Three more clean calls must drive it to 0 and clamp at 0.
                [void](Invoke-AzResourceGraphQuery -Query 'resources' -DisableCrossCallCooldown)
                [void](Invoke-AzResourceGraphQuery -Query 'resources' -DisableCrossCallCooldown)
                [void](Invoke-AzResourceGraphQuery -Query 'resources' -DisableCrossCallCooldown)
                $script:ArgConsecutiveThrottledCalls | Should -Be 0
            }
        }
    }
}

#endregion Internal Helper: Invoke-AzResourceGraphQuery

Describe 'Internal Helper: Invoke-AzRestJson diagnostics' {
    It 'Emits bounded completion telemetry for a value collection without URI query parameters' {
        InModuleScope AzLocal.UpdateManagement {
            function az {
                $global:LASTEXITCODE = 0
                return '{"value":[{"id":"a"},{"id":"b"}]}'
            }

            $diagnosticOutput = @(& {
                $script:diagnosticRestResult = Invoke-AzRestJson -Uri 'https://management.azure.com/subscriptions/sub-1/providers/Microsoft.Example/widgets?api-version=2025-01-01&sig=do-not-log' -Verbose
            } 4>&1)
            $script:diagnosticRestResult.Ok | Should -BeTrue
            $verboseText = @($diagnosticOutput | Where-Object { $_ -is [System.Management.Automation.VerboseRecord] }) -join "`n"
            $verboseText | Should -Match 'ARM request start: method=GET; path=/subscriptions/sub-1/providers/Microsoft.Example/widgets; hasBody=False'
            $verboseText | Should -Match 'ARM request completed: method=GET; .*shape=value collection; resultCount=2'
            $verboseText | Should -Not -Match 'api-version|do-not-log'
        }
    }

    It 'Distinguishes a successful empty response from failure' {
        InModuleScope AzLocal.UpdateManagement {
            function az {
                $global:LASTEXITCODE = 0
                return ''
            }

            $diagnosticOutput = @(& {
                $script:diagnosticRestResult = Invoke-AzRestJson -Uri 'https://management.azure.com/subscriptions/sub-1/resourceGroups/rg-1' -Verbose
            } 4>&1)
            $script:diagnosticRestResult.Ok | Should -BeTrue
            $script:diagnosticRestResult.Data | Should -BeNullOrEmpty
            (@($diagnosticOutput | Where-Object { $_ -is [System.Management.Automation.VerboseRecord] }) -join "`n") |
                Should -Match 'ARM request completed with empty response: method=GET; path=/subscriptions/sub-1/resourceGroups/rg-1'
        }
    }

    It 'Emits scrubbed failure telemetry and returns the same actionable error' {
        InModuleScope AzLocal.UpdateManagement {
            function az {
                $global:LASTEXITCODE = 1
                return 'Authorization failed. access_token=secret-value'
            }

            $diagnosticOutput = @(& {
                $script:diagnosticRestResult = Invoke-AzRestJson -Uri 'https://management.azure.com/subscriptions/sub-1/resourceGroups/rg-1?api-version=2025-01-01' -Verbose
            } 4>&1)
            $script:diagnosticRestResult.Ok | Should -BeFalse
            $verboseText = @($diagnosticOutput | Where-Object { $_ -is [System.Management.Automation.VerboseRecord] }) -join "`n"
            $verboseText | Should -Match 'ARM request failed: method=GET; path=/subscriptions/sub-1/resourceGroups/rg-1; exit=1; error='
            $verboseText | Should -Not -Match 'secret-value|api-version'
            $script:diagnosticRestResult.Error | Should -Not -Match 'secret-value'
        }
    }

    It 'Renews GitHub OIDC authentication after an expired assertion and retries once' {
        InModuleScope AzLocal.UpdateManagement {
            $script:RestCalls = 0
            function az {
                param([Parameter(ValueFromRemainingArguments = $true)][object[]]$RemainingArgs)
                if ($RemainingArgs[0] -eq 'rest') {
                    $script:RestCalls++
                    if ($script:RestCalls -eq 1) {
                        Write-Error -ErrorAction Continue 'ERROR: AADSTS700024: assertion is not within its valid time range.'
                        $global:LASTEXITCODE = 1
                        return
                    }
                    $global:LASTEXITCODE = 0
                    return '{"id":"recovered"}'
                }
                $global:LASTEXITCODE = 1
            }
            Mock Repair-AzLocalAzureCliAuthentication { return $true }

            $result = Invoke-AzRestJson -Uri 'https://management.azure.com/subscriptions/sub-1?api-version=2025-01-01'

            $result.Ok | Should -BeTrue
            $result.Data.id | Should -Be 'recovered'
            $script:RestCalls | Should -Be 2
            Assert-MockCalled Repair-AzLocalAzureCliAuthentication -Times 1 -Exactly
        }
    }
}

Describe 'Internal Helper: Repair-AzLocalAzureCliAuthentication' {
    It 'Requests a fresh GitHub assertion, signs in, and restores the default subscription' {
        InModuleScope AzLocal.UpdateManagement {
            $savedEnvironment = @{
                GITHUB_ACTIONS                 = $env:GITHUB_ACTIONS
                ACTIONS_ID_TOKEN_REQUEST_URL   = $env:ACTIONS_ID_TOKEN_REQUEST_URL
                ACTIONS_ID_TOKEN_REQUEST_TOKEN = $env:ACTIONS_ID_TOKEN_REQUEST_TOKEN
                AZLOCAL_OIDC_CLIENT_ID         = $env:AZLOCAL_OIDC_CLIENT_ID
                AZLOCAL_OIDC_TENANT_ID         = $env:AZLOCAL_OIDC_TENANT_ID
                AZLOCAL_OIDC_SUBSCRIPTION_ID   = $env:AZLOCAL_OIDC_SUBSCRIPTION_ID
            }
            try {
                $env:GITHUB_ACTIONS = 'true'
                $env:ACTIONS_ID_TOKEN_REQUEST_URL = 'https://token.actions.example/oidc?api-version=1'
                $env:ACTIONS_ID_TOKEN_REQUEST_TOKEN = 'request-token'
                $env:AZLOCAL_OIDC_CLIENT_ID = 'client-id'
                $env:AZLOCAL_OIDC_TENANT_ID = 'tenant-id'
                $env:AZLOCAL_OIDC_SUBSCRIPTION_ID = 'subscription-id'
                $script:AzRenewalCalls = [System.Collections.Generic.List[string]]::new()
                function az {
                    param([Parameter(ValueFromRemainingArguments = $true)][object[]]$RemainingArgs)
                    [void]$script:AzRenewalCalls.Add(($RemainingArgs -join ' '))
                    $global:LASTEXITCODE = 0
                }
                Mock Invoke-RestMethod { return [pscustomobject]@{ value = 'fresh-assertion' } }

                Repair-AzLocalAzureCliAuthentication | Should -BeTrue

                Assert-MockCalled Invoke-RestMethod -Times 1 -Exactly -ParameterFilter {
                    $Uri -match 'audience=api%3A%2F%2FAzureADTokenExchange' -and
                    $Headers.Authorization -eq 'Bearer request-token'
                }
                $script:AzRenewalCalls | Should -HaveCount 2
                $script:AzRenewalCalls[0] | Should -Match '^login --service-principal .*--username client-id .*--tenant tenant-id .*--federated-token fresh-assertion'
                $script:AzRenewalCalls[1] | Should -Be 'account set --subscription subscription-id'
            }
            finally {
                foreach ($entry in $savedEnvironment.GetEnumerator()) {
                    [Environment]::SetEnvironmentVariable([string]$entry.Key, $entry.Value, 'Process')
                }
            }
        }
    }

    It 'Declines renewal when GitHub OIDC metadata is unavailable' {
        InModuleScope AzLocal.UpdateManagement {
            $savedGitHubActions = $env:GITHUB_ACTIONS
            try {
                Remove-Item Env:GITHUB_ACTIONS -ErrorAction SilentlyContinue
                Mock Invoke-RestMethod { throw 'must not be called' }

                Repair-AzLocalAzureCliAuthentication | Should -BeFalse

                Assert-MockCalled Invoke-RestMethod -Times 0 -Exactly
            }
            finally {
                [Environment]::SetEnvironmentVariable('GITHUB_ACTIONS', $savedGitHubActions, 'Process')
            }
        }
    }
}

Describe 'GitHub monitoring workflows expose OIDC renewal metadata' {
    It 'Wires renewal metadata into <Workflow>' -ForEach @(
        @{ Workflow = 'fleet-connectivity-status.yml' }
        @{ Workflow = 'fleet-health-status.yml' }
        @{ Workflow = 'fleet-update-status.yml' }
        @{ Workflow = 'monitor-updates.yml' }
    ) {
        $workflowPath = Join-Path -Path $PSScriptRoot -ChildPath "..\Automation-Pipeline-Examples\github-actions\$Workflow"
        $workflowText = Get-Content -LiteralPath $workflowPath -Raw

        @($workflowText | Select-String -Pattern 'AZLOCAL_OIDC_CLIENT_ID:\s*\$\{\{ secrets\.AZURE_CLIENT_ID \}\}' -AllMatches).Matches.Count | Should -Be 1
        @($workflowText | Select-String -Pattern 'AZLOCAL_OIDC_TENANT_ID:\s*\$\{\{ vars\.AZURE_TENANT_ID \}\}' -AllMatches).Matches.Count | Should -Be 1
        @($workflowText | Select-String -Pattern 'AZLOCAL_OIDC_SUBSCRIPTION_ID:\s*\$\{\{ vars\.AZURE_SUBSCRIPTION_ID \}\}' -AllMatches).Matches.Count | Should -Be 1
        $workflowText | Should -Match 'subscription id restores the CLI default account after login'
        $workflowText | Should -Match 'does not scope ARG queries'
    }
}

Describe 'Pipeline diagnostics: Invoke-AzLocalPipelineTimedOperation' {
    It 'Preserves workload output and writes a successful timing report' {
        InModuleScope AzLocal.UpdateManagement {
            $path = Join-Path $TestDrive 'diagnostics\pipeline-timings.json'
            $result = Invoke-AzLocalPipelineTimedOperation `
                -PipelineName 'monitor-updates' `
                -PipelineVersion '0.9.28' `
                -StepNumber 20 `
                -StepName 'Snapshot update runs' `
                -Path $path `
                -ScriptBlock { [pscustomobject]@{ Value = 42 } }

            $result.Value | Should -Be 42
            $report = Get-Content -LiteralPath $path -Raw | ConvertFrom-Json
            $report.schemaVersion | Should -Be 1
            $report.pipelineName | Should -Be 'monitor-updates'
            $report.pipelineVersion | Should -Be '0.9.28'
            $report.platform | Should -Be 'Local'
            $report.runId | Should -Be ''
            $report.runAttempt | Should -Be ''
            $report.moduleVersion | Should -Match '^0\.9\.31'
            $report.powerShellVersion | Should -Not -BeNullOrEmpty
            $report.powerShellEdition | Should -Not -BeNullOrEmpty
            { [datetime]$report.startedUtc | Out-Null } | Should -Not -Throw
            { [datetime]$report.lastUpdatedUtc | Out-Null } | Should -Not -Throw
            $report.wallClockDurationMs | Should -BeGreaterOrEqual 0
            $report.status | Should -Be 'Succeeded'
            $report.operationCount | Should -Be 1
            $report.operations[0].stepNumber | Should -Be 20
            $report.operations[0].stepName | Should -Be 'Snapshot update runs'
            $report.operations[0].invocationId | Should -Match '^[0-9a-f-]{36}$'
            { [datetime]$report.operations[0].startedUtc | Out-Null } | Should -Not -Throw
            { [datetime]$report.operations[0].endedUtc | Out-Null } | Should -Not -Throw
            $report.operations[0].status | Should -Be 'Succeeded'
            $report.operations[0].durationMs | Should -BeGreaterOrEqual 0
            $report.operations[0].errorType | Should -BeNullOrEmpty
            $report.operations[0].errorMessage | Should -BeNullOrEmpty
        }
    }

    It 'Appends separate operations and sorts loose step numbers' {
        InModuleScope AzLocal.UpdateManagement {
            $path = Join-Path $TestDrive 'ordered\pipeline-timings.json'
            Invoke-AzLocalPipelineTimedOperation -PipelineName 'apply-updates' -StepNumber 30 -StepName 'Retry failed updates' -Path $path -ScriptBlock { } | Out-Null
            Invoke-AzLocalPipelineTimedOperation -PipelineName 'apply-updates' -StepNumber 10 -StepName 'Apply updates' -Path $path -ScriptBlock { } | Out-Null

            $report = Get-Content -LiteralPath $path -Raw | ConvertFrom-Json
            @($report.operations).Count | Should -Be 2
            @($report.operations.stepNumber) | Should -Be @(10, 30)
            @($report.operations.stepName) | Should -Be @('Apply updates', 'Retry failed updates')
        }
    }

    It 'Clears a handled native failure exit code when the workload succeeds' {
        InModuleScope AzLocal.UpdateManagement {
            $path = Join-Path $TestDrive 'handled-native-failure\pipeline-timings.json'
            $global:LASTEXITCODE = 0

            $result = Invoke-AzLocalPipelineTimedOperation `
                -PipelineName 'fleet-update-status' `
                -StepNumber 20 `
                -StepName 'Collect fleet update status' `
                -Path $path `
                -ScriptBlock {
                    $global:LASTEXITCODE = 1
                    'report-complete'
                }

            $result | Should -Be 'report-complete'
            $global:LASTEXITCODE | Should -Be 0
            (Get-Content -LiteralPath $path -Raw | ConvertFrom-Json).status | Should -Be 'Succeeded'
        }
    }

    It 'Records and rethrows failures while scrubbing credential fragments' {
        InModuleScope AzLocal.UpdateManagement {
            $path = Join-Path $TestDrive 'failed\pipeline-timings.json'
            {
                Invoke-AzLocalPipelineTimedOperation `
                    -PipelineName 'fleet-health-status' `
                    -StepNumber 20 `
                    -StepName 'Collect fleet health' `
                    -Path $path `
                    -ScriptBlock { throw 'Request failed access_token=secret-value' }
            } | Should -Throw -ExpectedMessage '*Request failed*'

            $report = Get-Content -LiteralPath $path -Raw | ConvertFrom-Json
            $report.status | Should -Be 'Failed'
            $report.operations[0].status | Should -Be 'Failed'
            $report.operations[0].errorType | Should -Be 'System.Management.Automation.RuntimeException'
            $report.operations[0].errorMessage | Should -Match 'access_token=<redacted>'
            $report | ConvertTo-Json -Depth 8 | Should -Not -Match 'secret-value'
        }
    }

    It 'Executes normally without writing a report when disabled' {
        InModuleScope AzLocal.UpdateManagement {
            $path = Join-Path $TestDrive 'disabled\pipeline-timings.json'
            $global:LASTEXITCODE = 0
            $result = Invoke-AzLocalPipelineTimedOperation -PipelineName 'monitor-updates' -StepNumber 20 -StepName 'Disabled timing' -Path $path -Enabled:$false -ScriptBlock {
                $global:LASTEXITCODE = 1
                'workload-output'
            }
            $result | Should -Be 'workload-output'
            $global:LASTEXITCODE | Should -Be 0
            Test-Path -LiteralPath $path | Should -BeFalse
        }
    }

    It 'All bundled pipeline workloads use the shared timed-operation success boundary' {
        $pipelineRoot = Join-Path $PSScriptRoot '..\Automation-Pipeline-Examples'
        $pipelineFiles = @(
            Get-ChildItem -LiteralPath (Join-Path $pipelineRoot 'github-actions') -Filter '*.yml'
            Get-ChildItem -LiteralPath (Join-Path $pipelineRoot 'azure-devops') -Filter '*.yml'
        )
        $timedPipelineFiles = @($pipelineFiles | Where-Object {
                (Get-Content -LiteralPath $_.FullName -Raw) -match 'Invoke-AzLocalPipelineTimedOperation'
            })

        $timedPipelineFiles.Count | Should -Be 20
        foreach ($pipelineFile in $timedPipelineFiles) {
            (Get-Content -LiteralPath $pipelineFile.FullName -Raw) |
                Should -Match 'Invoke-AzLocalPipelineTimedOperation' -Because "$($pipelineFile.FullName) must use the shared exit-code boundary"
        }
    }

    It 'Is exported as a first-class module command' {
        Get-Command Invoke-AzLocalPipelineTimedOperation -Module AzLocal.UpdateManagement |
            Should -Not -BeNullOrEmpty
    }
}

Describe 'v0.9.22 fleet-scale ARG payload contracts' {
    BeforeAll {
