        } | ConvertTo-Json -Depth 8 | Set-Content -Path $p -Encoding UTF8
        $cfg = Get-AzLocalItsmConfig -Path $p
        $cfg.SchemaVersion | Should -Be 1
        $cfg.Secrets['keyvaultName'] | Should -Be 'kv1'
