        $updaterDest = Join-Path $repoRoot 'Update-Module-And-Pipelines.ps1'
        $text = Get-Content -LiteralPath $updaterDest -Raw
        # Resolves its own repo-relative path from $PSCommandPath and appends it
        # to the staged paths, so an in-place self-refresh is committed/pushed.
        $text | Should -Match '\$PSCommandPath'
        $text | Should -Match '\$selfRel'
        $text | Should -Match 'if \(\$selfRel\) \{ \$candidatePaths \+= \$selfRel \}'
    }

    # v0.8.98: version-gated self-refresh. The dropped script carries an
    # '# AZLOCAL-UPDATER-VERSION: X.Y.Z' marker. Copy re-renders an existing
    # file IN PLACE only when its marker is STRICTLY OLDER than the bundled
    # template; an equal marker, or a markerless (operator-owned) file, is
    # preserved.

    It 'v0.8.98: bundled updater template carries an AZLOCAL-UPDATER-VERSION marker' {
        $repoRoot = Join-Path $script:cpDestRoot 'gh-updater-marker'
        $dest = Join-Path $repoRoot '.github\workflows'
        New-Item -Path $dest -ItemType Directory -Force | Out-Null

        Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub 6>$null | Out-Null

        $text = Get-Content -LiteralPath (Join-Path $repoRoot 'Update-Module-And-Pipelines.ps1') -Raw
        $text | Should -Match '(?im)^\s*#+\s*AZLOCAL-UPDATER-VERSION\s*:\s*\d+\.\d+\.\d+\s*$'
    }

    It 'v0.8.98: existing updater script with an OLDER version marker is refreshed in place' {
        $repoRoot = Join-Path $script:cpDestRoot 'gh-updater-older'
        $dest = Join-Path $repoRoot '.github\workflows'
        New-Item -Path $dest -ItemType Directory -Force | Out-Null

        $updaterDest = Join-Path $repoRoot 'Update-Module-And-Pipelines.ps1'
        # Simulate a stale prior drop: an OLD version marker + an operator
        # body that the refresh is expected to replace.
        $stale = @(
            '#Requires -Version 5.1'
            '# AZLOCAL-UPDATER-VERSION: 0.0.1'
            '# STALE BODY - should be replaced on refresh'
        ) -join "`r`n"
        Set-Content -LiteralPath $updaterDest -Value $stale -Encoding ASCII

        Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub 6>$null | Out-Null

        $text = Get-Content -LiteralPath $updaterDest -Raw
        $text | Should -Not -Match 'STALE BODY'
        $text | Should -Not -Match '0\.0\.1'
        $text | Should -Match "Platform\s*=\s*'GitHub'"
    }

    It 'v0.8.98: existing updater script with an EQUAL version marker is preserved (not re-rendered)' {
        $repoRoot = Join-Path $script:cpDestRoot 'gh-updater-equal'
        $dest = Join-Path $repoRoot '.github\workflows'
        New-Item -Path $dest -ItemType Directory -Force | Out-Null

        # First drop establishes the current bundled marker version.
        Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub 6>$null | Out-Null
        $updaterDest = Join-Path $repoRoot 'Update-Module-And-Pipelines.ps1'

        # Append an operator sentinel; a second invocation at the SAME version
        # must leave the updater file (and the sentinel) untouched. -Update is
        # required so the pre-existing workflow YAMLs do not trip the
        # no-overwrite guard before the updater logic runs.
        Add-Content -LiteralPath $updaterDest -Value "`r`n# OPERATOR SENTINEL EQUAL-VERSION"
        Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub -Update -Confirm:$false 6>$null | Out-Null

        (Get-Content -LiteralPath $updaterDest -Raw) | Should -Match 'OPERATOR SENTINEL EQUAL-VERSION'
    }

    It 'v0.8.98: existing markerless (operator-owned) updater script is preserved' {
        $repoRoot = Join-Path $script:cpDestRoot 'gh-updater-markerless'
        $dest = Join-Path $repoRoot '.github\workflows'
        New-Item -Path $dest -ItemType Directory -Force | Out-Null

        $updaterDest = Join-Path $repoRoot 'Update-Module-And-Pipelines.ps1'
        Set-Content -LiteralPath $updaterDest -Value '# NO VERSION MARKER - operator-owned' -Encoding ASCII

        Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub 6>$null | Out-Null

        (Get-Content -LiteralPath $updaterDest -Raw) | Should -Match 'operator-owned'
    }

    # v0.9.0: managed repo README drop (default-on for -Platform
    # GitHub|AzureDevOps; suppressed by -SkipReadme). Lands a lightweight,
    # link-first README.md at the REPO ROOT only when the repo has no usable
    # README (missing / whitespace-only / GitHub default stub); refreshes an
    # existing managed README (carrying the hidden AZLOCAL-README-VERSION
    # marker) only when the bundled template is newer; preserves any other
    # non-empty README as operator-owned.
    Context 'v0.9.0 managed repo README drop' {

        It '-SkipReadme is exposed as a [switch] parameter' {
            $cmd = Get-Command -Name 'Copy-AzLocalPipelineExample' -ErrorAction Stop
            $cmd.Parameters.ContainsKey('SkipReadme') | Should -BeTrue
            $cmd.Parameters['SkipReadme'].ParameterType | Should -Be ([switch])
        }

        It '-Platform GitHub default drops a managed README.md into the repo root' {
            $repoRoot = Join-Path $script:cpDestRoot 'gh-readme-fresh'
            $dest = Join-Path $repoRoot '.github\workflows'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub 6>$null | Out-Null

            $readmeDest = Join-Path $repoRoot 'README.md'
            Test-Path $readmeDest | Should -BeTrue
            $text = Get-Content -LiteralPath $readmeDest -Raw
            $text | Should -Match '(?im)AZLOCAL-README-VERSION\s*:\s*\d+\.\d+\.\d+'
        }

        It '-Platform AzureDevOps default drops a managed README.md into the repo root' {
            $repoRoot = Join-Path $script:cpDestRoot 'ado-readme-fresh'
            $dest = Join-Path $repoRoot 'pipelines'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            Copy-AzLocalPipelineExample -Destination $dest -Platform AzureDevOps 6>$null | Out-Null

            Test-Path (Join-Path $repoRoot 'README.md') | Should -BeTrue
        }

        It 'dropped README has the placeholder tokens substituted and both aka.ms links' {
            $repoRoot = Join-Path $script:cpDestRoot 'gh-readme-tokens'
            $dest = Join-Path $repoRoot '.github\workflows'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub 6>$null | Out-Null

            $text = Get-Content -LiteralPath (Join-Path $repoRoot 'README.md') -Raw
            $text | Should -Not -Match '__PLATFORM__'
            $text | Should -Not -Match '__WORKFLOW_SUBPATH__'
            $text | Should -Match 'GitHub'
            $text | Should -Match '\.github/workflows'
            $text | Should -Match 'https://aka\.ms/AzLocal\.UpdateManagement'
            $text | Should -Match 'https://aka\.ms/AzLocal\.UpdateManagement/CICD'
        }

        It 'dropped README is written WITHOUT a UTF-8 BOM' {
            $repoRoot = Join-Path $script:cpDestRoot 'gh-readme-bom'
            $dest = Join-Path $repoRoot '.github\workflows'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub 6>$null | Out-Null

            $bytes = [System.IO.File]::ReadAllBytes((Join-Path $repoRoot 'README.md'))
            ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) | Should -BeFalse
        }

        It 'replaces a GitHub default-stub README (H1 = repo name) with the managed README' {
            $repoRoot = Join-Path $script:cpDestRoot 'gh-readme-stub'
            $dest = Join-Path $repoRoot '.github\workflows'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            $readmeDest = Join-Path $repoRoot 'README.md'
            # GitHub "Add a README" default: a single H1 of the repo folder name.
            Set-Content -LiteralPath $readmeDest -Value '# gh-readme-stub' -Encoding ASCII

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub 6>$null | Out-Null

            (Get-Content -LiteralPath $readmeDest -Raw) | Should -Match '(?im)AZLOCAL-README-VERSION'
        }

        It 'preserves an operator-owned README (real content, no marker)' {
            $repoRoot = Join-Path $script:cpDestRoot 'gh-readme-owned'
            $dest = Join-Path $repoRoot '.github\workflows'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            $readmeDest = Join-Path $repoRoot 'README.md'
            $owned = @(
                '# gh-readme-owned'
                ''
                '## Our internal runbook'
                '- do not touch this file'
                '- it is operator-owned'
            ) -join "`r`n"
            Set-Content -LiteralPath $readmeDest -Value $owned -Encoding ASCII

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub 6>$null | Out-Null

            $text = Get-Content -LiteralPath $readmeDest -Raw
            $text | Should -Match 'operator-owned'
            $text | Should -Not -Match 'AZLOCAL-README-VERSION'
        }

        It 'refreshes an existing managed README with an OLDER version marker' {
            $repoRoot = Join-Path $script:cpDestRoot 'gh-readme-older'
            $dest = Join-Path $repoRoot '.github\workflows'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            $readmeDest = Join-Path $repoRoot 'README.md'
            $stale = @(
                '<!-- AZLOCAL-README-VERSION: 0.0.1 -->'
                '# Stale managed README'
                'OLD MANAGED BODY - should be replaced on refresh'
            ) -join "`r`n"
            Set-Content -LiteralPath $readmeDest -Value $stale -Encoding ASCII

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub 6>$null | Out-Null

            $text = Get-Content -LiteralPath $readmeDest -Raw
            $text | Should -Not -Match 'OLD MANAGED BODY'
            $text | Should -Match 'https://aka\.ms/AzLocal\.UpdateManagement'
        }

        It 'preserves an existing managed README with an EQUAL version marker' {
            $repoRoot = Join-Path $script:cpDestRoot 'gh-readme-equal'
            $dest = Join-Path $repoRoot '.github\workflows'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            # First drop establishes the current bundled README version.
            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub 6>$null | Out-Null
            $readmeDest = Join-Path $repoRoot 'README.md'

            # Append a sentinel; a second invocation at the SAME version must
            # leave the README (and the sentinel) untouched.
            Add-Content -LiteralPath $readmeDest -Value "`r`n<!-- OPERATOR SENTINEL EQUAL-VERSION -->"
            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub -Update -Confirm:$false 6>$null | Out-Null

            (Get-Content -LiteralPath $readmeDest -Raw) | Should -Match 'OPERATOR SENTINEL EQUAL-VERSION'
        }

        It '-SkipReadme suppresses the README drop entirely' {
            $repoRoot = Join-Path $script:cpDestRoot 'gh-readme-skip'
            $dest = Join-Path $repoRoot '.github\workflows'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub -SkipReadme 6>$null | Out-Null

            Test-Path (Join-Path $repoRoot 'README.md') | Should -BeFalse
        }

        It '-Platform All does NOT drop a managed README at a repo root' {
            $parent = Join-Path $script:cpDestRoot 'all-no-readme-parent'
            New-Item -Path $parent -ItemType Directory -Force | Out-Null
            $dest = Join-Path $parent 'all-no-readme'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            Copy-AzLocalPipelineExample -Destination $dest 6>$null | Out-Null

            Test-Path (Join-Path $parent 'README.md') | Should -BeFalse
            Test-Path (Join-Path $dest   'README.md') | Should -BeFalse
        }

        It '-WhatIf does not write the README' {
            $repoRoot = Join-Path $script:cpDestRoot 'gh-readme-whatif'
            $dest = Join-Path $repoRoot '.github\workflows'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub -WhatIf 6>$null | Out-Null

            Test-Path (Join-Path $repoRoot 'README.md') | Should -BeFalse
        }

        It 'v1.2.0 template: dropped updater script conditionally stages the managed README' {
            $repoRoot = Join-Path $script:cpDestRoot 'gh-readme-stage'
            $dest = Join-Path $repoRoot '.github\workflows'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub 6>$null | Out-Null

            $text = Get-Content -LiteralPath (Join-Path $repoRoot 'Update-Module-And-Pipelines.ps1') -Raw
            # Stages README.md only when it carries the managed marker.
            $text | Should -Match 'AZLOCAL-README-VERSION'
            $text | Should -Match "\`$candidatePaths \+= 'README\.md'"
        }
    }

    # v0.8.85: -PruneDeprecated removes the legacy authentication-test.yml /
    # inventory-clusters.yml sample files that were merged into the single
    # setup-validate-and-inventory.yml workflow. The cleanup is opt-in,
    # GitHub-only, ID-verified (each candidate's AZLOCAL-PIPELINE-ID must match
    # the expected value before deletion) and ShouldProcess-gated.
    Context 'v0.8.85 -PruneDeprecated cleanup of merged setup workflow files' {

        It '-PruneDeprecated is exposed as a [switch] parameter' {
            $cmd = Get-Command -Name 'Copy-AzLocalPipelineExample' -ErrorAction Stop
            $cmd.Parameters.ContainsKey('PruneDeprecated') | Should -BeTrue
            $cmd.Parameters['PruneDeprecated'].ParameterType | Should -Be ([switch])
        }

        It 'removes BOTH deprecated files when their AZLOCAL-PIPELINE-IDs match' {
            $dest = Join-Path $script:cpDestRoot 'prune-both'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null
            # Seed the two legacy files with their canonical IDs so the
            # ID-verification gate allows deletion.
            Set-Content -LiteralPath (Join-Path $dest 'authentication-test.yml') -Value '# AZLOCAL-PIPELINE-ID: authentication-test' -Encoding ASCII
            Set-Content -LiteralPath (Join-Path $dest 'inventory-clusters.yml')  -Value '# AZLOCAL-PIPELINE-ID: inventory-clusters'  -Encoding ASCII

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub -PruneDeprecated -Confirm:$false 6>$null | Out-Null

            Test-Path (Join-Path $dest 'authentication-test.yml') | Should -BeFalse
            Test-Path (Join-Path $dest 'inventory-clusters.yml')  | Should -BeFalse
            # The merged replacement must be present.
            Test-Path (Join-Path $dest 'setup-validate-and-inventory.yml') | Should -BeTrue
        }

        It 'removes only the single deprecated file that is present' {
            $dest = Join-Path $script:cpDestRoot 'prune-single'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null
            Set-Content -LiteralPath (Join-Path $dest 'inventory-clusters.yml') -Value '# AZLOCAL-PIPELINE-ID: inventory-clusters' -Encoding ASCII

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub -PruneDeprecated -Confirm:$false 6>$null | Out-Null

            Test-Path (Join-Path $dest 'inventory-clusters.yml') | Should -BeFalse
            Test-Path (Join-Path $dest 'setup-validate-and-inventory.yml') | Should -BeTrue
        }

        It 'preserves a deprecated-named file whose AZLOCAL-PIPELINE-ID does not match' {
            $dest = Join-Path $script:cpDestRoot 'prune-mismatch'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null
            # An operator-owned file that merely happens to share the legacy
            # name but carries a different ID must NOT be deleted.
            Set-Content -LiteralPath (Join-Path $dest 'authentication-test.yml') -Value '# AZLOCAL-PIPELINE-ID: my-custom-auth-workflow' -Encoding ASCII

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub -PruneDeprecated -Confirm:$false 6>$null 3>$null | Out-Null

            Test-Path (Join-Path $dest 'authentication-test.yml') | Should -BeTrue
        }

        It 'leaves deprecated files untouched when -PruneDeprecated is NOT supplied' {
            $dest = Join-Path $script:cpDestRoot 'prune-omitted'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null
            Set-Content -LiteralPath (Join-Path $dest 'authentication-test.yml') -Value '# AZLOCAL-PIPELINE-ID: authentication-test' -Encoding ASCII
            Set-Content -LiteralPath (Join-Path $dest 'inventory-clusters.yml')  -Value '# AZLOCAL-PIPELINE-ID: inventory-clusters'  -Encoding ASCII

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub 6>$null 3>$null | Out-Null

            Test-Path (Join-Path $dest 'authentication-test.yml') | Should -BeTrue
            Test-Path (Join-Path $dest 'inventory-clusters.yml')  | Should -BeTrue
        }

        It '-PruneDeprecated -WhatIf does not delete the deprecated files' {
            $dest = Join-Path $script:cpDestRoot 'prune-whatif'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null
            Set-Content -LiteralPath (Join-Path $dest 'authentication-test.yml') -Value '# AZLOCAL-PIPELINE-ID: authentication-test' -Encoding ASCII
            Set-Content -LiteralPath (Join-Path $dest 'inventory-clusters.yml')  -Value '# AZLOCAL-PIPELINE-ID: inventory-clusters'  -Encoding ASCII

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub -PruneDeprecated -WhatIf 6>$null | Out-Null

            Test-Path (Join-Path $dest 'authentication-test.yml') | Should -BeTrue
            Test-Path (Join-Path $dest 'inventory-clusters.yml')  | Should -BeTrue
        }
    }

    Context 'Fleet settings starter lifecycle' {
        It 'Creates the inert starter at the repository config path' {
            $repoRoot = Join-Path $script:cpDestRoot 'fleet-settings-create'
            $dest = Join-Path $repoRoot '.github\workflows'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub -Confirm:$false 6>$null | Out-Null

            $settingsPath = Join-Path $repoRoot 'config\fleet-settings.yml'
            Test-Path -LiteralPath $settingsPath | Should -BeTrue
            (Get-AzLocalFleetSettings -Path $settingsPath).ScopeMode | Should -Be 'ImplicitSubscriptions'
            $starterText = Get-Content -LiteralPath $settingsPath -Raw
            $starterText | Should -Match '(?m)^# schemaVersion: 4\r?$'
            $starterText | Should -Match '(?m)^# updateStartWindow:\r?$'
            $starterText | Should -Match '(?m)^#   allowBeforeMinutes: 0\r?$'
            $starterText | Should -Match '(?m)^#   allowAfterMinutes: 0\r?$'
        }

        It 'Preserves an existing operator-owned settings file' {
            $repoRoot = Join-Path $script:cpDestRoot 'fleet-settings-preserve'
            $dest = Join-Path $repoRoot '.github\workflows'
            $settingsPath = Join-Path $repoRoot 'config\fleet-settings.yml'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null
            New-Item -Path (Split-Path -Parent $settingsPath) -ItemType Directory -Force | Out-Null
            Set-Content -LiteralPath $settingsPath -Value "schemaVersion: 1`n# OPERATOR SENTINEL" -Encoding ASCII

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub -Confirm:$false 6>$null | Out-Null

            (Get-Content -LiteralPath $settingsPath -Raw) | Should -Match 'OPERATOR SENTINEL'
        }

        It 'Does not create the starter when skipped or under WhatIf' -TestCases @(
            @{ Name = 'skip'; Arguments = @{ SkipStarterFleetSettings = $true; Confirm = $false } }
            @{ Name = 'whatif'; Arguments = @{ WhatIf = $true } }
        ) {
            param($Name, $Arguments)
            $repoRoot = Join-Path $script:cpDestRoot ("fleet-settings-{0}" -f $Name)
            $dest = Join-Path $repoRoot '.github\workflows'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null

            Copy-AzLocalPipelineExample -Destination $dest -Platform GitHub @Arguments 6>$null | Out-Null

            Test-Path -LiteralPath (Join-Path $repoRoot 'config\fleet-settings.yml') | Should -BeFalse
        }
    }

    Context 'Schema v4 UpdateStartWindow allowance wiring' {
        It 'Reads both fleet settings allowances and forwards them to the schedule gate' {
            $source = Get-Content -LiteralPath (Join-Path $PSScriptRoot '..\Public\Start-AzLocalClusterUpdate.ps1') -Raw

            $source | Should -Match 'Get-AzLocalFleetSettings'
            $source | Should -Match 'UpdateStartWindowAllowBeforeMinutes'
            $source | Should -Match 'UpdateStartWindowAllowAfterMinutes'
            $source | Should -Match '(?s)Test-AzLocalUpdateScheduleAllowed.+-AllowBeforeMinutes \$updateStartWindowAllowBeforeMinutes.+-AllowAfterMinutes \$updateStartWindowAllowAfterMinutes'
        }
    }
}

#endregion Copy-AzLocalPipelineExample (v0.7.4, updated in v0.7.50, v0.7.92)

#region Copy-AzLocalItsmSample (v0.7.50)

Describe 'Function: Copy-AzLocalItsmSample' {
    BeforeAll {
        # See Copy-AzLocalPipelineExample BeforeAll: normalise $env:TEMP to its
        # canonical long-form path so the FullName string-equality assertions
        # survive runners where $env:TEMP returns an 8.3 short name (CI).
        $tempLong = (Get-Item -LiteralPath $env:TEMP).FullName
        $script:itsmDestRoot = Join-Path $tempLong "azlocal-itsm-$([guid]::NewGuid().Guid.Substring(0,8))"
        New-Item -Path $script:itsmDestRoot -ItemType Directory -Force | Out-Null
    }

    AfterAll {
        Remove-Item $script:itsmDestRoot -Recurse -Force -ErrorAction SilentlyContinue
    }

    It 'Is exported by the module' {
        $cmd = Get-Command -Name 'Copy-AzLocalItsmSample' -Module 'AzLocal.UpdateManagement' -ErrorAction Stop
        $cmd | Should -Not -BeNullOrEmpty
        $cmd.CommandType | Should -Be 'Function'
    }

    It 'Default -Destination ends in .itsm' {
        $cmd = Get-Command -Name 'Copy-AzLocalItsmSample' -ErrorAction Stop
        # Look at the default value embedded in the function source
        $src = $cmd.ScriptBlock.ToString()
        $src | Should -Match "Join-Path\s+-Path\s+\`$PWD\.Path\s+-ChildPath\s+'\.itsm'"
    }

    It '-WhatIf does not copy anything' {
        $dest = Join-Path $script:itsmDestRoot 'whatif'
        # Note: dest does not yet exist; -WhatIf should not create file contents either
        Copy-AzLocalItsmSample -Destination $dest -WhatIf 6>$null
        # No YAML should have been written even if the directory was created
        Test-Path (Join-Path $dest 'azurelocal-itsm.yml') | Should -BeFalse
    }

    It 'Default copy: writes azurelocal-itsm.yml and templates/incident-body.md' {
        $dest = Join-Path $script:itsmDestRoot 'default'
        $r = Copy-AzLocalItsmSample -Destination $dest -PassThru 6>$null

        $r | Should -BeOfType [System.IO.DirectoryInfo]
        $r.FullName | Should -Be $dest
        Test-Path (Join-Path $dest 'azurelocal-itsm.yml') | Should -BeTrue
        Test-Path (Join-Path $dest 'templates\incident-body.md') | Should -BeTrue
    }

    It 'Refuses to overwrite an existing file by default and points at -Update' {
        $dest = Join-Path $script:itsmDestRoot 'no-overwrite'
        Copy-AzLocalItsmSample -Destination $dest 6>$null | Out-Null

        { Copy-AzLocalItsmSample -Destination $dest 6>$null } |
            Should -Throw -ExpectedMessage '*refusing to overwrite*'
        { Copy-AzLocalItsmSample -Destination $dest 6>$null } |
            Should -Throw -ExpectedMessage '*-Update*'
    }

    It '-Update -Confirm:$false overwrites existing files without prompting (automation path)' {
        $dest = Join-Path $script:itsmDestRoot 'update-confirm-false'
        Copy-AzLocalItsmSample -Destination $dest 6>$null | Out-Null

        $target = Join-Path $dest 'azurelocal-itsm.yml'
        $sentinel = '# SENTINEL - if this survives, -Update did not overwrite'
        Set-Content -LiteralPath $target -Value $sentinel -Encoding ASCII
        (Get-Content -LiteralPath $target -Raw) | Should -Match 'SENTINEL'

        { Copy-AzLocalItsmSample -Destination $dest -Update -Confirm:$false 6>$null } |
            Should -Not -Throw

        (Get-Content -LiteralPath $target -Raw) | Should -Not -Match 'SENTINEL'
    }

    It '-Update -WhatIf does not modify any existing files' {
        $dest = Join-Path $script:itsmDestRoot 'update-whatif'
        Copy-AzLocalItsmSample -Destination $dest 6>$null | Out-Null

        $target = Join-Path $dest 'azurelocal-itsm.yml'
        $sentinel = '# WHATIF SENTINEL - -WhatIf must preserve this'
        Set-Content -LiteralPath $target -Value $sentinel -Encoding ASCII

        Copy-AzLocalItsmSample -Destination $dest -Update -WhatIf 6>$null

        (Get-Content -LiteralPath $target -Raw) | Should -Match 'WHATIF SENTINEL'
    }

    It '-Update is exposed as a [switch] parameter' {
        $cmd = Get-Command -Name 'Copy-AzLocalItsmSample' -ErrorAction Stop
        $cmd.Parameters.ContainsKey('Update') | Should -BeTrue
        $cmd.Parameters['Update'].ParameterType | Should -Be ([switch])
    }

    It 'Has the No-to-All only-when-destExists regression guard (matches Copy-AzLocalPipelineExample fix)' {
        $cmd = Get-Command -Name 'Copy-AzLocalItsmSample' -ErrorAction Stop
        $src = $cmd.ScriptBlock.ToString()
        $src | Should -Match 'if\s*\(\s*\$noToAll\s+-and\s+\$destExists\s*\)'
    }

    It '-PassThru returns a DirectoryInfo; without it nothing is emitted to the pipeline' {
        $dest = Join-Path $script:itsmDestRoot 'passthru'
        $withPT = Copy-AzLocalItsmSample -Destination $dest -PassThru 6>$null
        $withPT | Should -BeOfType [System.IO.DirectoryInfo]
        $withPT.FullName | Should -Be $dest

        $dest2 = Join-Path $script:itsmDestRoot 'nopassthru'
        $noPT = Copy-AzLocalItsmSample -Destination $dest2 6>$null
        $noPT | Should -BeNullOrEmpty
    }

    It 'Creates -Destination (including templates subfolder) when it does not already exist' {
        $dest = Join-Path $script:itsmDestRoot 'autocreate'
        Test-Path $dest | Should -BeFalse

        Copy-AzLocalItsmSample -Destination $dest 6>$null | Out-Null

        Test-Path $dest | Should -BeTrue
        Test-Path (Join-Path $dest 'templates') | Should -BeTrue
        Test-Path (Join-Path $dest 'templates\incident-body.md') | Should -BeTrue
    }
}

#endregion Copy-AzLocalItsmSample (v0.7.50)

#region Apply-Updates Schedule Coverage Advisor (v0.7.65)

Describe 'Function: Test-AzLocalApplyUpdatesScheduleCoverage' {

    Context 'Parameter Validation' {
        BeforeAll {
            $command = Get-Command Test-AzLocalApplyUpdatesScheduleCoverage
        }

        It 'Is CmdletBinding' {
            $command.CmdletBinding | Should -BeTrue
        }

        It 'Should have View parameter with ValidateSet (Audit, Matrix, Recommend)' {
            $command.Parameters.Keys | Should -Contain 'View'
            $vs = $command.Parameters['View'].Attributes | Where-Object { $_ -is [System.Management.Automation.ValidateSetAttribute] }
            $vs | Should -Not -BeNullOrEmpty
            ($vs.ValidValues | Sort-Object) | Should -Be (@('Audit','Matrix','Recommend') | Sort-Object)
        }

        It 'Should have Platform parameter with ValidateSet (GitHubActions, AzureDevOps, Both)' {
            $command.Parameters.Keys | Should -Contain 'Platform'
            $vs = $command.Parameters['Platform'].Attributes | Where-Object { $_ -is [System.Management.Automation.ValidateSetAttribute] }
            $vs | Should -Not -BeNullOrEmpty
            ($vs.ValidValues | Sort-Object) | Should -Be (@('AzureDevOps','Both','GitHubActions') | Sort-Object)
        }

        It 'Should have LeadTimeMinutes parameter with ValidateRange 0..60' {
            $command.Parameters.Keys | Should -Contain 'LeadTimeMinutes'
            $vr = $command.Parameters['LeadTimeMinutes'].Attributes | Where-Object { $_ -is [System.Management.Automation.ValidateRangeAttribute] }
            $vr | Should -Not -BeNullOrEmpty
            $vr.MinRange | Should -Be 0
            $vr.MaxRange | Should -Be 60
        }

        It 'Should have SubscriptionId, PipelineYamlPath, UpdateRingTag, IncludeUntagged, ExportPath, PassThru parameters' {
            foreach ($p in @('SubscriptionId','PipelineYamlPath','UpdateRingTag','IncludeUntagged','ExportPath','PassThru')) {
                $command.Parameters.Keys | Should -Contain $p
            }
        }

        It 'Declares [OutputType([PSCustomObject[]])]' {
            # PSCustomObject is a PowerShell accelerator for PSObject, so the
            # resolved type name on the OutputTypeAttribute is 'PSObject[]'.
            $command.OutputType.Type.Name | Should -Contain 'PSObject[]'
        }

        It 'Throws when -View Audit is used without -PipelineYamlPath or -SchedulePath' {
            InModuleScope AzLocal.UpdateManagement {
                Mock Invoke-AzResourceGraphQuery { @() }
                { Test-AzLocalApplyUpdatesScheduleCoverage -View Audit } |
                    Should -Throw -ExpectedMessage '*requires at least one of -PipelineYamlPath or -SchedulePath*'
            }
        }

        It 'Throws when PipelineYamlPath does not exist' {
            InModuleScope AzLocal.UpdateManagement {
                Mock Invoke-AzResourceGraphQuery { @() }
                { Test-AzLocalApplyUpdatesScheduleCoverage -View Audit -PipelineYamlPath 'X:\does\not\exist.yml' } |
                    Should -Throw -ExpectedMessage '*PipelineYamlPath not found*'
            }
        }
    }

    Context 'Private helper: Convert-AzLocalUpdateWindowToCron' {
        It 'Uses a seven-minute default to avoid crowded scheduler boundaries' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Sat-Sun_02:00-06:00'
                $r | Should -HaveCount 1
                $r[0].CronExpression | Should -Be '53 1 * * 6,0'
            }
        }

        It 'Sat-Sun_02:00-06:00 with lead 5 -> 55 1 * * 6,0' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Sat-Sun_02:00-06:00' -LeadTimeMinutes 5
                $r | Should -HaveCount 1
                $r[0].CronExpression | Should -Be '55 1 * * 6,0'
                $r[0].FireHour | Should -Be 1
                $r[0].FireMinute | Should -Be 55
                $r[0].DayShift | Should -BeFalse
            }
        }

        It 'Mon-Fri_22:00-04:00 with lead 5 -> 55 21 * * 1-5 (range)' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Mon-Fri_22:00-04:00' -LeadTimeMinutes 5
                $r | Should -HaveCount 1
                $r[0].CronExpression | Should -Be '55 21 * * 1-5'
            }
        }

        It 'Sun_03:00-07:00 with lead 5 -> 55 2 * * 0' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Sun_03:00-07:00' -LeadTimeMinutes 5
                $r[0].CronExpression | Should -Be '55 2 * * 0'
            }
        }

        It 'Lead-time wrap: Mon_00:05-04:00 with lead 10 -> 55 23 * * 0 (Sun) with DayShift=$true' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Mon_00:05-04:00' -LeadTimeMinutes 10
                $r[0].CronExpression | Should -Be '55 23 * * 0'
                $r[0].DayShift | Should -BeTrue
            }
        }

        It 'Multi-segment window emits one cron per segment' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Mon-Fri_22:00-04:00;Sat-Sun_02:00-10:00' -LeadTimeMinutes 5
                $r | Should -HaveCount 2
                ($r | ForEach-Object CronExpression) -join '|' | Should -Be '55 21 * * 1-5|55 1 * * 6,0'
            }
        }
    }

    Context 'Private helper: Convert-AzLocalUpdateWindowToCron -FiresPerWindow 2 (belt-and-braces, v0.7.92)' {
        It 'FiresPerWindow=1 (default) is back-compat: one row per segment, IsRetry=false' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Sat-Sun_02:00-06:00' -LeadTimeMinutes 5
                $r | Should -HaveCount 1
                $r[0].IsRetry | Should -BeFalse
            }
        }

        It '4h window Sat-Sun_02:00-06:00: open at 01:55, retry de-contented before the +60min target' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Sat-Sun_02:00-06:00' -LeadTimeMinutes 5 -FiresPerWindow 2
                $r | Should -HaveCount 2
                $r[0].CronExpression | Should -Be '55 1 * * 6,0'
                $r[0].IsRetry | Should -BeFalse
                $r[1].CronExpression | Should -Be '53 2 * * 6,0'
                $r[1].IsRetry | Should -BeTrue
                $r[1].DayShift | Should -BeFalse
            }
        }

        It '3h window Mon-Fri_20:00-23:00: open at 19:55, retry de-contented before the +60min target' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Mon-Fri_20:00-23:00' -LeadTimeMinutes 5 -FiresPerWindow 2
                $r | Should -HaveCount 2
                $r[0].CronExpression | Should -Be '55 19 * * 1-5'
                $r[1].CronExpression | Should -Be '53 20 * * 1-5'
                $r[1].IsRetry | Should -BeTrue
            }
        }

        It '6h overnight Mon-Fri_22:00-04:00: retry at 22:53 with no day shift' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Mon-Fri_22:00-04:00' -LeadTimeMinutes 5 -FiresPerWindow 2
                $r | Should -HaveCount 2
                $r[0].CronExpression | Should -Be '55 21 * * 1-5'
                $r[1].CronExpression | Should -Be '53 22 * * 1-5'
                $r[1].IsRetry | Should -BeTrue
                $r[1].DayShift | Should -BeFalse
            }
        }

        It 'Short window Sat_03:00-03:30 (30min): retry de-contented to 03:08' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Sat_03:00-03:30' -LeadTimeMinutes 5 -FiresPerWindow 2
                $r | Should -HaveCount 2
                $r[0].CronExpression | Should -Be '55 2 * * 6'
                $r[1].CronExpression | Should -Be '8 3 * * 6'
                $r[1].IsRetry | Should -BeTrue
            }
        }

        It 'Overnight crossing midnight: Mon_23:30-00:30 retry de-contented to Mon 23:53' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Mon_23:30-00:30' -LeadTimeMinutes 5 -FiresPerWindow 2
                $r | Should -HaveCount 2
                # Open: 23:30 - 5min lead = 23:25 Mon (no shift, still Mon).
                $r[0].CronExpression | Should -Be '25 23 * * 1'
                $r[0].DayShift | Should -BeFalse
                # Retry target is midnight; seven-minute de-contention keeps it on Monday.
                $r[1].CronExpression | Should -Be '53 23 * * 1'
                $r[1].IsRetry | Should -BeTrue
                $r[1].DayShift | Should -BeFalse
            }
        }

        It '24h-style window Mon-Fri_00:00-23:00: retry de-contented before the +60min target' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Mon-Fri_00:00-23:00' -LeadTimeMinutes 0 -FiresPerWindow 2
                $r | Should -HaveCount 2
                $r[0].CronExpression | Should -Be '0 0 * * 1-5'
                # 23h = 1380min, midpoint 690min, capped to 60 -> 01:00.
                $r[1].CronExpression | Should -Be '53 0 * * 1-5'
                $r[1].IsRetry | Should -BeTrue
                $r[1].DayShift | Should -BeFalse
            }
        }

        It 'Multi-segment window with FiresPerWindow=2 emits TWO rows per segment (4 total)' {
            InModuleScope AzLocal.UpdateManagement {
                $r = Convert-AzLocalUpdateWindowToCron -UpdateStartWindow 'Mon-Fri_22:00-04:00;Sat-Sun_02:00-06:00' -LeadTimeMinutes 5 -FiresPerWindow 2
                $r | Should -HaveCount 4
                @($r | Where-Object IsRetry -eq $false).Count | Should -Be 2
                @($r | Where-Object IsRetry -eq $true).Count  | Should -Be 2
            }
        }
    }

    Context 'Private helper: ConvertFrom-AzLocalCronExpression' {
        It 'Parses 55 1 * * 6,0 and enumerates 2 fire times in the reference week' {
            InModuleScope AzLocal.UpdateManagement {
                $p = ConvertFrom-AzLocalCronExpression -Expression '55 1 * * 6,0'
                $p.IsValid | Should -BeTrue
                $p.IsComplex | Should -BeFalse
                @($p.FireTimes).Count | Should -Be 2
            }
        }

        It 'Parses comma-separated minutes (0,15,30,45) into 4 entries per hour' {
            InModuleScope AzLocal.UpdateManagement {
                $p = ConvertFrom-AzLocalCronExpression -Expression '0,15,30,45 2 * * 1'
                $p.IsValid | Should -BeTrue
                @($p.FireTimes).Count | Should -Be 4
            }
        }

        It 'Flags non-* DayOfMonth as IsComplex (advisor cannot evaluate)' {
            InModuleScope AzLocal.UpdateManagement {
                $p = ConvertFrom-AzLocalCronExpression -Expression '0 2 15 * *'
                $p.IsValid | Should -BeTrue
                $p.IsComplex | Should -BeTrue
                @($p.FireTimes).Count | Should -Be 0
            }
        }

        It 'Parses */15 step syntax (v0.7.67) and enumerates 4 fires per hour' {
            # v0.7.67: cron step syntax is now supported. Pre-v0.7.67 this
            # asserted IsValid=$false and ErrorMessage matched "not supported";
            # the advisor would falsely flag every-15-minute crons as
            # UnparseableCron even though GitHub Actions and Azure DevOps
            # both honour the syntax.
            InModuleScope AzLocal.UpdateManagement {
                $p = ConvertFrom-AzLocalCronExpression -Expression '*/15 * * * *'
                $p.IsValid | Should -BeTrue
                $p.IsComplex | Should -BeFalse
                # 60 / 15 = 4 minutes per hour * 24 hours * 7 days = 672 fires.
                @($p.FireTimes).Count | Should -Be 672
            }
        }

        It 'Parses bounded step range 9-17/2 in the hour field (v0.7.67)' {
            InModuleScope AzLocal.UpdateManagement {
                # 0 9-17/2 * * 1-5 -> hours 9,11,13,15,17 on weekdays = 5 fires/day * 5 days = 25.
                $p = ConvertFrom-AzLocalCronExpression -Expression '0 9-17/2 * * 1-5'
                $p.IsValid | Should -BeTrue
                $p.IsComplex | Should -BeFalse
                @($p.FireTimes).Count | Should -Be 25
            }
        }

        It 'Parses start-anchored step 5/15 in the minute field (v0.7.67)' {
            InModuleScope AzLocal.UpdateManagement {
                # 5/15 in minute (0-59) -> 5,20,35,50 = 4 fires per hour.
                $p = ConvertFrom-AzLocalCronExpression -Expression '5/15 * * * 1'
                $p.IsValid | Should -BeTrue
                @($p.FireTimes).Count | Should -Be (4 * 24)
                # First fire should be at minute 5, not 0.
                $p.FireTimes[0].Minute | Should -Be 5
            }
        }

        It 'Rejects step expressions with non-positive N (v0.7.67)' {
            InModuleScope AzLocal.UpdateManagement {
                $p = ConvertFrom-AzLocalCronExpression -Expression '*/0 * * * *'
                $p.IsValid | Should -BeFalse
                $p.ErrorMessage | Should -Match 'positive integer'
            }
        }

        It 'Rejects wrong field count' {
            InModuleScope AzLocal.UpdateManagement {
                $p = ConvertFrom-AzLocalCronExpression -Expression '0 2 * *'
                $p.IsValid | Should -BeFalse
                $p.ErrorMessage | Should -Match '5 cron fields'
            }
        }

        It 'Treats DOW=7 as Sunday (== 0)' {
            InModuleScope AzLocal.UpdateManagement {
                $p7 = ConvertFrom-AzLocalCronExpression -Expression '0 2 * * 7'
                $p0 = ConvertFrom-AzLocalCronExpression -Expression '0 2 * * 0'
                @($p7.FireTimes).Count | Should -Be 1
                $p7.FireTimes[0] | Should -Be $p0.FireTimes[0]
            }
        }

        It 'Accepts an empty string and returns IsValid=$false with structured error (v0.7.69)' {
            # Regression: v0.7.68 declared [Parameter(Mandatory)][string]$Expression,
            # so the binder rejected '' before the function body could surface the
            # 'Cron expression is empty.' message. v0.7.69 adds [AllowEmptyString()]
            # so the IsNullOrWhiteSpace handler actually runs.
            InModuleScope AzLocal.UpdateManagement {
                $p = ConvertFrom-AzLocalCronExpression -Expression ''
                $p.IsValid      | Should -BeFalse
                $p.ErrorMessage | Should -Be 'Cron expression is empty.'
            }
        }

        It 'Accepts a whitespace-only string and returns IsValid=$false with structured error (v0.7.69)' {
            InModuleScope AzLocal.UpdateManagement {
                $p = ConvertFrom-AzLocalCronExpression -Expression '   '
                $p.IsValid      | Should -BeFalse
                $p.ErrorMessage | Should -Be 'Cron expression is empty.'
            }
        }
    }

    Context 'Private helper: Read-AzLocalApplyUpdatesYamlCrons' {
        BeforeAll {
            $script:tmpYamlDir = Join-Path $env:TEMP "schedule-cov-tests-$(Get-Random)"
            New-Item -ItemType Directory -Path (Join-Path $script:tmpYamlDir 'github-actions') -Force | Out-Null
            New-Item -ItemType Directory -Path (Join-Path $script:tmpYamlDir 'azure-devops')   -Force | Out-Null
            @"
on:
  workflow_dispatch:
  schedule:
    - cron: '55 1 * * 6,0'
    - cron: "0 22 * * 5"
"@ | Set-Content -Path (Join-Path $script:tmpYamlDir 'github-actions\Step.7_apply-updates.yml') -Encoding ASCII
            @"
trigger: none
schedules:
  - cron: '30 2 * * 1-5'
    displayName: Weekday early-morning
    branches:
      include: [ main ]
"@ | Set-Content -Path (Join-Path $script:tmpYamlDir 'azure-devops\Step.7_apply-updates.yml') -Encoding ASCII
        }
        AfterAll {
            Remove-Item -Path $script:tmpYamlDir -Recurse -Force -ErrorAction SilentlyContinue
        }

        It 'Discovers 2 GH cron lines + 1 ADO cron line with platform inferred from folder name' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ tmpYamlDir = $script:tmpYamlDir } {
                param($tmpYamlDir)
                $r = Read-AzLocalApplyUpdatesYamlCrons -Path $tmpYamlDir
                @($r).Count | Should -Be 3
                @($r | Where-Object Platform -eq 'GitHubActions').Count | Should -Be 2
                @($r | Where-Object Platform -eq 'AzureDevOps').Count   | Should -Be 1
            }
        }

        It 'Strips surrounding quotes from cron expressions' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ tmpYamlDir = $script:tmpYamlDir } {
                param($tmpYamlDir)
                $r = Read-AzLocalApplyUpdatesYamlCrons -Path $tmpYamlDir
                ($r | ForEach-Object CronExpression) | Should -Contain '55 1 * * 6,0'
                ($r | ForEach-Object CronExpression) | Should -Contain '0 22 * * 5'
                ($r | ForEach-Object CronExpression) | Should -Contain '30 2 * * 1-5'
            }
        }

        It 'Does NOT match sibling Step.N pipelines (v0.7.69 glob regression)' {
            # v0.7.68 used `Get-ChildItem -LiteralPath -Recurse -Include`, which
            # silently ignored the -Include filter and returned every recursed
            # file. As a result the audit picked up Step.1, Step.3, Step.6, and
            # Step.7 schedule crons as if they were apply-updates crons. The
            # fix uses per-pattern -Filter calls (which honour -Recurse).
            $regressionDir = Join-Path $env:TEMP "schedule-cov-glob-$(Get-Random)"
            New-Item -ItemType Directory -Path (Join-Path $regressionDir 'github-actions') -Force | Out-Null
            try {
                # Sibling pipelines that carry their own (legitimate) schedule
                # crons - audit should ignore all of these.
                @"
on:
  schedule:
    - cron: '0 6 * * 1'
"@ | Set-Content -Path (Join-Path $regressionDir 'github-actions\Step.1_inventory-clusters.yml') -Encoding ASCII
                @"
on:
  schedule:
    - cron: '0 5 * * 1'
"@ | Set-Content -Path (Join-Path $regressionDir 'github-actions\Step.3_apply-updates-schedule-audit.yml') -Encoding ASCII
                @"
on:
  schedule:
    - cron: '0 7 * * *'
"@ | Set-Content -Path (Join-Path $regressionDir 'github-actions\Step.10_fleet-health-status.yml') -Encoding ASCII
                # Apply-updates file: ships with only commented-out cron examples,
                # so the reader should return ZERO crons for this folder overall.
                @"
on:
  workflow_dispatch:
  # schedule:
  #   - cron: '0 22 * * 6'
"@ | Set-Content -Path (Join-Path $regressionDir 'github-actions\Step.7_apply-updates.yml') -Encoding ASCII

                InModuleScope AzLocal.UpdateManagement -Parameters @{ dir = $regressionDir } {
                    param($dir)
                    $r = Read-AzLocalApplyUpdatesYamlCrons -Path $dir
                    @($r).Count | Should -Be 0
                }
            }
            finally {
                Remove-Item -Path $regressionDir -Recurse -Force -ErrorAction SilentlyContinue
            }
        }

        It 'Skips quoted whitespace-only cron captures (v0.7.69)' {
            # The regex `[^'"]+` also matches whitespace runs, so a malformed
            # `cron: '   '` would emit a record with CronExpression='' once
            # Trim() ran. v0.7.69 drops that record at the reader rather than
            # letting it crash the downstream parser binder.
            $emptyDir = Join-Path $env:TEMP "schedule-cov-emptycron-$(Get-Random)"
            New-Item -ItemType Directory -Path (Join-Path $emptyDir 'github-actions') -Force | Out-Null
            try {
                @"
on:
  schedule:
    - cron: '   '
    - cron: '0 22 * * 6'
"@ | Set-Content -Path (Join-Path $emptyDir 'github-actions\Step.7_apply-updates.yml') -Encoding ASCII

                InModuleScope AzLocal.UpdateManagement -Parameters @{ dir = $emptyDir } {
                    param($dir)
                    $r = Read-AzLocalApplyUpdatesYamlCrons -Path $dir
                    @($r).Count | Should -Be 1
                    $r[0].CronExpression | Should -Be '0 22 * * 6'
                }
            }
            finally {
                Remove-Item -Path $emptyDir -Recurse -Force -ErrorAction SilentlyContinue
            }
        }
    }

    Context 'Behavior: Audit / Matrix / Recommend' {
        BeforeAll {
            $script:tmpYamlDir2 = Join-Path $env:TEMP "schedule-cov-behaviour-$(Get-Random)"
            New-Item -ItemType Directory -Path (Join-Path $script:tmpYamlDir2 'github-actions') -Force | Out-Null
            # YAML covers Sat/Sun windows (fires Sat 01:50, Sun 01:50) but does NOT cover Mon-Fri windows.
            @"
on:
  schedule:
    - cron: '50 1 * * 6,0'
"@ | Set-Content -Path (Join-Path $script:tmpYamlDir2 'github-actions\Step.7_apply-updates.yml') -Encoding ASCII
        }
        AfterAll {
            Remove-Item -Path $script:tmpYamlDir2 -Recurse -Force -ErrorAction SilentlyContinue
        }

        It 'Audit: reports Covered for Sat-Sun window and Uncovered for Mon-Fri window' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ tmpYamlDir2 = $script:tmpYamlDir2 } {
                param($tmpYamlDir2)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Wave1';      UpdateStartWindow='Sat-Sun_02:00-06:00' },
                        [PSCustomObject]@{ ClusterName='c2'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c2'; UpdateRing='Wave1';      UpdateStartWindow='Sat-Sun_02:00-06:00' },
                        [PSCustomObject]@{ ClusterName='c3'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c3'; UpdateRing='Production'; UpdateStartWindow='Mon-Fri_22:00-04:00' }
                    )
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Audit -PipelineYamlPath $tmpYamlDir2 -PassThru 6>$null
                $rWave  = $result | Where-Object UpdateRing -eq 'Wave1'
                $rProd  = $result | Where-Object UpdateRing -eq 'Production'
                $rWave.Status | Should -Be 'Covered'
                $rWave.ClusterCount | Should -Be 2
                $rProd.Status | Should -Be 'Uncovered'
                $rProd.RequiredCronUTC | Should -Be '53 21 * * 1-5'
            }
        }

        It 'Matrix: emits one row per distinct (Ring, Window) with RequiredCronUTC populated' {
            InModuleScope AzLocal.UpdateManagement {
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Wave1'; UpdateStartWindow='Sat-Sun_02:00-06:00' }
                    )
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Matrix -PassThru 6>$null
                $result | Should -HaveCount 1
                $result[0].RequiredCronUTC | Should -Be '53 1 * * 6,0'
                $result[0].ClusterCount | Should -Be 1
            }
        }

        It 'Recommend: dedupes crons across rings and emits one row per cron' {
            InModuleScope AzLocal.UpdateManagement {
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Pilot'; UpdateStartWindow='Sat-Sun_02:00-06:00' },
                        [PSCustomObject]@{ ClusterName='c2'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c2'; UpdateRing='Wave1'; UpdateStartWindow='Sat-Sun_02:00-06:00' }
                    )
                }
                # Pin to FiresPerWindow=1 (pre-v0.7.92 behaviour) so the single-cron dedupe assertion still holds.
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -RecommendFiresPerWindow 1 -PassThru 6>$null
                $result | Should -HaveCount 1
                $result[0].CronExpression | Should -Be '53 1 * * 6,0'
                $result[0].ClusterCount   | Should -Be 2
                ($result[0].Rings | Sort-Object) | Should -Be @('Pilot','Wave1')
                $result[0].Snippet | Should -Match "schedule:"
            }
        }

        It 'Audit: MalformedTag emitted when UpdateStartWindow tag fails to parse' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ tmpYamlDir2 = $script:tmpYamlDir2 } {
                param($tmpYamlDir2)
                Mock Invoke-AzResourceGraphQuery {
                    @([PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='X'; UpdateStartWindow='NotAWindow' })
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Audit -PipelineYamlPath $tmpYamlDir2 -PassThru 6>$null
                ($result | Where-Object UpdateRing -eq 'X').Status | Should -Be 'MalformedTag'
            }
        }

        It '-IncludeUntagged surfaces clusters with no UpdateStartWindow tag' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ tmpYamlDir2 = $script:tmpYamlDir2 } {
                param($tmpYamlDir2)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Wave1'; UpdateStartWindow='Sat-Sun_02:00-06:00' },
                        [PSCustomObject]@{ ClusterName='c2'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c2'; UpdateRing='';      UpdateStartWindow='' }
                    )
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Audit -PipelineYamlPath $tmpYamlDir2 -IncludeUntagged -PassThru 6>$null
                ($result | Where-Object Status -eq 'NoWindowTag').ClusterCount | Should -Be 1
            }
        }

        It 'v0.8.2: -IncludeUntagged Recommendation lists cluster names grouped by UpdateRing (first 15)' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ tmpYamlDir2 = $script:tmpYamlDir2 } {
                param($tmpYamlDir2)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='cl-cnry-01'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/cl-cnry-01'; UpdateRing='Canary'; UpdateStartWindow='' },
                        [PSCustomObject]@{ ClusterName='cl-cnry-02'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/cl-cnry-02'; UpdateRing='Canary'; UpdateStartWindow='' },
                        [PSCustomObject]@{ ClusterName='cl-prd-01';  ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/cl-prd-01';  UpdateRing='Prod';   UpdateStartWindow='' },
                        [PSCustomObject]@{ ClusterName='cl-tst-99';  ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/cl-tst-99';  UpdateRing='';       UpdateStartWindow='' }
                    )
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Audit -PipelineYamlPath $tmpYamlDir2 -IncludeUntagged -PassThru 6>$null
                $row = $result | Where-Object Status -eq 'NoWindowTag'
                $row | Should -Not -BeNullOrEmpty
                $row.ClusterCount | Should -Be 4
                $row.Recommendation | Should -Match 'Grouped by UpdateRing'
                $row.Recommendation | Should -Match 'Canary -> cl-cnry-01, cl-cnry-02'
                $row.Recommendation | Should -Match 'Prod -> cl-prd-01'
                $row.Recommendation | Should -Match '\(none\) -> cl-tst-99'
                $row.Issue | Should -Match 'optional'
            }
        }

        It 'v0.8.2: NoWindowTag Recommendation caps the cluster list at 15 and appends "(showing first 15 of N)"' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ tmpYamlDir2 = $script:tmpYamlDir2 } {
                param($tmpYamlDir2)
                Mock Invoke-AzResourceGraphQuery {
                    1..20 | ForEach-Object {
                        [PSCustomObject]@{ ClusterName=("cl-{0:D2}" -f $_); ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId="/s/r/cl-$_"; UpdateRing='Prod'; UpdateStartWindow='' }
                    }
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Audit -PipelineYamlPath $tmpYamlDir2 -IncludeUntagged -PassThru 6>$null
                $row = $result | Where-Object Status -eq 'NoWindowTag'
                $row.ClusterCount | Should -Be 20
                $row.Recommendation | Should -Match 'showing first 15 of 20'
                # Only the first 15 cluster names should appear in the Recommendation
                $row.Recommendation | Should -Match 'cl-15'
                $row.Recommendation | Should -Not -Match 'cl-16'
            }
        }

        It 'v0.8.2: NoWindowTag sorts AFTER Covered rows (informational, not blocking)' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ tmpYamlDir2 = $script:tmpYamlDir2 } {
                param($tmpYamlDir2)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Wave1'; UpdateStartWindow='Sat-Sun_02:00-06:00' },
                        [PSCustomObject]@{ ClusterName='c2'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c2'; UpdateRing='Wave2'; UpdateStartWindow='Sat-Sun_02:00-06:00' },
                        [PSCustomObject]@{ ClusterName='c3'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c3'; UpdateRing='';      UpdateStartWindow='' }
                    )
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Audit -PipelineYamlPath $tmpYamlDir2 -IncludeUntagged -PassThru 6>$null
                $cronSection = @($result | Where-Object Section -eq 'Cron')
                $cronSection.Count | Should -BeGreaterThan 1
                # NoWindowTag must be the LAST row in the Cron section
                $cronSection[-1].Status | Should -Be 'NoWindowTag'
            }
        }
    }

    Context 'Belt-and-braces: -RecommendFiresPerWindow + RingMixedWindows (v0.7.92)' {
        BeforeAll {
            $script:beltYamlDir = Join-Path $env:TEMP "schedule-cov-belt-$(Get-Random)"
            New-Item -ItemType Directory -Path (Join-Path $script:beltYamlDir 'github-actions') -Force | Out-Null
            # Cover the Sat-Sun opening edge so Audit reports Covered for that ring.
            @"
on:
  schedule:
    - cron: '53 1 * * 6,0'
"@ | Set-Content -Path (Join-Path $script:beltYamlDir 'github-actions\Step.7_apply-updates.yml') -Encoding ASCII
        }
        AfterAll {
            Remove-Item -Path $script:beltYamlDir -Recurse -Force -ErrorAction SilentlyContinue
        }

        It 'Recommend default (-RecommendFiresPerWindow=2) emits TWO rows per window (open + retry)' {
            InModuleScope AzLocal.UpdateManagement {
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Pilot'; UpdateStartWindow='Sat-Sun_02:00-06:00' }
                    )
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -PassThru 6>$null
                @($result).Count | Should -Be 2
                $open  = $result | Where-Object CronExpression -eq '53 1 * * 6,0'
                $retry = $result | Where-Object CronExpression -eq '53 2 * * 6,0'
                $open  | Should -Not -BeNullOrEmpty
                $retry | Should -Not -BeNullOrEmpty
                $open.Snippet  | Should -Match '\(open\)'
                $retry.Snippet | Should -Match '\(retry\)'
            }
        }

        It 'Recommend with -RecommendFiresPerWindow 1 emits ONLY the opening cron (back-compat)' {
            InModuleScope AzLocal.UpdateManagement {
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Pilot'; UpdateStartWindow='Sat-Sun_02:00-06:00' }
                    )
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -RecommendFiresPerWindow 1 -PassThru 6>$null
                @($result).Count | Should -Be 1
                $result[0].CronExpression | Should -Be '53 1 * * 6,0'
            }
        }

        It 'Audit emits RingMixedWindows when same ring has two different UpdateStartWindow values' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ beltYamlDir = $script:beltYamlDir } {
                param($beltYamlDir)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Production'; UpdateStartWindow='Sat-Sun_02:00-06:00' },
                        [PSCustomObject]@{ ClusterName='c2'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c2'; UpdateRing='Production'; UpdateStartWindow='Mon-Fri_22:00-04:00' }
                    )
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Audit -PipelineYamlPath $beltYamlDir -PassThru 6>$null
                $mixed = @($result | Where-Object Status -eq 'RingMixedWindows')
                $mixed | Should -HaveCount 1
                $mixed[0].UpdateRing | Should -Be 'Production'
                $mixed[0].ClusterCount | Should -Be 2
                $mixed[0].UpdateStartWindow | Should -Match 'Mon-Fri_22:00-04:00'
                $mixed[0].UpdateStartWindow | Should -Match 'Sat-Sun_02:00-06:00'
                # Per-(Ring, Window) coverage rows are also emitted alongside the mixed warning.
                @($result | Where-Object { $_.UpdateRing -eq 'Production' -and $_.Status -in @('Covered','Uncovered','PartiallyCovered') }).Count | Should -Be 2
            }
        }

        It 'Audit does NOT emit RingMixedWindows when each ring has a single UpdateStartWindow' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ beltYamlDir = $script:beltYamlDir } {
                param($beltYamlDir)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Pilot';      UpdateStartWindow='Sat-Sun_02:00-06:00' },
                        [PSCustomObject]@{ ClusterName='c2'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c2'; UpdateRing='Production'; UpdateStartWindow='Mon-Fri_22:00-04:00' }
                    )
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Audit -PipelineYamlPath $beltYamlDir -PassThru 6>$null
                @($result | Where-Object Status -eq 'RingMixedWindows') | Should -HaveCount 0
            }
        }
    }

    Context 'Regression: multi-segment / multi-cron row-shape (Finding 1, v0.7.76)' {
        # These tests guard against the silent row-collapse bug where the public
        # cmdlet wrapped helper return values with @() while the helpers used
        # `return , $arr` to preserve Object[N] shape. Wrapping a `, $arr`
        # return with @() collapses it to Object[1] containing the inner array,
        # so multi-row scenarios silently produced one nested-array row instead
        # of N rows. See `docs/MODULE-REVIEW-AND-RECOMMENDATIONS.md` Finding 1.
        BeforeAll {
            $script:multiYamlDir = Join-Path $env:TEMP "schedule-cov-multicron-$(Get-Random)"
            New-Item -ItemType Directory -Path (Join-Path $script:multiYamlDir 'github-actions') -Force | Out-Null
            # Two cron triggers in one YAML: Sat-Sun 01:50 AND Mon-Fri 21:55.
            # Read-AzLocalApplyUpdatesYamlCrons returns Object[2] via `, $arr`;
            # a regressed caller wrapping with @() would receive Object[1] and
            # this test would fail.
            @"
on:
  schedule:
    - cron: '50 1 * * 6,0'
    - cron: '55 21 * * 1-5'
"@ | Set-Content -Path (Join-Path $script:multiYamlDir 'github-actions\Step.7_apply-updates.yml') -Encoding ASCII
        }
        AfterAll {
            Remove-Item -Path $script:multiYamlDir -Recurse -Force -ErrorAction SilentlyContinue
        }

        It 'Audit: multi-cron YAML produces Covered for both Sat-Sun AND Mon-Fri windows' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ multiYamlDir = $script:multiYamlDir } {
                param($multiYamlDir)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Wave1';      UpdateStartWindow='Sat-Sun_02:00-06:00' },
                        [PSCustomObject]@{ ClusterName='c2'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c2'; UpdateRing='Production'; UpdateStartWindow='Mon-Fri_22:00-04:00' }
                    )
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Audit -PipelineYamlPath $multiYamlDir -PassThru 6>$null
                # If the @() wrap regression returns - both rows would collapse
                # to a single nested-array row and one of these assertions would
                # fail with `Status` being a System.Object[] of array values.
                ($result | Where-Object UpdateRing -eq 'Wave1').Status      | Should -Be 'Covered'
                ($result | Where-Object UpdateRing -eq 'Production').Status | Should -Be 'Covered'
            }
        }

        It 'Audit: multi-segment UpdateStartWindow (Mon-Fri_22:00-04:00;Sat-Sun_02:00-10:00) reports both segments parsed' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ multiYamlDir = $script:multiYamlDir } {
                param($multiYamlDir)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='HybridRing'; UpdateStartWindow='Mon-Fri_22:00-04:00;Sat-Sun_02:00-10:00' }
                    )
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Audit -PipelineYamlPath $multiYamlDir -PassThru 6>$null
                # The HybridRing row contains TWO required crons (one per segment).
                # Convert-AzLocalUpdateWindowToCron returns Object[2] via `, $arr`;
                # a regressed caller wrapping with @() would produce Object[1]
                # containing the nested array, and downstream coverage matching
                # would compare a single nested-array string against YAML crons
                # and always report Uncovered (silent false negative).
                #
                # Audit view ROLLS multi-segment windows into a single row per
                # (UpdateRing, UpdateStartWindow) with all required crons reflected
                # in RequiredCronUTC (semicolon-separated). This test asserts
                # both segments are PARSED (visible in RequiredCronUTC) and
                # both contribute to the rolled-up Status.
                $hybrid = @($result | Where-Object UpdateRing -eq 'HybridRing')
                $hybrid | Should -Not -BeNullOrEmpty
                $hybrid.Count | Should -Be 1 -Because 'multi-segment windows roll into one Audit row per (UpdateRing, UpdateStartWindow)'
                # RequiredCronUTC must reflect BOTH segments. If the @() wrap
                # regression returns the second cron will be missing or the
                # field will surface as a System.Object[] of array values
                # (semicolon join would then produce 'System.Object[]; System.Object[]').
                $hybrid[0].RequiredCronUTC | Should -Match ';' -Because 'two required crons must be semicolon-joined'
                $hybrid[0].RequiredCronUTC | Should -Not -Match 'System.Object' -Because 'a regressed caller wrap with @() collapses Object[2] into Object[1] of nested arrays'
                # Both segments covered by the two-cron YAML.
                $hybrid[0].Status | Should -Be 'Covered'
            }
        }

        It 'Recommend: multi-segment UpdateStartWindow emits one row per cron with stable dedupe key' {
            InModuleScope AzLocal.UpdateManagement {
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='HybridRing'; UpdateStartWindow='Mon-Fri_22:00-04:00;Sat-Sun_02:00-10:00' }
                    )
                }
                # Pin to FiresPerWindow=1 (pre-v0.7.92 behaviour) so the per-segment row count is unambiguous (2 instead of 4 with belt-and-braces).
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -RecommendFiresPerWindow 1 -PassThru 6>$null
                # If RequiredCrons collapsed to one nested-array row, Recommend
                # would emit a single CronExpression equal to a `System.Object[]`
                # string and the count would be 1. With the fix it should be 2.
                @($result).Count | Should -Be 2
                # Each emitted row should have a real cron string, not a
                # stringified array.
                foreach ($r in $result) {
                    $r.CronExpression | Should -Match '^\d+\s+\d+\s+\*\s+\*\s+'
                    $r.ClusterCount | Should -Be 1
                }
            }
        }
    }

    Context 'v0.8.3 - Recommend diff-prunes crons already present in -PipelineYamlPath' {
        # Pre-v0.8.3 Recommend built its snippet purely from cluster tags via
        # Convert-AzLocalUpdateWindowToCron, so on a steady-state fleet where
        # Step.6 already contained the recommended crons, the advisor re-emitted
        # the same cron lines under an "Action required - cron coverage" header.
        # Operators read it as "Step.3 is telling me to add these again" and
        # pasted duplicates. v0.8.3 hoists the yaml-read out of the Audit-only
        # guard so Recommend can also read existing crons, and prunes any
        # recommended cron whose expression matches one already present.

        BeforeAll {
            $script:pruneYamlDir = Join-Path $env:TEMP "schedule-cov-prune-$(Get-Random)"
            New-Item -ItemType Directory -Path (Join-Path $script:pruneYamlDir 'github-actions') -Force | Out-Null
            # Pre-existing Step.6 already covers the Sat-Sun_02:00-06:00 opening
            # edge (cron '53 1 * * 6,0' = 7 min before 02:00 UTC on Sat+Sun).
            # With FiresPerWindow=1, Recommend would propose ONLY '53 1 * * 6,0';
            # diff-prune should drop it -> zero recommended rows.
            @"
on:
  schedule:
    - cron: '53 1 * * 6,0'
"@ | Set-Content -Path (Join-Path $script:pruneYamlDir 'github-actions\Step.7_apply-updates.yml') -Encoding ASCII
        }
        AfterAll {
            Remove-Item -Path $script:pruneYamlDir -Recurse -Force -ErrorAction SilentlyContinue
        }

        It 'Recommend WITH -PipelineYamlPath prunes the recommended cron when it is already present (FiresPerWindow=1)' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ pruneYamlDir = $script:pruneYamlDir } {
                param($pruneYamlDir)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Pilot'; UpdateStartWindow='Sat-Sun_02:00-06:00' }
                    )
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -RecommendFiresPerWindow 1 -PipelineYamlPath $pruneYamlDir -PassThru 6>$null
                @($result).Count | Should -Be 0 -Because 'the only recommended cron (53 1 * * 6,0) is already present in the supplied Step.6 yml'
            }
        }

        It 'Recommend WITHOUT -PipelineYamlPath emits the full (un-pruned) set (back-compat)' {
            InModuleScope AzLocal.UpdateManagement {
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Pilot'; UpdateStartWindow='Sat-Sun_02:00-06:00' }
                    )
                }
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -RecommendFiresPerWindow 1 -PassThru 6>$null
                @($result).Count | Should -Be 1
                $result[0].CronExpression | Should -Be '53 1 * * 6,0'
            }
        }

        It 'Recommend WITH -PipelineYamlPath emits only the missing cron when only ONE of two recommended crons is already present (FiresPerWindow=2)' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ pruneYamlDir = $script:pruneYamlDir } {
                param($pruneYamlDir)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Pilot'; UpdateStartWindow='Sat-Sun_02:00-06:00' }
                    )
                }
                # FiresPerWindow=2 emits opening (53 1 * * 6,0) + retry (53 2 * * 6,0).
                # The pre-existing yml only has the opening, so retry remains.
                $result = Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -RecommendFiresPerWindow 2 -PipelineYamlPath $pruneYamlDir -PassThru 6>$null
                @($result).Count | Should -Be 1 -Because 'opening cron already present, retry remains'
                $result[0].CronExpression | Should -Be '53 2 * * 6,0'
                $result[0].Snippet        | Should -Match '\(retry\)'
            }
        }
    }

    Context 'v0.8.4 - Enhancement A: NoWindowTag CSV remediation (-ClusterCsvPath)' {
        # When -ClusterCsvPath is supplied, the Recommend view emits a new
        # "## Action required - NoWindowTag remediation" section: for each
        # cluster with an UpdateRing tag but no UpdateStartWindow tag, the
        # advisor proposes a peer-derived UpdateStartWindow (mode of peers
        # in the same ring) and looks up the cluster in the CSV by
        # ResourceId (case-insensitive), falling back to ClusterName+RG.

        BeforeAll {
            $script:nwtDir = Join-Path $env:TEMP "schedule-cov-nwt-$(Get-Random)"
            New-Item -ItemType Directory -Path (Join-Path $script:nwtDir 'github-actions') -Force | Out-Null
            # Minimal Step.6 yml so -PipelineYamlPath validates and Recommend
            # has something to diff against (we are not testing the cron
            # section here - the focus is the NoWindowTag remediation block).
            @"
on:
  workflow_dispatch:
"@ | Set-Content -Path (Join-Path $script:nwtDir 'github-actions\Step.7_apply-updates.yml') -Encoding ASCII

            # CSV WITH ResourceId column: 4 clusters. One peer (cA) in Ring1
            # with a real UpdateStartWindow; one orphan target (cB) in Ring1
            # with blank UpdateStartWindow; one peer (cC) in Ring2; and one
            # cluster (cD) in CSV that is NOT in ARG (irrelevant - should not
            # appear in remediation table).
            $script:nwtCsvWithRid = Join-Path $script:nwtDir 'with-rid.csv'
            @'
ClusterName,ResourceGroup,SubscriptionId,UpdateRing,UpdateStartWindow,UpdateExclusionsWindow,ResourceId
cA,rg1,s1,Ring1,Mon-Fri_22:00-06:00,,/subscriptions/s1/resourceGroups/rg1/providers/Microsoft.AzureStackHCI/clusters/cA
cB,rg1,s1,Ring1,,,/subscriptions/s1/resourceGroups/rg1/providers/Microsoft.AzureStackHCI/clusters/cB
cC,rg2,s2,Ring2,Sat-Sun_08:00-20:00,,/subscriptions/s2/resourceGroups/rg2/providers/Microsoft.AzureStackHCI/clusters/cC
cD,rg9,s9,Ring9,,,/subscriptions/s9/resourceGroups/rg9/providers/Microsoft.AzureStackHCI/clusters/cD
'@ | Set-Content -Path $script:nwtCsvWithRid -Encoding ASCII

            # CSV WITHOUT ResourceId column: forces ClusterName+ResourceGroup
            # fallback path.
            $script:nwtCsvNoRid = Join-Path $script:nwtDir 'no-rid.csv'
            @'
ClusterName,ResourceGroup,SubscriptionId,UpdateRing,UpdateStartWindow
cA,rg1,s1,Ring1,Mon-Fri_22:00-06:00
cB,rg1,s1,Ring1,
'@ | Set-Content -Path $script:nwtCsvNoRid -Encoding ASCII
        }
        AfterAll {
            Remove-Item -Path $script:nwtDir -Recurse -Force -ErrorAction SilentlyContinue
        }

        It 'Recommend emits NoWindowTag remediation section with peer-derived value when -ClusterCsvPath supplied (ResourceId match)' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ nwtDir = $script:nwtDir; csv = $script:nwtCsvWithRid } {
                param($nwtDir, $csv)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        # peer cA - tagged
                        [PSCustomObject]@{ ClusterName='cA'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/subscriptions/s1/resourceGroups/rg1/providers/Microsoft.AzureStackHCI/clusters/cA'; UpdateRing='Ring1'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow='' }
                        # NoWindowTag target cB - same ring as cA, no window
                        [PSCustomObject]@{ ClusterName='cB'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/subscriptions/s1/resourceGroups/rg1/providers/Microsoft.AzureStackHCI/clusters/cB'; UpdateRing='Ring1'; UpdateStartWindow=''; UpdateExclusionsWindow='' }
                    )
                }
                $out = Join-Path $nwtDir 'reco.md'
                Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -PipelineYamlPath (Join-Path $nwtDir 'github-actions') -ClusterCsvPath $csv -ExportPath $out 6>$null | Out-Null
                $md = Get-Content -Path $out -Raw
                $md | Should -Match 'NoWindowTag remediation'
                $md | Should -Match '`Mon-Fri_22:00-06:00`'
                $md | Should -Match 'matched by \*\*ResourceId\*\*'
                $md | Should -Match 'Only peer in \\`Ring1\\` \(\\`cA\\`\)'
                $md | Should -Match '<details open><summary>Clusters missing UpdateRing and/or UpdateStartWindow tags \(1 cluster\(s\)\)</summary>'
                $md | Should -Match '(?s)<details open>.*\| Cluster \| ResourceGroup \| UpdateRing \|.*</details>'
            }
        }

        It 'Recommend falls back to ClusterName+ResourceGroup matching when CSV has no ResourceId column' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ nwtDir = $script:nwtDir; csv = $script:nwtCsvNoRid } {
                param($nwtDir, $csv)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='cA'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/subscriptions/s1/resourceGroups/rg1/providers/Microsoft.AzureStackHCI/clusters/cA'; UpdateRing='Ring1'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow='' }
                        [PSCustomObject]@{ ClusterName='cB'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/subscriptions/s1/resourceGroups/rg1/providers/Microsoft.AzureStackHCI/clusters/cB'; UpdateRing='Ring1'; UpdateStartWindow=''; UpdateExclusionsWindow='' }
                    )
                }
                $out = Join-Path $nwtDir 'reco-norid.md'
                Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -PipelineYamlPath (Join-Path $nwtDir 'github-actions') -ClusterCsvPath $csv -ExportPath $out 6>$null | Out-Null
                $md = Get-Content -Path $out -Raw
                $md | Should -Match 'matched by \*\*ClusterName\+ResourceGroup\*\*'
                $md | Should -Match 'onsider re-running the cluster inventory pipeline'
            }
        }

        It 'Recommend emits "Not in CSV" + re-run Step.1 messaging when cluster is absent from CSV' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ nwtDir = $script:nwtDir; csv = $script:nwtCsvWithRid } {
                param($nwtDir, $csv)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        # cA is in CSV (peer); cZ is NOT in CSV at all
                        [PSCustomObject]@{ ClusterName='cA'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/subscriptions/s1/resourceGroups/rg1/providers/Microsoft.AzureStackHCI/clusters/cA'; UpdateRing='Ring1'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow='' }
                        [PSCustomObject]@{ ClusterName='cZ'; ResourceGroup='rg5'; SubscriptionId='s5'; ClusterResourceId='/subscriptions/s5/resourceGroups/rg5/providers/Microsoft.AzureStackHCI/clusters/cZ'; UpdateRing='Ring1'; UpdateStartWindow=''; UpdateExclusionsWindow='' }
                    )
                }
                $out = Join-Path $nwtDir 'reco-notin.md'
                Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -PipelineYamlPath (Join-Path $nwtDir 'github-actions') -ClusterCsvPath $csv -ExportPath $out 6>$null | Out-Null
                $md = Get-Content -Path $out -Raw
                $md | Should -Match '\*\*Not in CSV\.\*\*'
                $md | Should -Match 'Re-run the cluster inventory pipeline'
                $md | Should -Match 'replace \\`[^`]+\\` in source control with the artifact'
            }
        }

        It 'Recommend reports majority-mode peer-derivation source when peers disagree' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ nwtDir = $script:nwtDir; csv = $script:nwtCsvWithRid } {
                param($nwtDir, $csv)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='p1'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/subscriptions/s1/resourceGroups/rg1/providers/Microsoft.AzureStackHCI/clusters/p1'; UpdateRing='Ring1'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow='' }
                        [PSCustomObject]@{ ClusterName='p2'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/subscriptions/s1/resourceGroups/rg1/providers/Microsoft.AzureStackHCI/clusters/p2'; UpdateRing='Ring1'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow='' }
                        [PSCustomObject]@{ ClusterName='p3'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/subscriptions/s1/resourceGroups/rg1/providers/Microsoft.AzureStackHCI/clusters/p3'; UpdateRing='Ring1'; UpdateStartWindow='Sat-Sun_08:00-20:00'; UpdateExclusionsWindow='' }
                        [PSCustomObject]@{ ClusterName='target'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/subscriptions/s1/resourceGroups/rg1/providers/Microsoft.AzureStackHCI/clusters/target'; UpdateRing='Ring1'; UpdateStartWindow=''; UpdateExclusionsWindow='' }
                    )
                }
                $out = Join-Path $nwtDir 'reco-mixed.md'
                Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -PipelineYamlPath (Join-Path $nwtDir 'github-actions') -ClusterCsvPath $csv -ExportPath $out 6>$null | Out-Null
                $md = Get-Content -Path $out -Raw
                $md | Should -Match '2 of 3 peer\(s\) in \\`Ring1\\` use \\`Mon-Fri_22:00-06:00\\`'
                $md | Should -Match 'Alternatives: \\`Sat-Sun_08:00-20:00\\` \(1\)'
            }
        }

        It 'Recommend does NOT emit NoWindowTag remediation section when -ClusterCsvPath is omitted' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ nwtDir = $script:nwtDir } {
                param($nwtDir)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='cA'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/subscriptions/s1/resourceGroups/rg1/providers/Microsoft.AzureStackHCI/clusters/cA'; UpdateRing='Ring1'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow='' }
                        [PSCustomObject]@{ ClusterName='cB'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/subscriptions/s1/resourceGroups/rg1/providers/Microsoft.AzureStackHCI/clusters/cB'; UpdateRing='Ring1'; UpdateStartWindow=''; UpdateExclusionsWindow='' }
                    )
                }
                $out = Join-Path $nwtDir 'reco-nocsv.md'
                Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -PipelineYamlPath (Join-Path $nwtDir 'github-actions') -ExportPath $out 6>$null | Out-Null
                $md = Get-Content -Path $out -Raw -ErrorAction SilentlyContinue
                if ($md) { $md | Should -Not -Match 'NoWindowTag remediation' }
            }
        }
    }

    Context 'v0.8.4 - Enhancement B: Cycle calendar (auto-renders when -SchedulePath supplied)' {

        BeforeAll {
            $script:calDir = Join-Path $env:TEMP "schedule-cov-cal-$(Get-Random)"
            New-Item -ItemType Directory -Path (Join-Path $script:calDir 'github-actions') -Force | Out-Null
            @"
on:
  workflow_dispatch:
"@ | Set-Content -Path (Join-Path $script:calDir 'github-actions\Step.7_apply-updates.yml') -Encoding ASCII

            # Minimal schema-v2 schedule: 2-week cycle, Ring1 in week 1
            # (Mon-Fri), Ring2 in week 2 (Mon-Fri). No allowedUpdateVersions.
            $script:calSchedule = Join-Path $script:calDir 'apply-updates-schedule.yml'
            @"
schemaVersion: 2
cycleWeeks: 2
cycleAnchorISOWeek: 1
cycleAnchorYear: 2024
allowedUpdateVersions: 'Latest'
schedule:
  - weeksInCycle: '1'
    daysOfWeek:   'Mon-Fri'
    rings:        'Ring1'
    notes:        'week-1 ring1'
  - weeksInCycle: '2'
    daysOfWeek:   'Mon-Fri'
    rings:        'Ring2'
    notes:        'week-2 ring2'
"@ | Set-Content -Path $script:calSchedule -Encoding ASCII
        }
        AfterAll {
            Remove-Item -Path $script:calDir -Recurse -Force -ErrorAction SilentlyContinue
        }

        It 'Recommend emits Cycle calendar section when -SchedulePath is supplied' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ calDir = $script:calDir; schedule = $script:calSchedule } {
                param($calDir, $schedule)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/s/r/c1'; UpdateRing='Ring1'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow='' }
                        [PSCustomObject]@{ ClusterName='c2'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/s/r/c2'; UpdateRing='Ring2'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow='' }
                    )
                }
                $out = Join-Path $calDir 'reco-cal.md'
                Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -PipelineYamlPath (Join-Path $calDir 'github-actions') -SchedulePath $schedule -ExportPath $out 6>$null | Out-Null
                $md = Get-Content -Path $out -Raw
                $md | Should -Match 'Cycle calendar - next 14 day\(s\) \(cycle length: 2 week\(s\)\)'
                $md | Should -Match '\| Date \(UTC\) \| Day \| CycleWeek \| Eligible rings(?: \(cluster count\))? \| AllowedUpdateVersions \|'
                # Should have 14 data rows
                $rowCount = ([regex]::Matches($md, '(?m)^\|\s*\d{4}-\d{2}-\d{2}\s*\|')).Count
                $rowCount | Should -Be 14
                # At least one row should reference Ring1 and one Ring2
                $md | Should -Match '`Ring1`'
                $md | Should -Match '`Ring2`'
                # Cycle-wrap marker only appears when the 14-day projection
                # crosses the cycle boundary. With cycleWeeks=2 and a 14-day
                # window starting on day-1 of the cycle the window ends exactly
                # at the boundary - no wrap row is emitted. Compute today's
                # day-in-cycle from the anchor and only assert when wrap is
                # expected.
                $anchor = [datetime]'2024-01-01'   # ISO week 1, 2024 (Monday)
                $todayUtc = [datetime]::UtcNow.Date
                $daysSinceAnchor = ($todayUtc - $anchor).Days
                $dayInCycle = $daysSinceAnchor % 14
                if ($dayInCycle -ne 0) {
                    $md | Should -Match '_\(cycle wraps\)_'
                }
            }
        }

        It 'Recommend does NOT emit Cycle calendar when -SchedulePath is omitted' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ calDir = $script:calDir } {
                param($calDir)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/s/r/c1'; UpdateRing='Ring1'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow='' }
                    )
                }
                $out = Join-Path $calDir 'reco-nocal.md'
                Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -PipelineYamlPath (Join-Path $calDir 'github-actions') -ExportPath $out 6>$null | Out-Null
                $md = Get-Content -Path $out -Raw -ErrorAction SilentlyContinue
                if ($md) { $md | Should -Not -Match 'Cycle calendar' }
            }
        }
    }

    Context 'v0.8.4 - Enhancement C: Configured exclusion windows summary' {

        BeforeAll {
            $script:exclDir = Join-Path $env:TEMP "schedule-cov-excl-$(Get-Random)"
            New-Item -ItemType Directory -Path (Join-Path $script:exclDir 'github-actions') -Force | Out-Null
            @"
on:
  workflow_dispatch:
"@ | Set-Content -Path (Join-Path $script:exclDir 'github-actions\Step.7_apply-updates.yml') -Encoding ASCII
        }
        AfterAll {
            Remove-Item -Path $script:exclDir -Recurse -Force -ErrorAction SilentlyContinue
        }

        It 'Recommend emits Configured exclusion windows section when at least one cluster has the tag' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ exclDir = $script:exclDir } {
                param($exclDir)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/s/r/c1'; UpdateRing='Prod'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow='2025-12-10/2026-01-06' }
                        [PSCustomObject]@{ ClusterName='c2'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/s/r/c2'; UpdateRing='Prod'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow='2025-12-10/2026-01-06' }
                        [PSCustomObject]@{ ClusterName='c3'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/s/r/c3'; UpdateRing='Prod'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow='' }
                    )
                }
                $out = Join-Path $exclDir 'reco-excl.md'
                Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -PipelineYamlPath (Join-Path $exclDir 'github-actions') -ExportPath $out 6>$null | Out-Null
                $md = Get-Content -Path $out -Raw
                $md | Should -Match 'Configured exclusion windows \(UpdateExclusionsWindow tag\)'
                $md | Should -Match '`2025-12-10/2026-01-06`'
                $md | Should -Match 'Clusters with NO `UpdateExclusionsWindow` tag'
                $md | Should -Match '\*\*Prod\*\* - 1 cluster\(s\)'
            }
        }

        It 'Keeps ARG tag and cluster values containing Markdown delimiters inside one exclusion-table row' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ exclDir = $script:exclDir } {
                param($exclDir)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{
                            ClusterName='cluster|`one`'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/s/r/c1'
                            UpdateRing='Prod|`Canary`'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow="2025-12-10|freeze`n2026-01-06"
                        }
                    )
                }
                $out = Join-Path $exclDir 'reco-excl-poison.md'
                Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -PipelineYamlPath (Join-Path $exclDir 'github-actions') -ExportPath $out 6>$null | Out-Null
                $md = Get-Content -Path $out -Raw
                $dataRow = @($md -split "`r?`n" | Where-Object { $_ -match '^\| Prod' })

                $dataRow | Should -HaveCount 1
                $dataRow[0] | Should -Match 'Prod\\\|\\`Canary\\`'
                $dataRow[0] | Should -Match '2025-12-10\\\|freeze<br>2026-01-06'
                $dataRow[0] | Should -Match 'cluster\\\|\\`one\\`'
            }
        }

        It 'Recommend does NOT emit Configured exclusion windows when no cluster has the tag' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ exclDir = $script:exclDir } {
                param($exclDir)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='rg1'; SubscriptionId='s1'; ClusterResourceId='/s/r/c1'; UpdateRing='Prod'; UpdateStartWindow='Mon-Fri_22:00-06:00'; UpdateExclusionsWindow='' }
                    )
                }
                $out = Join-Path $exclDir 'reco-noexcl.md'
                Test-AzLocalApplyUpdatesScheduleCoverage -View Recommend -PipelineYamlPath (Join-Path $exclDir 'github-actions') -ExportPath $out 6>$null | Out-Null
                $md = Get-Content -Path $out -Raw -ErrorAction SilentlyContinue
                if ($md) { $md | Should -Not -Match 'Configured exclusion windows' }
            }
        }
    }

    Context 'Integration: shipped Automation-Pipeline-Examples bundle (v0.7.69)' {
        # End-to-end smoke against the actual YAMLs published to PSGallery as
        # part of the module. This is the gap that let v0.7.68 ship with the
        # -LiteralPath/-Include glob regression: unit tests only fed the reader
        # synthetic Step.7_apply-updates.yml files in isolation, never a real
        # multi-pipeline folder. Running the audit against the bundle now
        # guarantees that no future change re-introduces a glob that also picks
        # up sibling Step.N_*.yml schedule triggers.
        BeforeAll {
            $script:bundleGhDir = Join-Path $PSScriptRoot '..\Automation-Pipeline-Examples\github-actions'
        }

        It 'Audit against the shipped GitHub Actions bundle returns rows without throwing' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ bundleGhDir = $script:bundleGhDir } {
                param($bundleGhDir)
                Mock Invoke-AzResourceGraphQuery {
                    @(
                        [PSCustomObject]@{ ClusterName='c1'; ResourceGroup='r'; SubscriptionId='s'; ClusterResourceId='/s/r/c1'; UpdateRing='Wave1'; UpdateStartWindow='Sat-Sun_02:00-06:00' }
                    )
                }
                { Test-AzLocalApplyUpdatesScheduleCoverage -View Audit -PipelineYamlPath $bundleGhDir -PassThru 6>$null } |
                    Should -Not -Throw
            }
        }

        It 'Reader finds zero crons in the shipped bundle (no false-positive sibling matches)' {
            InModuleScope AzLocal.UpdateManagement -Parameters @{ bundleGhDir = $script:bundleGhDir } {
                param($bundleGhDir)
                $r = Read-AzLocalApplyUpdatesYamlCrons -Path $bundleGhDir
                @($r).Count | Should -Be 0 -Because 'the shipped Step.7_apply-updates.yml ships with only commented cron examples, and the reader must NOT pick up crons from sibling Step.N pipelines'
            }
        }
    }
}

