#region v0.7.68 Update-AzLocalPipelineExample + marker parser

Describe 'Helper Function: Get-AzLocalPipelineCustomiseMarkers (Internal)' {

    It 'Returns an empty hashtable on empty input' {
        InModuleScope AzLocal.UpdateManagement {
            $r = Get-AzLocalPipelineCustomiseMarkers -Text ''
            $r | Should -BeOfType [hashtable]
            $r.Count | Should -Be 0
        }
    }

    It 'Returns an empty hashtable when no markers are present' {
        InModuleScope AzLocal.UpdateManagement {
            $r = Get-AzLocalPipelineCustomiseMarkers -Text @"
name: My Workflow
on:
  push:
    branches: [main]
"@
            $r.Count | Should -Be 0
        }
    }

    It 'Parses a single marker block with multi-line body' {
        InModuleScope AzLocal.UpdateManagement {
            $text = @"
on:
  # BEGIN-AZLOCAL-CUSTOMIZE:schedule-triggers
  schedule:
    - cron: '0 22 * * 6'
  # END-AZLOCAL-CUSTOMIZE:schedule-triggers
  workflow_dispatch:
"@
            $r = Get-AzLocalPipelineCustomiseMarkers -Text $text
            $r.Count | Should -Be 1
            $r.ContainsKey('schedule-triggers') | Should -BeTrue
            $r['schedule-triggers'].BeginLine | Should -Match 'BEGIN-AZLOCAL-CUSTOMIZE:schedule-triggers'
            $r['schedule-triggers'].EndLine   | Should -Match 'END-AZLOCAL-CUSTOMIZE:schedule-triggers'
            $r['schedule-triggers'].Body      | Should -Match "cron: '0 22 \* \* 6'"
        }
    }

    It 'Parses multiple distinct markers in the same file' {
        InModuleScope AzLocal.UpdateManagement {
            $text = @"
on:
  # BEGIN-AZLOCAL-CUSTOMIZE:schedule-triggers
  schedule: []
  # END-AZLOCAL-CUSTOMIZE:schedule-triggers
env:
  # BEGIN-AZLOCAL-CUSTOMIZE:itsm-secrets
  TOKEN: `${{ secrets.MY_TOKEN }}
  # END-AZLOCAL-CUSTOMIZE:itsm-secrets
"@
            $r = Get-AzLocalPipelineCustomiseMarkers -Text $text
            $r.Count | Should -Be 2
            $r.ContainsKey('schedule-triggers') | Should -BeTrue
            $r.ContainsKey('itsm-secrets')      | Should -BeTrue
        }
    }

    It 'Reconstructing BeginLine + Body + EndLine reproduces the original span exactly' {
        InModuleScope AzLocal.UpdateManagement {
            $text = "preamble`n  # BEGIN-AZLOCAL-CUSTOMIZE:demo`nline1`nline2`n  # END-AZLOCAL-CUSTOMIZE:demo`ntail"
            $r = Get-AzLocalPipelineCustomiseMarkers -Text $text
            $r.Count | Should -Be 1
            $b = $r['demo']
            $reassembled = $b.BeginLine + $b.Body + $b.EndLine
            $text.Substring($b.Index, $b.Length) | Should -BeExactly $reassembled
        }
    }

    It 'Skips duplicate marker names and keeps the first occurrence' {
        InModuleScope AzLocal.UpdateManagement {
            $text = @"
# BEGIN-AZLOCAL-CUSTOMIZE:dup
first
# END-AZLOCAL-CUSTOMIZE:dup
# BEGIN-AZLOCAL-CUSTOMIZE:dup
second
# END-AZLOCAL-CUSTOMIZE:dup
"@
            $r = Get-AzLocalPipelineCustomiseMarkers -Text $text 3>$null
            $r.Count | Should -Be 1
            $r['dup'].Body | Should -Match 'first'
        }
    }
}

Describe 'Helper Function: Get-AzLocalUpdaterScriptVersion (Internal)' {

    It 'Returns $null on empty input' {
        InModuleScope AzLocal.UpdateManagement {
            Get-AzLocalUpdaterScriptVersion -Text '' | Should -BeNullOrEmpty
        }
    }

    It 'Returns $null when no marker is present' {
        InModuleScope AzLocal.UpdateManagement {
            Get-AzLocalUpdaterScriptVersion -Text "#Requires -Version 5.1`n# just a comment" | Should -BeNullOrEmpty
        }
    }

    It 'Parses a standard marker into a [version]' {
        InModuleScope AzLocal.UpdateManagement {
            $v = Get-AzLocalUpdaterScriptVersion -Text "#Requires -Version 5.1`n# AZLOCAL-UPDATER-VERSION: 1.2.3`n<#"
            $v | Should -BeOfType [version]
            $v | Should -Be ([version]'1.2.3')
        }
    }

    It 'Is case-insensitive on the token and tolerates extra hashes / whitespace' {
        InModuleScope AzLocal.UpdateManagement {
            $v = Get-AzLocalUpdaterScriptVersion -Text "  ## azlocal-updater-version :  2.0.0  "
            $v | Should -Be ([version]'2.0.0')
        }
    }

    It 'Returns the FIRST marker when several are present' {
        InModuleScope AzLocal.UpdateManagement {
            $v = Get-AzLocalUpdaterScriptVersion -Text "# AZLOCAL-UPDATER-VERSION: 1.0.0`n# AZLOCAL-UPDATER-VERSION: 9.9.9"
            $v | Should -Be ([version]'1.0.0')
        }
    }

    It 'Returns $null for a non-version-shaped value' {
        InModuleScope AzLocal.UpdateManagement {
            Get-AzLocalUpdaterScriptVersion -Text '# AZLOCAL-UPDATER-VERSION: not-a-version' | Should -BeNullOrEmpty
        }
    }

    It 'Reads the marker from the bundled update-module-and-pipelines.ps1 template' {
        $templatePath = Join-Path -Path $PSScriptRoot -ChildPath '..\Automation-Pipeline-Examples\update-module-and-pipelines.ps1'
        Test-Path -LiteralPath $templatePath | Should -BeTrue
        $text = Get-Content -LiteralPath $templatePath -Raw
        InModuleScope AzLocal.UpdateManagement -Parameters @{ Text = $text } {
            param($Text)
            Get-AzLocalUpdaterScriptVersion -Text $Text | Should -Not -BeNullOrEmpty
        }
    }
}

