Describe 'Helper Function: Test-AzLocalReadmeReplaceable (Internal)' {

    It 'Treats a missing / empty README as replaceable' {
        InModuleScope AzLocal.UpdateManagement {
            Test-AzLocalReadmeReplaceable -Text '' -RepoName 'my-repo' | Should -BeTrue
        }
    }

    It 'Treats a whitespace-only README as replaceable' {
        InModuleScope AzLocal.UpdateManagement {
            Test-AzLocalReadmeReplaceable -Text "   `r`n   `r`n" -RepoName 'my-repo' | Should -BeTrue
        }
    }

    It 'Treats a GitHub default stub (H1 = repo name) as replaceable' {
        InModuleScope AzLocal.UpdateManagement {
            Test-AzLocalReadmeReplaceable -Text '# my-repo' -RepoName 'my-repo' | Should -BeTrue
        }
    }

    It 'Treats a GitHub default stub with a one-line description as replaceable' {
        InModuleScope AzLocal.UpdateManagement {
            Test-AzLocalReadmeReplaceable -Text "# My Repo`r`n`r`nA short description of the project." -RepoName 'my-repo' | Should -BeTrue
        }
    }

    It 'Normalises punctuation / case when matching the repo name' {
        InModuleScope AzLocal.UpdateManagement {
            Test-AzLocalReadmeReplaceable -Text '# My Repo' -RepoName 'My-Repo' | Should -BeTrue
        }
    }

    It 'Preserves a stub whose H1 does not match the repo name' {
        InModuleScope AzLocal.UpdateManagement {
            Test-AzLocalReadmeReplaceable -Text '# Something Completely Different' -RepoName 'my-repo' | Should -BeFalse
        }
    }

    It 'Preserves a README with real operator content (heading + list)' {
        InModuleScope AzLocal.UpdateManagement {
            Test-AzLocalReadmeReplaceable -Text "# my-repo`r`n`r`n## Setup`r`n- step one" -RepoName 'my-repo' | Should -BeFalse
        }
    }

    It 'Preserves a stub-shaped README when no repo name is supplied (conservative)' {
        InModuleScope AzLocal.UpdateManagement {
            Test-AzLocalReadmeReplaceable -Text '# my-repo' -RepoName '' | Should -BeFalse
        }
    }
}

Describe 'Function: Update-AzLocalPipelineExample' {

    BeforeAll {
        # The cmdlet resolves -Platform 'GitHub' to <ModuleBase>/Automation-Pipeline-Examples/github-actions
        # so all tests below operate against the development checkout's bundled samples.
        $script:UpePlatformSrcGh  = Join-Path $PSScriptRoot '..\Automation-Pipeline-Examples\github-actions'
        $script:UpePlatformSrcAdo = Join-Path $PSScriptRoot '..\Automation-Pipeline-Examples\azure-devops'
    }

    Context 'Parameter surface' {
        It 'Has Destination, Platform, Force, PassThru parameters' {
            $cmd = Get-Command Update-AzLocalPipelineExample
            $cmd.Parameters.Keys | Should -Contain 'Destination'
            $cmd.Parameters.Keys | Should -Contain 'Platform'
            $cmd.Parameters.Keys | Should -Contain 'Force'
            $cmd.Parameters.Keys | Should -Contain 'PassThru'
        }
        It 'Supports ShouldProcess (WhatIf / Confirm)' {
            $cmd = Get-Command Update-AzLocalPipelineExample
            $cmd.Parameters.Keys | Should -Contain 'WhatIf'
            $cmd.Parameters.Keys | Should -Contain 'Confirm'
        }
        It 'Platform is ValidateSet GitHub|AzureDevOps' {
            $cmd = Get-Command Update-AzLocalPipelineExample
            $attr = $cmd.Parameters['Platform'].Attributes |
                Where-Object { $_ -is [System.Management.Automation.ValidateSetAttribute] }
            $attr | Should -Not -BeNullOrEmpty
            ($attr.ValidValues | Sort-Object) -join ',' | Should -Be 'AzureDevOps,GitHub'
        }
        It 'Throws when -Destination does not exist' {
            { Update-AzLocalPipelineExample -Destination "$env:TEMP\does-not-exist-$([guid]::NewGuid())" -Platform GitHub -PassThru } |
                Should -Throw -ExpectedMessage '*Destination*does not exist*'
        }
    }

    Context 'Fleet settings starter lifecycle' {
        It 'Exposes -SkipStarterFleetSettings as a switch parameter' {
            $parameter = (Get-Command Update-AzLocalPipelineExample).Parameters['SkipStarterFleetSettings']
            $parameter | Should -Not -BeNullOrEmpty
            $parameter.ParameterType | Should -Be ([switch])
        }

        It 'Exposes -UpgradeFleetSettingsSchema as a switch parameter' {
            $parameter = (Get-Command Update-AzLocalPipelineExample).Parameters['UpgradeFleetSettingsSchema']
            $parameter | Should -Not -BeNullOrEmpty
            $parameter.ParameterType | Should -Be ([switch])
        }

        It 'Creates a missing starter and automatically upgrades an existing operator file' {
            $repoRoot = Join-Path $env:TEMP "upe-fleet-settings-$([guid]::NewGuid())"
            $dest = Join-Path $repoRoot '.github\workflows'
            $settingsPath = Join-Path $repoRoot 'config\fleet-settings.yml'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null
            try {
                Update-AzLocalPipelineExample -Destination $dest -Platform GitHub -Confirm:$false 6>$null 4>$null | Out-Null
                Test-Path -LiteralPath $settingsPath | Should -BeTrue

                Set-Content -LiteralPath $settingsPath -Value "schemaVersion: 1`n# OPERATOR SENTINEL" -Encoding ASCII
                Update-AzLocalPipelineExample -Destination $dest -Platform GitHub -Confirm:$false 6>$null 4>$null | Out-Null
                (Get-Content -LiteralPath $settingsPath -Raw) | Should -Match 'OPERATOR SENTINEL'
                (Get-AzLocalFleetSettings -Path $settingsPath).SchemaVersion | Should -Be 4
            }
            finally {
                Remove-Item -Path $repoRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }

        It 'Does not create the starter when skipped or under WhatIf' -TestCases @(
            @{ Name = 'skip'; Arguments = @{ SkipStarterFleetSettings = $true; Confirm = $false } }
            @{ Name = 'whatif'; Arguments = @{ WhatIf = $true } }
        ) {
            param($Name, $Arguments)
            $repoRoot = Join-Path $env:TEMP ("upe-fleet-settings-{0}-{1}" -f $Name, [guid]::NewGuid())
            $dest = Join-Path $repoRoot '.github\workflows'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null
            try {
                Update-AzLocalPipelineExample -Destination $dest -Platform GitHub @Arguments 6>$null 4>$null | Out-Null
                Test-Path -LiteralPath (Join-Path $repoRoot 'config\fleet-settings.yml') | Should -BeFalse
            }
            finally {
                Remove-Item -Path $repoRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }

        It 'Automatically upgrades a legacy fully commented schema v1 starter' {
            $repoRoot = Join-Path $env:TEMP "upe-fleet-settings-commented-upgrade-$([guid]::NewGuid())"
            $dest = Join-Path $repoRoot '.github\workflows'
            $settingsPath = Join-Path $repoRoot 'config\fleet-settings.yml'
            $backupPath = Join-Path $repoRoot 'config\fleet-settings_v1.bak.yml'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null
            New-Item -Path (Split-Path -Parent $settingsPath) -ItemType Directory -Force | Out-Null
            $before = "# Legacy inert starter`r`n# schemaVersion: 1`r`n# scope:`r`n#   managementGroups:`r`n#     - contoso-platform`r`n"
            [IO.File]::WriteAllText($settingsPath, $before, [Text.UTF8Encoding]::new($false))
            try {
                Update-AzLocalPipelineExample -Destination $dest -Platform GitHub -Confirm:$false 6>$null 4>$null | Out-Null
                $after = [IO.File]::ReadAllText($settingsPath)
                [IO.File]::ReadAllText($backupPath) | Should -BeExactly $before
                $after | Should -Match '(?m)^# schemaVersion: 4\r?$'
                $after | Should -Match '(?m)^#   clusterTagFilters:\r?$'
                $after | Should -Match '(?m)^# AZLOCAL-FLEET-SETTINGS-SCHEMA-V4\r?$'
                $after | Should -Match '(?m)^# updateStartWindow:\r?$'
                (Get-AzLocalFleetSettings -Path $settingsPath).SchemaVersion | Should -Be 1
                (Get-AzLocalFleetSettings -Path $settingsPath).ScopeMode | Should -Be 'ImplicitSubscriptions'
            }
            finally {
                Remove-Item -Path $repoRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }

        It 'Automatically upgrades active schema v1 while preserving operator content and line endings' {
            $repoRoot = Join-Path $env:TEMP "upe-fleet-settings-upgrade-$([guid]::NewGuid())"
            $dest = Join-Path $repoRoot '.github\workflows'
            $settingsPath = Join-Path $repoRoot 'config\fleet-settings.yml'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null
            New-Item -Path (Split-Path -Parent $settingsPath) -ItemType Directory -Force | Out-Null
            $before = "schemaVersion: 1`r`nscope:`r`n  managementGroups:`r`n    - group-a`r`n# OPERATOR SENTINEL`r`n"
            [IO.File]::WriteAllText($settingsPath, $before, [Text.UTF8Encoding]::new($false))
            try {
                Update-AzLocalPipelineExample -Destination $dest -Platform GitHub -Confirm:$false 6>$null 4>$null | Out-Null
                $after = [IO.File]::ReadAllText($settingsPath)
                $backupPath = Join-Path (Split-Path -Parent $settingsPath) 'fleet-settings_v1.bak.yml'
                [IO.File]::ReadAllText($backupPath) | Should -BeExactly $before
                $after | Should -Match '(?m)^schemaVersion: 4\r$'
                $after | Should -Match '(?m)^scope:\r$'
                $after | Should -Match '(?m)^  managementGroups:\r$'
                $after | Should -Match '(?m)^    - group-a\r$'
                $after | Should -Match '(?m)^# OPERATOR SENTINEL\r$'
                $after | Should -Not -Match '(?<!\r)\n'
                $after | Should -Match '(?m)^# AZLOCAL-FLEET-SETTINGS-SCHEMA-V4\r?$'
                $after | Should -Match '(?m)^#   clusterTagFilters:\r?$'
                $after | Should -Match '(?m)^#     - name: Production\r?$'
                $after | Should -Match '(?m)^#       tags:\r?$'
                $after | Should -Match '(?m)^#           value: Production\r?$'
                ([regex]::Matches($after, '(?m)^# AZLOCAL-FLEET-SETTINGS-SCHEMA-V4\r?$')).Count | Should -Be 1
                (Get-AzLocalFleetSettings -Path $settingsPath).SchemaVersion | Should -Be 4

                Update-AzLocalPipelineExample -Destination $dest -Platform GitHub -Confirm:$false 6>$null 4>$null | Out-Null
                [IO.File]::ReadAllText($settingsPath) | Should -BeExactly $after
                [IO.File]::ReadAllText($backupPath) | Should -BeExactly $before
            }
            finally {
                Remove-Item -Path $repoRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }

        It 'Backs up and upgrades a fully commented schema v2 file while keeping it inert' {
            $repoRoot = Join-Path $env:TEMP "upe-fleet-settings-commented-v2-$([guid]::NewGuid())"
            $dest = Join-Path $repoRoot '.github\workflows'
            $settingsPath = Join-Path $repoRoot 'config\fleet-settings.yml'
            $backupPath = Join-Path $repoRoot 'config\fleet-settings_v2.bak.yml'
            New-Item -Path $dest -ItemType Directory -Force | Out-Null
            New-Item -Path (Split-Path -Parent $settingsPath) -ItemType Directory -Force | Out-Null
            $before = @(
                '# AzLocal.UpdateManagement fleet settings (schema version 1)'
                '# schemaVersion: 2'
                '# scope:'
                '#   clusterTagFilters:'
                '#     - name: Live-Environment'
                '#       value: Yes'
                '#     - name: Test-Environment'
                '#       value: Yes'
                '# AZLOCAL-FLEET-SETTINGS-SCHEMA-V2'
            ) -join "`r`n"
            [IO.File]::WriteAllText($settingsPath, $before, [Text.UTF8Encoding]::new($false))
            try {
                Update-AzLocalPipelineExample -Destination $dest -Platform GitHub -Confirm:$false 6>$null 4>$null | Out-Null
                $after = [IO.File]::ReadAllText($settingsPath)

                [IO.File]::ReadAllText($backupPath) | Should -BeExactly $before
                $after | Should -Match '(?m)^# AzLocal\.UpdateManagement fleet settings \(schema version 4\)\r?$'
                $after | Should -Match '(?m)^# schemaVersion: 4\r?$'
                $after | Should -Match '(?m)^#       tags:\r?$'
                $after | Should -Match '(?m)^#         - name: Live-Environment\r?$'
                $after | Should -Match '(?m)^# AZLOCAL-FLEET-SETTINGS-SCHEMA-V4\r?$'
                $after | Should -Not -Match 'SCHEMA-V2'
                @($after -split '\r?\n' | Where-Object { $_.Trim() -and -not $_.Trim().StartsWith('#') }).Count | Should -Be 0
                (Get-AzLocalFleetSettings -Path $settingsPath).ScopeMode | Should -Be 'ImplicitSubscriptions'
                @((Get-AzLocalFleetSettings -Path $settingsPath).ClusterTagFilters).Count | Should -Be 0

                Update-AzLocalPipelineExample -Destination $dest -Platform GitHub -Confirm:$false 6>$null 4>$null | Out-Null
                [IO.File]::ReadAllText($settingsPath) | Should -BeExactly $after
                [IO.File]::ReadAllText($backupPath) | Should -BeExactly $before
            }
            finally {
                Remove-Item -Path $repoRoot -Recurse -Force -ErrorAction SilentlyContinue
            }
        }

        It 'Does not rewrite schema v1 under WhatIf' {
