    It 'Stalled InProgress run (lastUpdatedTime frozen beyond StalledNoProgressHours): StalledCount=1, CRITICAL, stalled chip' {
        # Arizona run 19444cab repro: State=InProgress for weeks, but ARM
        # lastUpdatedTime froze after only ~9 minutes of runtime. The run is
        # making zero progress yet still reports InProgress.
        $env:GITHUB_ACTIONS      = 'true'
        $env:GITHUB_OUTPUT       = $script:_s7_ghOutputFile
        $env:GITHUB_STEP_SUMMARY = $script:_s7_ghSummaryFile
        $runs = @(
            [pscustomobject]@{
                ClusterName       = 'alpha'
                ClusterResourceId = $script:_s7_inventory[0].ResourceId
                UpdateName        = 'Solution12.2604.1003.1005'
                State             = 'InProgress'
                Status            = 'InProgress'
                CurrentStep       = 'Run Update Health Checks'
                Progress          = ''
                StartTime         = $script:_s7_now.AddDays(-30).ToString('yyyy-MM-ddTHH:mm:ss')
                StepStartTime     = $script:_s7_now.AddDays(-30).ToString('yyyy-MM-ddTHH:mm:ss')
                LastUpdatedTime   = $script:_s7_now.AddDays(-30).AddMinutes(9).ToString('yyyy-MM-ddTHH:mm:ss')   # frozen ~30d ago
                EndTime           = $null
                RunId             = '19444cab'
                RunResourceId     = ($script:_s7_inventory[0].ResourceId + '/updates/Solution12.2604.1003.1005/updateRuns/19444cab')
            }
        )
        $global:_s7_payload = @{ Inventory = $script:_s7_inventory; Runs = $runs; Now = $script:_s7_now; OutDir = $script:_s7_outDir }
        $result = InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalClusterInventory { @($global:_s7_payload.Inventory) }
            Mock Get-AzLocalUpdateRuns       { @($global:_s7_payload.Runs) }
            Export-AzLocalUpdateRunMonitorReport -OutputDirectory $global:_s7_payload.OutDir -Now $global:_s7_payload.Now -StalledNoProgressHours 24 -PassThru
        }
        $result.InFlightCount | Should -Be 1
        $result.StalledCount  | Should -Be 1
        $row = @($result.Rows)[0]
        $row.IsStalled            | Should -BeTrue
        $row.LastUpdatedUtc       | Should -Not -BeNullOrEmpty
        $row.SinceLastUpdateHours | Should -BeGreaterThan 24
        $row.Flags                | Should -Match 'stalled'
        $row.SeverityScore        | Should -BeGreaterThan 599
        (Get-Content -Raw -LiteralPath $script:_s7_ghOutputFile)  | Should -Match 'stalled=1'
        (Get-Content -Raw -LiteralPath $script:_s7_ghSummaryFile) | Should -Match 'Fleet Status: CRITICAL'
    }

    It 'Stalled run surfaces in the JUnit testcase as a Stalled-typed failure (not just a long-running-step reason)' {
        # v0.8.96 regression: before this, a stalled run fell into the
        # ExceedsStepThreshold branch and the JUnit failure message (what the
        # test-reporter check renders) only said 'step exceeds Nh' - never that
        # the run was stalled/orphaned. The stall was visible only in the CSV.
        $runs = @(
            [pscustomobject]@{
                ClusterName       = 'alpha'
                ClusterResourceId = $script:_s7_inventory[0].ResourceId
                UpdateName        = 'Solution12.2604.1003.1005'
                State             = 'InProgress'
                Status            = 'InProgress'
                CurrentStep       = 'CAU Attempt'
                Progress          = '132/167 steps (79%)'
                StartTime         = $script:_s7_now.AddDays(-30).ToString('yyyy-MM-ddTHH:mm:ss')
                StepStartTime     = $script:_s7_now.AddDays(-30).ToString('yyyy-MM-ddTHH:mm:ss')
                LastUpdatedTime   = $script:_s7_now.AddDays(-30).AddMinutes(9).ToString('yyyy-MM-ddTHH:mm:ss')
                EndTime           = $null
                RunId             = '19444cab'
                RunResourceId     = ($script:_s7_inventory[0].ResourceId + '/updates/Solution12.2604.1003.1005/updateRuns/19444cab')
            }
        )
        $env:GITHUB_ACTIONS      = 'true'
        $env:GITHUB_OUTPUT       = $script:_s7_ghOutputFile
        $env:GITHUB_STEP_SUMMARY = $script:_s7_ghSummaryFile
        $global:_s7_payload = @{ Inventory = $script:_s7_inventory; Runs = $runs; Now = $script:_s7_now; OutDir = $script:_s7_outDir }
        $null = InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalClusterInventory { @($global:_s7_payload.Inventory) }
            Mock Get-AzLocalUpdateRuns       { @($global:_s7_payload.Runs) }
            Export-AzLocalUpdateRunMonitorReport -OutputDirectory $global:_s7_payload.OutDir -Now $global:_s7_payload.Now -StalledNoProgressHours 24
        }
        [xml]$xml = Get-Content -Raw -LiteralPath (Join-Path $script:_s7_outDir 'update-monitor.xml')
        $stalledCases = @($xml.SelectNodes('//testcase') | Where-Object { $_.name -match 'alpha' })
        $stalledCases.Count        | Should -BeGreaterOrEqual 1
        $stalledCases[0].failure.type    | Should -Be 'Stalled'
        $stalledCases[0].failure.message | Should -Match 'STALLED: no orchestration activity'
        # v0.8.96: the failure body must also spell out the manual remediation
        # (the run is not auto-retried) with the Get-/Start-SolutionUpdate flow
        # and the public troubleshooting doc link.
        $stalledCases[0].failure.message | Should -Match 'MANUAL ACTION REQUIRED'
        $stalledCases[0].failure.message | Should -Match 'Start-SolutionUpdate'
        $stalledCases[0].failure.message | Should -Match 'update-troubleshooting-23h2'
        # the Status property the ITSM connector matches on must be 'Stalled'
        $statusProp = @($stalledCases[0].properties.property | Where-Object { $_.name -eq 'Status' })
        $statusProp[0].value | Should -Be 'Stalled'
        # the markdown step summary must carry the operator-action callout too
        $summaryMd = Get-Content -Raw -LiteralPath $script:_s7_ghSummaryFile
        $summaryMd | Should -Match 'Stalled / orphaned run\(s\) detected'
        $summaryMd | Should -Match 'Manual action required'
    }

