            foreach ($n in 'SUCCEEDED','SKIPPED','FAILED','HEALTH_BLOCKED','SCHEDULE_BLOCKED','SIDELOADED_BLOCKED','EXCLUDED_BY_TAG') {
                $outFile | Should -Match "$n=0"
