#endregion v0.8.5 Step.6 thin-YAML: Apply-Updates pipeline cmdlets

# =====================================================================
# v0.8.6 regression tests for pipeline bugs introduced in v0.8.5
# =====================================================================
#
# All four production regressions shipped in v0.8.5 share two root causes:
#   (1) `@(<helper>)` wrap on a helper that uses unary-comma `return , $arr`
#       silently collapses the row-set to Object[1] (the outer wrapper) -
#       see github-patterns.md in user memory.
#   (2) `[type]$x = if (cond) { @(...) } else { @() }` without an explicit
#       array cast lets the if-as-expression unwrap a single-element @()
#       into a bare scalar; downstream `$x.Count` then throws under
#       Set-StrictMode -Version Latest.
# These static-source tests would have caught all four pre-release.

Describe 'v0.8.6 regression guard: @() wrap on unary-comma return helpers' {

    BeforeAll {
        # Helpers whose internal `return , $arr` (or equivalent) MUST be assigned
        # directly. Any caller that wraps them in `@()` collapses the row-set to
        # Object[1] and silently loses every row beyond the first. See
        # github-patterns.md for the full failure-mode explanation.
        $script:V086_UnaryCommaHelpers = @(
            'Invoke-AzResourceGraphQuery',
            'Get-AzLocalFleetHealthFailures',
            'Get-AzLocalFleetHealthOverview',
            'Read-AzLocalApplyUpdatesYamlCrons'
        )
        $script:V086_ModuleRoot = Split-Path -Parent $PSScriptRoot
        $script:V086_PsFiles = Get-ChildItem -Path $script:V086_ModuleRoot -Recurse -Filter '*.ps1' -File |
            Where-Object { $_.FullName -notmatch '\\Tests\\' }
    }

    It 'no Public/Private .ps1 file wraps <Helper> with @(...) - silently collapses row-set' -ForEach @(
        @{ Helper = 'Invoke-AzResourceGraphQuery' },
        @{ Helper = 'Get-AzLocalFleetHealthFailures' },
        @{ Helper = 'Get-AzLocalFleetHealthOverview' },
        @{ Helper = 'Read-AzLocalApplyUpdatesYamlCrons' }
    ) {
        $pattern = "@\(\s*$([regex]::Escape($Helper))\b"
        $offenders = [System.Collections.Generic.List[string]]::new()
        foreach ($file in $script:V086_PsFiles) {
            $lines = Get-Content -LiteralPath $file.FullName
            for ($i = 0; $i -lt $lines.Count; $i++) {
                if ($lines[$i] -match $pattern) {
                    $offenders.Add(("{0}:{1}: {2}" -f $file.Name, ($i + 1), $lines[$i].Trim()))
                }
            }
        }
        $offenders.Count | Should -Be 0 -Because (
            "wrapping '$Helper' (which uses `return , `$arr` unary-comma return) " +
            "with @() silently collapses the row-set to Object[1] containing the " +
            "inner array. Found:`n$($offenders -join "`n")"
        )
    }
}

Describe 'v0.8.6 regression guard: Step.4 ARB strict-mode .Count crash on single-cluster RG' {

    It 'Get-AzLocalFleetConnectivityStatus uses explicit if/else with @($clustersByRg[$rg]) (NOT @($null) which yields Object[1] containing $null)' {
        $path = Join-Path -Path $PSScriptRoot -ChildPath '..\Public\Get-AzLocalFleetConnectivityStatus.ps1'
        $content = Get-Content -LiteralPath $path -Raw
        # v0.8.6-fix3: `@($null)` produces an Object[1] containing $null (NOT an empty array),
        # so downstream `$matched.Count -gt 0` is true and `$_.ClusterName` on the null element
        # throws PropertyNotFound. The reliable pattern is an explicit if/else where the miss
        # branch assigns a real empty array (`@()`) and the hit branch wraps the list.
        $content | Should -Match '(?s)if\s*\(\s*\$clustersByRg\.ContainsKey\(\$rg\)\s*\)\s*\{\s*\$matched\s*=\s*@\(\$clustersByRg\[\$rg\]\)\s*\}\s*else\s*\{\s*\$matched\s*=\s*@\(\)\s*\}' -Because (
            'Step.4 must branch explicitly on ContainsKey, with the else branch assigning a literal `@()` ' +
            'to $matched. @($null) does NOT yield an empty array.'
        )
        # The OLD broken patterns must be gone.
        $content | Should -Not -Match '\[object\[\]\]\$matched\s*=\s*if\s*\(\$clustersByRg'
        $content | Should -Not -Match '\$matchedList\s*=\s*if\s*\(\$clustersByRg\.ContainsKey\(\$rg\)\)\s*\{\s*\$clustersByRg\[\$rg\]\s*\}\s*else\s*\{\s*\$null\s*\}'
    }
}

Describe 'v0.8.6 regression guard: Step.6 Get-AzLocalClusterUpdateReadiness $cluster.NotFound strict-mode crash' {

    It 'every "$clustersToProcess += @{ ... }" block sets a NotFound key' {
        # Under Set-StrictMode -Version Latest, dot-notation on a hashtable
        # missing the requested key throws "The property 'NotFound' cannot be
        # found on this object." Every hashtable shape MUST define NotFound or
        # the iteration at line ~337 (`if ($cluster.NotFound)`) crashes Step.6.
        $path = Join-Path -Path $PSScriptRoot -ChildPath '..\Public\Get-AzLocalClusterUpdateReadiness.ps1'
        $content = Get-Content -LiteralPath $path -Raw
        # Find every `$clustersToProcess += @{ ... }` block (lazy match, dotall).
        $rx = [regex]'(?s)\$clustersToProcess\s*\+=\s*@\{(?<body>.*?)\}'
        $rxMatches = $rx.Matches($content)
        $rxMatches.Count | Should -BeGreaterThan 0 -Because 'the regression-guarded code shape must be present'
        $offenders = [System.Collections.Generic.List[string]]::new()
        foreach ($m in $rxMatches) {
            if ($m.Groups['body'].Value -notmatch '(?m)^\s*NotFound\s*=') {
                $offenders.Add($m.Value.Trim())
            }
        }
        $offenders.Count | Should -Be 0 -Because (
            "every `$clustersToProcess += @{ } literal must include 'NotFound = `$true' or 'NotFound = `$false' " +
            "so the strict-mode dot-access at iteration time cannot throw. Offending block(s):`n$($offenders -join "`n---`n")"
        )
    }
}

Describe 'v0.8.6 regression guard: GitHub Actions Node.js 20 deprecation' {

    BeforeAll {
        $script:V086_GhaRoot = Join-Path -Path (Split-Path -Parent $PSScriptRoot) -ChildPath 'Automation-Pipeline-Examples\github-actions'
        $script:V086_GhaYamls = if (Test-Path -LiteralPath $script:V086_GhaRoot) {
            Get-ChildItem -Path $script:V086_GhaRoot -Filter '*.yml' -File
        } else { @() }
    }

    It 'no bundled GHA YAML uses actions/upload-artifact@v[1-5] (Node 20 - deprecated)' {
        $offenders = [System.Collections.Generic.List[string]]::new()
        foreach ($yml in $script:V086_GhaYamls) {
            $lines = Get-Content -LiteralPath $yml.FullName
            for ($i = 0; $i -lt $lines.Count; $i++) {
                if ($lines[$i] -match 'actions/upload-artifact@v[1-5]\b') {
                    $offenders.Add(("{0}:{1}: {2}" -f $yml.Name, ($i + 1), $lines[$i].Trim()))
                }
            }
        }
        $offenders.Count | Should -Be 0 -Because (
            "actions/upload-artifact v1-v5 run on Node.js 20 which GitHub has deprecated. " +
            "Bump to @v6 or later to avoid the deprecation warning in production runs. Found:`n$($offenders -join "`n")"
        )
    }

    It 'no bundled GHA YAML uses actions/download-artifact@v[1-3] (Node 20 - deprecated)' {
        $offenders = [System.Collections.Generic.List[string]]::new()
        foreach ($yml in $script:V086_GhaYamls) {
            $lines = Get-Content -LiteralPath $yml.FullName
            for ($i = 0; $i -lt $lines.Count; $i++) {
                if ($lines[$i] -match 'actions/download-artifact@v[1-3]\b') {
                    $offenders.Add(("{0}:{1}: {2}" -f $yml.Name, ($i + 1), $lines[$i].Trim()))
                }
            }
        }
        $offenders.Count | Should -Be 0 -Because (
            "actions/download-artifact v1-v3 run on Node.js 20. Bump to @v4 or later. " +
            "Found:`n$($offenders -join "`n")"
        )
    }
}

Describe 'v0.8.6 functional regression: Export-AzLocalAuthValidationReport preserves all cluster rows from unary-comma helper' {

    It 'Reports the true cluster count (not 1) when Invoke-AzResourceGraphQuery returns 20 rows via unary-comma' {
        # Smoke-test the source line shape: Step.0 cluster reachability MUST
        # assign Invoke-AzResourceGraphQuery directly (no @() wrap), then
        # report $clusterRows.Count. We can't easily mock through the whole
        # cmdlet here (it has many dependencies) - instead assert the
        # specific source pattern that was buggy in v0.8.5.
        $path = Join-Path -Path $PSScriptRoot -ChildPath '..\Public\Export-AzLocalAuthValidationReport.ps1'
        $content = Get-Content -LiteralPath $path -Raw
        # The fixed line MUST be a direct assignment, NOT @(...).
        $content | Should -Match '(?m)^\s*\$clusterRows\s*=\s*Invoke-AzResourceGraphQuery\s+-Query\s+\$clusterKql' -Because (
            'Step.0 must use direct assignment (`$clusterRows = Invoke-AzResourceGraphQuery ...`) - ' +
            'wrapping with @() collapses 20 clusters to Object[1] and reports "1 cluster(s) visible".'
        )
        $content | Should -Not -Match '\$clusterRows\s*=\s*@\(\s*Invoke-AzResourceGraphQuery'
    }
}

Describe 'v0.8.6 functional regression: Export-AzLocalFleetHealthStatusReport preserves all detail rows from unary-comma helper' {

    It 'Step.9 assigns Get-AzLocalFleetHealthFailures directly (no @() wrap that collapses 81 rows to 1)' {
        $path = Join-Path -Path $PSScriptRoot -ChildPath '..\Public\Export-AzLocalFleetHealthStatusReport.ps1'
        $content = Get-Content -LiteralPath $path -Raw
        $content | Should -Match '(?m)^\s*\$detail\s*=\s*Get-AzLocalFleetHealthFailures\s+-View\s+Detail'
        $content | Should -Not -Match '\$detail\s*=\s*@\(\s*Get-AzLocalFleetHealthFailures'
    }

    It 'Step.9 assigns Get-AzLocalFleetHealthOverview directly (no @() wrap that collapses fleet rows to 1)' {
        $path = Join-Path -Path $PSScriptRoot -ChildPath '..\Public\Export-AzLocalFleetHealthStatusReport.ps1'
        $content = Get-Content -LiteralPath $path -Raw
        $content | Should -Match '(?m)^\s*\$overview\s*=\s*Get-AzLocalFleetHealthOverview\b'
        $content | Should -Not -Match '\$overview\s*=\s*@\(\s*Get-AzLocalFleetHealthOverview'
    }
}

Describe 'v0.8.6 regression guard: Step.3 Test-AzLocalApplyUpdatesScheduleCoverage MatchingCrons strict-mode crash' {

    It 'guards $segmentStatuses.MatchingCrons via explicit ForEach-Object enumeration (NOT array-level member-access)' {
        # Under Set-StrictMode -Version Latest, `$segmentStatuses.MatchingCrons` member-access
        # on an array throws "The property 'MatchingCrons' cannot be found on this object."
        # even when Count > 0. The fix uses `$segmentStatuses | ForEach-Object { $_.MatchingCrons }`
        # to enumerate explicitly, AND guards with `if ($segmentStatuses.Count -gt 0)` for the
        # empty-array case (v0.8.5 Step.3 production regression).
        $path = Join-Path -Path $PSScriptRoot -ChildPath '..\Public\Test-AzLocalApplyUpdatesScheduleCoverage.ps1'
        $content = Get-Content -LiteralPath $path -Raw
        $content | Should -Match '\$segmentStatuses\.Count\s*-gt\s*0' -Because (
            'the .MatchingCrons access path MUST be guarded by `if ($segmentStatuses.Count -gt 0)`.'
        )
        $content | Should -Match '\$segmentStatuses\s*\|\s*ForEach-Object\s*\{\s*\$_\.MatchingCrons\s*\}' -Because (
            'explicit `ForEach-Object { $_.MatchingCrons }` is required - array-level member-access ' +
            '`$segmentStatuses.MatchingCrons` throws PropertyNotFound under strict mode.'
        )
        # The unguarded one-liner AND the array-level member-access must be gone.
        $content | Should -Not -Match '(?m)^\s+\$allMatched\s*=\s*@\(\$segmentStatuses\.MatchingCrons'
        $content | Should -Not -Match '@\(\$segmentStatuses\.MatchingCrons\s*\|\s*Select-Object\s*-Unique\)'
    }
}

Describe 'v0.8.6 regression guard: Step.0 Export-AzLocalAuthValidationReport defensive @() coerce on $clusterRows' {

    It 'coerces $clusterRows = @($clusterRows) before reading .Count so scalar returns become Object[1]' {
        # When a downstream Invoke-AzResourceGraphQuery mock or shape change returns
        # a single PSCustomObject (instead of Object[1]), $clusterRows.Count returns
        # $null under strict mode. The defensive @() on the VARIABLE (not the call)
        # is idempotent on Object[N] and safe to apply.
        $path = Join-Path -Path $PSScriptRoot -ChildPath '..\Public\Export-AzLocalAuthValidationReport.ps1'
        $content = Get-Content -LiteralPath $path -Raw
        $content | Should -Match '\$clusterRows\s*=\s*@\(\$clusterRows\)' -Because (
            'Step.0 must defensively coerce $clusterRows = @($clusterRows) after the ARG call ' +
            'so .Count is always a valid integer property, even when callers (tests) mock with a single object.'
        )
    }
}

#region On-Prem Sideloading Automation (v0.8.7) - behaviour tests for the 5 new public cmdlets

Describe 'Sideload (v0.8.7): Update-AzLocalSideloadCatalog' {

    Context 'Offline HTML parsing + catalog merge' {

        It 'Parses CombinedSolutionBundle rows from offline HTML and writes a reviewable catalog' {
            $catalogPath = Join-Path $env:TEMP ("azlocal-sideload-catalog-{0}.yml" -f ([Guid]::NewGuid()))
            try {
                $html = @'
<table>
  <tr><td><a href="https://download.contoso.com/CombinedSolutionBundle.12.2605.1003.210.zip">12.2605.1003.210</a></td>
      <td>26100.4061</td>
      <td>SHA256: ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789. Availability date: 2026-05-15</td></tr>
</table>
'@
                $result = Update-AzLocalSideloadCatalog -Path $catalogPath -Html $html -Confirm:$false

                $result | Should -Not -BeNullOrEmpty
                @($result).Count | Should -Be 1
                $result[0].Version | Should -Be '12.2605.1003.210'
                $result[0].PackageType | Should -Be 'Solution'
                $result[0].OsBuild | Should -Be '26100.4061'
                $result[0].DownloadUri | Should -Be 'https://download.contoso.com/CombinedSolutionBundle.12.2605.1003.210.zip'
                $result[0].Sha256 | Should -Be 'ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789'
                $result[0].AvailabilityDate | Should -Be '2026-05-15'

                Test-Path -LiteralPath $catalogPath | Should -BeTrue
                $written = Get-Content -LiteralPath $catalogPath -Raw
                $written | Should -Match "version: '12\.2605\.1003\.210'"
                $written | Should -Match 'packageType: Solution'
            }
            finally {
                Remove-Item -LiteralPath $catalogPath -Force -ErrorAction SilentlyContinue
            }
        }

        It 'Preserves existing SBE (OEM) entries while merging Solution rows' {
            $catalogPath = Join-Path $env:TEMP ("azlocal-sideload-catalog-{0}.yml" -f ([Guid]::NewGuid()))
            try {
                # Seed an SBE entry the operator authored by hand.
                $seed = @'
schemaVersion: 1
packages:
  - version: '12.2605.1003.210'
    packageType: SBE
    sourceFolder: '\\fileserver\sbe\contoso'
    sha256: '1111111111111111111111111111111111111111111111111111111111111111'
'@
                Set-Content -LiteralPath $catalogPath -Value $seed -Encoding ASCII

                $html = @'
<a href="https://download.contoso.com/CombinedSolutionBundle.12.2606.0.99.zip">12.2606.0.99</a>
<span>SHA256 2222222222222222222222222222222222222222222222222222222222222222 Availability date: 2026-06-01</span>
'@
                $result = Update-AzLocalSideloadCatalog -Path $catalogPath -Html $html -Confirm:$false

                # SBE entry preserved + new Solution entry appended.
                $sbe = @($result | Where-Object { $_.PackageType -eq 'SBE' })
                $sbe.Count | Should -Be 1
                $sbe[0].Version | Should -Be '12.2605.1003.210'

                $sol = @($result | Where-Object { $_.PackageType -eq 'Solution' -and $_.Version -eq '12.2606.0.99' })
                $sol.Count | Should -Be 1
                $sol[0].DownloadUri | Should -Match 'CombinedSolutionBundle\.12\.2606\.0\.99\.zip'
            }
            finally {
                Remove-Item -LiteralPath $catalogPath -Force -ErrorAction SilentlyContinue
            }
        }

        It 'Does not write the catalog under -WhatIf' {
            $catalogPath = Join-Path $env:TEMP ("azlocal-sideload-catalog-{0}.yml" -f ([Guid]::NewGuid()))
            try {
                $html = '<a href="https://download.contoso.com/CombinedSolutionBundle.12.2605.1003.210.zip">12.2605.1003.210</a>'
                $null = Update-AzLocalSideloadCatalog -Path $catalogPath -Html $html -WhatIf
                Test-Path -LiteralPath $catalogPath | Should -BeFalse -Because '-WhatIf must not write the catalog file'
            }
            finally {
                Remove-Item -LiteralPath $catalogPath -Force -ErrorAction SilentlyContinue
            }
        }
    }

    Context 'Schema migration (-SchemaMigrate)' {

        It '-SchemaMigrate is exposed as a [switch] parameter' {
            $cmd = Get-Command -Name 'Update-AzLocalSideloadCatalog' -ErrorAction Stop
            $cmd.Parameters.ContainsKey('SchemaMigrate') | Should -BeTrue
            $cmd.Parameters['SchemaMigrate'].ParameterType | Should -Be ([switch])
        }

        It 'Migrating a v1 catalog is a no-op (already on the current schema) and leaves the file untouched' {
            $catalogPath = Join-Path $env:TEMP ("azlocal-sideload-catalog-{0}.yml" -f ([Guid]::NewGuid()))
            try {
                $seed = @'
# Operator comment that must survive
schemaVersion: 1
packages:
  - version: 'DellSBE-4.1.2412.1'
    packageType: SBE
    sourceFolder: '\\fileserver\sbe\Dell\4.1.2412.1'
'@
                Set-Content -LiteralPath $catalogPath -Value $seed -Encoding ASCII
                $before = Get-Content -LiteralPath $catalogPath -Raw

                $result = Update-AzLocalSideloadCatalog -Path $catalogPath -SchemaMigrate -Confirm:$false

                $result.Action | Should -Be 'Unchanged-SchemaCurrent'
                $result.FromVersion | Should -Be 1
                $result.ToVersion | Should -Be 1
                $result.BackupPath | Should -BeNullOrEmpty
                # File content unchanged; no backup written.
                (Get-Content -LiteralPath $catalogPath -Raw) | Should -Be $before
                $base = [System.IO.Path]::GetFileNameWithoutExtension($catalogPath)
                Test-Path -LiteralPath (Join-Path (Split-Path -Parent $catalogPath) ($base + '.v1.old.yml')) | Should -BeFalse
            }
            finally {
                Remove-Item -LiteralPath $catalogPath -Force -ErrorAction SilentlyContinue
            }
        }

        It '-SchemaMigrate on a missing file throws a clear error' {
            $missing = Join-Path $env:TEMP ("azlocal-sideload-missing-{0}.yml" -f ([Guid]::NewGuid()))
            { Update-AzLocalSideloadCatalog -Path $missing -SchemaMigrate -Confirm:$false } |
                Should -Throw -ExpectedMessage '*catalog file not found*'
        }
    }
}

Describe 'Sideload (v0.8.7): catalog schema framework' {

    It 'Get-AzLocalSideloadCatalog REFUSES a catalog written by a newer module (higher schemaVersion)' {
        $catalogPath = Join-Path $env:TEMP ("azlocal-sideload-future-{0}.yml" -f ([Guid]::NewGuid()))
        try {
            $seed = @'
schemaVersion: 99
packages:
  - version: '12.2605.1003.210'
    packageType: Solution
    downloadUri: 'https://contoso/CombinedSolutionBundle.zip'
    sha256: 'ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789ABCDEF0123456789'
'@
            Set-Content -LiteralPath $catalogPath -Value $seed -Encoding ASCII
            {
                InModuleScope AzLocal.UpdateManagement -Parameters @{ P = $catalogPath } {
                    param($P)
                    Get-AzLocalSideloadCatalog -Path $P
                }
            } | Should -Throw -ExpectedMessage '*only supports up to*'
        }
        finally {
            Remove-Item -LiteralPath $catalogPath -Force -ErrorAction SilentlyContinue
        }
    }

    It 'Get-AzLocalSideloadCatalog tolerates a MISSING schemaVersion (treated as v1) and parses packages' {
        $catalogPath = Join-Path $env:TEMP ("azlocal-sideload-nosv-{0}.yml" -f ([Guid]::NewGuid()))
        try {
            $seed = @'
packages:
  - version: 'DellSBE-4.1.2412.1'
    packageType: SBE
    sourceFolder: '\\fileserver\sbe\Dell\4.1.2412.1'
'@
            Set-Content -LiteralPath $catalogPath -Value $seed -Encoding ASCII
            $pkgs = @(InModuleScope AzLocal.UpdateManagement -Parameters @{ P = $catalogPath } {
                param($P)
                Get-AzLocalSideloadCatalog -Path $P
            })
            $pkgs.Count | Should -Be 1
            $pkgs[0].Version | Should -Be 'DellSBE-4.1.2412.1'
        }
        finally {
            Remove-Item -LiteralPath $catalogPath -Force -ErrorAction SilentlyContinue
        }
    }

    It 'Convert-AzLocalSideloadCatalogSchemaVersion is a no-op at the current schema version' {
        $r = InModuleScope AzLocal.UpdateManagement {
            $text = "schemaVersion: $($script:SideloadCatalogSchemaCurrentVersion)`r`npackages:`r`n"
            Convert-AzLocalSideloadCatalogSchemaVersion -Text $text
        }
        $r.Migrated | Should -BeFalse
        $r.Hops.Count | Should -Be 0
    }

    It 'Convert-AzLocalSideloadCatalogSchemaVersion throws a wired-up error when a hop is missing (empty recipe table at v1)' {
        {
            InModuleScope AzLocal.UpdateManagement {
                # Force a target one above current; the v1 recipe table is empty
                # so the engine must report the missing '1->2' hop.
                Convert-AzLocalSideloadCatalogSchemaVersion -Text "schemaVersion: 1`r`npackages:`r`n" -TargetSchemaVersion 2
            }
        } | Should -Throw -ExpectedMessage "*no migration recipe registered for '1->2'*"
    }
}

Describe 'Sideload (v0.8.7): Resolve-AzLocalSideloadPlan' {

    It 'Flags clusters whose UpdateAuthAccountId is not in the auth map' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalApplyUpdatesScheduleConfig { [PSCustomObject]@{} }
            Mock Get-AzLocalSideloadAuthMap { @{} }   # empty -> any account id is unknown
            Mock Get-AzLocalSideloadCatalog { @() }
            Mock ConvertTo-AzLocalUpdateRingKqlFilter { '' }
            Mock Get-AzLocalApplyUpdatesScheduleNextFirings { @() }
            Mock Invoke-AzResourceGraphQuery {
                @([PSCustomObject]@{
                        id             = '/subscriptions/s/clusters/c1'
                        name           = 'cluster1'
                        resourceGroup  = 'rg1'
                        subscriptionId = 's'
                        tags           = [PSCustomObject]@{ UpdateAuthAccountId = 'missing-acct'; UpdateRing = 'Ring1' }
                    })
            }

            $plan = Resolve-AzLocalSideloadPlan -SchedulePath 'sched.yml' -AuthMapPath 'auth.csv' -CatalogPath 'cat.yml'

            @($plan).Count | Should -Be 1
            $plan[0].Status | Should -Be 'UnknownAuthAccountId'
            $plan[0].ClusterName | Should -Be 'cluster1'
        }
    }

    It 'Emits a Planned row when the cluster is due and the selected version is in the catalog' {
        InModuleScope AzLocal.UpdateManagement {
            $script:PlanNow = [datetime]'2026-06-11T00:00:00Z'

            Mock Get-AzLocalApplyUpdatesScheduleConfig { [PSCustomObject]@{} }
            Mock Get-AzLocalSideloadAuthMap {
                @{ 'acct1' = [PSCustomObject]@{ RemotingTargetFqdn = 'host1.contoso.com'; ImportSharePath = '\\host1\import'; AuthMechanism = 'Negotiate' } }
            }
            Mock Get-AzLocalSideloadCatalog {
                @([PSCustomObject]@{ Version = '12.2605.1003.210'; PackageType = 'Solution' })
            }
            Mock ConvertTo-AzLocalUpdateRingKqlFilter { '' }
            Mock Resolve-AzLocalSideloadTargetPath { '\\host1\import' }
            Mock Resolve-AzLocalCurrentUpdateRing { [PSCustomObject]@{ AllowedUpdateVersions = @('12.2605.1003.210') } }
            Mock Get-AzLocalAvailableUpdates {
                @([PSCustomObject]@{ UpdateState = 'Ready'; UpdateName = 'Solution12'; PackageType = 'Solution'; Version = '12.2605.1003.210' })
            }
            Mock Select-AzLocalNextUpdateForCluster {
                [PSCustomObject]@{
                    Reason         = 'Selected'
                    SelectedUpdate = [PSCustomObject]@{ name = 'Solution12'; PackageType = 'Solution'; properties = [PSCustomObject]@{ version = '12.2605.1003.210'; state = 'Ready' } }
                }
            }
            Mock Get-AzLocalApplyUpdatesScheduleNextFirings {
                @([PSCustomObject]@{ Rings = @('Ring1'); DateUtc = $script:PlanNow.AddDays(2) })
            }
            Mock Invoke-AzResourceGraphQuery {
                @([PSCustomObject]@{
                        id             = '/subscriptions/s/clusters/c1'
                        name           = 'cluster1'
                        resourceGroup  = 'rg1'
                        subscriptionId = 's'
                        tags           = [PSCustomObject]@{ UpdateAuthAccountId = 'acct1'; UpdateRing = 'Ring1' }
                    })
            }

            # NextWindow = Now+2, LeadDays=7 -> dueDate = Now-5 <= Now -> DueNow -> Planned
            $plan = Resolve-AzLocalSideloadPlan -SchedulePath 'sched.yml' -AuthMapPath 'auth.csv' -CatalogPath 'cat.yml' -LeadDays 7 -Now $script:PlanNow

            @($plan).Count | Should -Be 1
            $plan[0].Status | Should -Be 'Planned'
            $plan[0].DueNow | Should -BeTrue
            $plan[0].SelectedVersion | Should -Be '12.2605.1003.210'
            $plan[0].CatalogEntry | Should -Not -BeNullOrEmpty
        }
    }

    It 'Flags NoCatalogEntry when the selected version is absent from the catalog' {
        InModuleScope AzLocal.UpdateManagement {
            $script:PlanNow2 = [datetime]'2026-06-11T00:00:00Z'

            Mock Get-AzLocalApplyUpdatesScheduleConfig { [PSCustomObject]@{} }
            Mock Get-AzLocalSideloadAuthMap {
                @{ 'acct1' = [PSCustomObject]@{ RemotingTargetFqdn = 'host1.contoso.com'; ImportSharePath = '\\host1\import' } }
            }
            Mock Get-AzLocalSideloadCatalog { @() }   # empty catalog
            Mock ConvertTo-AzLocalUpdateRingKqlFilter { '' }
            Mock Resolve-AzLocalSideloadTargetPath { '\\host1\import' }
            Mock Resolve-AzLocalCurrentUpdateRing { [PSCustomObject]@{ AllowedUpdateVersions = @('12.2605.1003.210') } }
            Mock Get-AzLocalAvailableUpdates {
                @([PSCustomObject]@{ UpdateState = 'Ready'; UpdateName = 'Solution12'; PackageType = 'Solution'; Version = '12.2605.1003.210' })
            }
            Mock Select-AzLocalNextUpdateForCluster {
                [PSCustomObject]@{
                    Reason         = 'Selected'
                    SelectedUpdate = [PSCustomObject]@{ name = 'Solution12'; PackageType = 'Solution'; properties = [PSCustomObject]@{ version = '12.2605.1003.210'; state = 'Ready' } }
                }
            }
            Mock Get-AzLocalApplyUpdatesScheduleNextFirings {
                @([PSCustomObject]@{ Rings = @('Ring1'); DateUtc = $script:PlanNow2.AddDays(2) })
            }
            Mock Invoke-AzResourceGraphQuery {
                @([PSCustomObject]@{
                        id             = '/subscriptions/s/clusters/c1'
                        name           = 'cluster1'
                        resourceGroup  = 'rg1'
                        subscriptionId = 's'
                        tags           = [PSCustomObject]@{ UpdateAuthAccountId = 'acct1'; UpdateRing = 'Ring1' }
                    })
            }

            $plan = Resolve-AzLocalSideloadPlan -SchedulePath 'sched.yml' -AuthMapPath 'auth.csv' -CatalogPath 'cat.yml' -LeadDays 7 -Now $script:PlanNow2

            @($plan).Count | Should -Be 1
            $plan[0].Status | Should -Be 'NoCatalogEntry'
        }
    }
}

Describe 'Sideload (v0.9.22): typed settings and task safety' {
    It 'parses the bundled disabled schema-1 settings file' {
        $path = Join-Path $PSScriptRoot '..\Automation-Pipeline-Examples\sideload-settings.example.yml'
        $settings = Get-AzLocalSideloadSettings -Path $path
        $settings.SchemaVersion | Should -Be 1
        $settings.Enabled | Should -BeFalse
        $settings.Identity.task.logonType | Should -Be 'ServiceAccount'
        $settings.Reconciliation.maxConcurrentCopiesPerRunner | Should -Be 2
    }

    It 'defaults an omitted per-runner copy cap to the fleet cap for existing schema-1 files' {
        $source = Join-Path $PSScriptRoot '..\Automation-Pipeline-Examples\sideload-settings.example.yml'
        $path = Join-Path $TestDrive 'legacy-settings.yml'
        (Get-Content -LiteralPath $source -Raw) -replace '(?m)^\s*maxConcurrentCopiesPerRunner:.*\r?\n', '' | Set-Content -LiteralPath $path -Encoding UTF8

        $settings = Get-AzLocalSideloadSettings -Path $path
        $settings.Reconciliation.maxConcurrentCopiesPerRunner | Should -Be $settings.Reconciliation.maxConcurrentCopies
    }

    It 'rejects a per-runner copy cap above the fleet cap' {
        $source = Join-Path $PSScriptRoot '..\Automation-Pipeline-Examples\sideload-settings.example.yml'
        $path = Join-Path $TestDrive 'invalid-runner-cap.yml'
        (Get-Content -LiteralPath $source -Raw) -replace 'maxConcurrentCopiesPerRunner: 2', 'maxConcurrentCopiesPerRunner: 3' | Set-Content -LiteralPath $path -Encoding UTF8

        { Get-AzLocalSideloadSettings -Path $path } | Should -Throw '*maxConcurrentCopiesPerRunner cannot exceed*'
    }

    It 'rejects an enabled settings file without an explicit task principal' {
        $source = Join-Path $PSScriptRoot '..\Automation-Pipeline-Examples\sideload-settings.example.yml'
        $path = Join-Path $TestDrive 'enabled-without-principal.yml'
        (Get-Content -LiteralPath $source -Raw) -replace 'enabled: false', 'enabled: true' | Set-Content -LiteralPath $path -Encoding UTF8
        { Get-AzLocalSideloadSettings -Path $path } | Should -Throw '*principalUserId is required*'
    }

    It 'creates state with unique operation and process diagnostic fields' {
        $first = InModuleScope AzLocal.UpdateManagement { New-AzLocalSideloadState -ClusterName c1 -Version 1.0 }
        $second = InModuleScope AzLocal.UpdateManagement { New-AzLocalSideloadState -ClusterName c1 -Version 1.0 }
        $first.OperationId | Should -Not -BeNullOrEmpty
        $first.OperationId | Should -Not -Be $second.OperationId
        $first.PSObject.Properties.Name | Should -Contain 'WorkerProcessId'
        $first.PSObject.Properties.Name | Should -Contain 'RobocopyProcessId'
        $first.PSObject.Properties.Name | Should -Contain 'LastProgressUtc'
    }

    It 'rejects S4U for UNC-backed copy tasks before task registration' {
        InModuleScope AzLocal.UpdateManagement {
            { Register-AzLocalSideloadCopyTask -TaskName t1 -ClusterName c1 -Version 1.0 -OperationId op1 -SourcePath '\\server\cache\x.zip' -TargetPath '\\cluster\share' -StateRoot '\\server\state' -PrincipalUserId 'CONTOSO\svc' -LogonType S4U } |
                Should -Throw '*cannot be used for sideload UNC paths*'
        }
    }
}

Describe 'Sideload (v0.8.7): Invoke-AzLocalSideloadUpdate state machine' {

    It 'Skips a cluster that has no state and is not due (Status != Planned)' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalSideloadState { $null }
            Mock Invoke-SideloadCopyStart { [PSCustomObject]@{ Retries = 0 } }

            $plan = @([PSCustomObject]@{ ClusterName = 'c1'; Status = 'NotDue'; SelectedVersion = '12.0'; Message = 'not yet' })
            $res = Invoke-AzLocalSideloadUpdate -Plan $plan -StateRoot 'TestDrive:\state' -Confirm:$false

            @($res).Count | Should -Be 1
            $res[0].Action | Should -Be 'Skip'
            Assert-MockCalled Invoke-SideloadCopyStart -Times 0 -Scope It
        }
    }

    It 'Starts the copy for a due cluster with no existing state' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalSideloadState { $null }
            Mock Invoke-SideloadCopyStart { [PSCustomObject]@{ Retries = 0; MediaFileName = 'media.zip' } }

            $plan = @([PSCustomObject]@{ ClusterName = 'c1'; Status = 'Planned'; SelectedVersion = '12.2605.1003.210'; Message = 'due' })
            $res = Invoke-AzLocalSideloadUpdate -Plan $plan -StateRoot 'TestDrive:\state' -Confirm:$false

            $res[0].Action | Should -Be 'Start'
            $res[0].State | Should -Be 'Copying'
            Assert-MockCalled Invoke-SideloadCopyStart -Times 1 -Scope It
        }
    }

    It 'defers a new copy when the current runner has reached its host cap' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalSideloadState {
                if ($ClusterName -eq 'active') {
                    return [PSCustomObject]@{ ClusterName = 'active'; State = 'Copying'; Version = '12.0'; OwningMachine = $env:COMPUTERNAME; Retries = 0; TotalBytes = 100; CopiedBytes = 50; Mbps = 1; EtaUtc = '' }
                }
                return $null
            }
            Mock Test-AzLocalSideloadHeartbeatStale { $false }
            Mock Test-AzLocalSideloadProgressStale { $false }
            Mock Invoke-SideloadCopyStart { [PSCustomObject]@{ Retries = 0 } }

            $plan = @(
                [PSCustomObject]@{ ClusterName = 'active'; Status = 'Planned'; SelectedVersion = '12.0' }
                [PSCustomObject]@{ ClusterName = 'queued'; Status = 'Planned'; SelectedVersion = '12.0' }
            )
            $res = Invoke-AzLocalSideloadUpdate -Plan $plan -StateRoot 'TestDrive:\state' -MaxConcurrentCopies 10 -MaxConcurrentCopiesPerRunner 1 -Confirm:$false

            $res[1].Action | Should -Be 'Deferred'
            $res[1].Message | Should -Match 'runner.*copy limit 1 reached'
            Assert-MockCalled Invoke-SideloadCopyStart -Times 0 -Scope It
        }
    }

    It 'does not charge another runner active copy against the current runner cap' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalSideloadState {
                if ($ClusterName -eq 'remote-active') {
                    return [PSCustomObject]@{ ClusterName = 'remote-active'; State = 'Copying'; Version = '12.0'; OwningMachine = 'OTHER-RUNNER'; Retries = 0; TotalBytes = 100; CopiedBytes = 50; Mbps = 1; EtaUtc = '' }
                }
                return $null
            }
            Mock Test-AzLocalSideloadHeartbeatStale { $false }
            Mock Test-AzLocalSideloadProgressStale { $false }
            Mock Invoke-SideloadCopyStart { [PSCustomObject]@{ Retries = 0 } }

            $plan = @(
                [PSCustomObject]@{ ClusterName = 'remote-active'; Status = 'Planned'; SelectedVersion = '12.0' }
                [PSCustomObject]@{ ClusterName = 'queued'; Status = 'Planned'; SelectedVersion = '12.0' }
            )
            $res = Invoke-AzLocalSideloadUpdate -Plan $plan -StateRoot 'TestDrive:\state' -MaxConcurrentCopies 10 -MaxConcurrentCopiesPerRunner 1 -Confirm:$false

            $res[1].Action | Should -Be 'Start'
            Assert-MockCalled Invoke-SideloadCopyStart -Times 1 -Scope It
        }
    }

    It 'Reports None when the cluster is already Imported' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalSideloadState {
                [PSCustomObject]@{ ClusterName = 'c1'; State = 'Imported'; Version = '12.0'; Message = 'done' }
            }

            $plan = @([PSCustomObject]@{ ClusterName = 'c1'; Status = 'Planned'; SelectedVersion = '12.0' })
            $res = Invoke-AzLocalSideloadUpdate -Plan $plan -StateRoot 'TestDrive:\state' -Confirm:$false

            $res[0].Action | Should -Be 'None'
            $res[0].State | Should -Be 'Imported'
        }
    }

    It 'Reports InProgress for a Copying state with a fresh heartbeat' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalSideloadState {
                [PSCustomObject]@{ ClusterName = 'c1'; State = 'Copying'; Version = '12.0'; TotalBytes = [long]100; CopiedBytes = [long]50; Mbps = 42; EtaUtc = '2026-06-11T01:00:00Z'; Retries = 0; Message = 'copying' }
            }
            Mock Test-AzLocalSideloadHeartbeatStale { $false }

            $plan = @([PSCustomObject]@{ ClusterName = 'c1'; Status = 'Planned'; SelectedVersion = '12.0' })
            $res = Invoke-AzLocalSideloadUpdate -Plan $plan -StateRoot 'TestDrive:\state' -Confirm:$false

            $res[0].Action | Should -Be 'InProgress'
            $res[0].State | Should -Be 'Copying'
            $res[0].Message | Should -Match '50'
        }
    }

    It 'Marks Failed when a Copying heartbeat is stale and retries are exhausted' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalSideloadState {
                [PSCustomObject]@{ ClusterName = 'c1'; State = 'Copying'; Version = '12.0'; Retries = [int]3; Message = '' }
            }
            Mock Test-AzLocalSideloadHeartbeatStale { $true }
            Mock Set-AzLocalSideloadState { }

            $plan = @([PSCustomObject]@{ ClusterName = 'c1'; Status = 'Planned'; SelectedVersion = '12.0' })
            $res = Invoke-AzLocalSideloadUpdate -Plan $plan -StateRoot 'TestDrive:\state' -MaxRetries 3 -Confirm:$false

            $res[0].Action | Should -Be 'Failed'
            $res[0].State | Should -Be 'Failed'
            Assert-MockCalled Set-AzLocalSideloadState -Times 1 -Scope It
        }
    }

    It 'Advances a Copied state through the import + gate-flip helper' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalSideloadState {
                [PSCustomObject]@{ ClusterName = 'c1'; State = 'Copied'; Version = '12.0' }
            }
            Mock Complete-SideloadImport { [PSCustomObject]@{ State = 'Imported'; Message = 'Imported; UpdateSideloaded=True.' } }

            $plan = @([PSCustomObject]@{ ClusterName = 'c1'; Status = 'Planned'; SelectedVersion = '12.0' })
            $res = Invoke-AzLocalSideloadUpdate -Plan $plan -StateRoot 'TestDrive:\state' -Confirm:$false

            $res[0].Action | Should -Be 'Import'
            $res[0].State | Should -Be 'Imported'
            Assert-MockCalled Complete-SideloadImport -Times 1 -Scope It
        }
    }

    It 'Surfaces an Error row when a helper throws' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Get-AzLocalSideloadState { $null }
            Mock Invoke-SideloadCopyStart { throw 'media staging failed' }

            $plan = @([PSCustomObject]@{ ClusterName = 'c1'; Status = 'Planned'; SelectedVersion = '12.0' })
            $res = Invoke-AzLocalSideloadUpdate -Plan $plan -StateRoot 'TestDrive:\state' -Confirm:$false

            $res[0].Action | Should -Be 'Error'
            $res[0].State | Should -Be 'Failed'
            $res[0].Message | Should -Match 'media staging failed'
        }
    }
}

Describe 'Sideload (v0.8.7): Export-AzLocalSideloadStatusReport' {

    BeforeEach {
        $script:SideloadStateRoot = Join-Path $env:TEMP ("azlocal-sideload-state-{0}" -f ([Guid]::NewGuid()))
        $script:SideloadStateDir = Join-Path $script:SideloadStateRoot 'state'
        New-Item -ItemType Directory -Path $script:SideloadStateDir -Force | Out-Null
    }

    AfterEach {
        Remove-Item -LiteralPath $script:SideloadStateRoot -Recurse -Force -ErrorAction SilentlyContinue
    }

    It 'Builds a markdown table and JUnit XML from shared state records' {
        $copying = [PSCustomObject]@{ ClusterName = 'clusterA'; Version = '12.0'; State = 'Copying'; OwningMachine = 'agent1'; TotalBytes = [long]100; CopiedBytes = [long]25; Mbps = 30; EtaUtc = '2026-06-11T02:00:00Z'; Retries = 0; Message = 'in progress' }
        $imported = [PSCustomObject]@{ ClusterName = 'clusterB'; Version = '12.0'; State = 'Imported'; OwningMachine = 'agent2'; TotalBytes = [long]0; CopiedBytes = [long]0; Mbps = 0; EtaUtc = ''; Retries = 0; Message = 'done' }
        ($copying | ConvertTo-Json) | Set-Content -LiteralPath (Join-Path $script:SideloadStateDir 'clusterA.json') -Encoding ASCII
        ($imported | ConvertTo-Json) | Set-Content -LiteralPath (Join-Path $script:SideloadStateDir 'clusterB.json') -Encoding ASCII

        $report = Export-AzLocalSideloadStatusReport -StateRoot $script:SideloadStateRoot

        $report.Markdown | Should -Match '## Sideload status'
        $report.Markdown | Should -Match 'clusterA'
        $report.Markdown | Should -Match 'clusterB'
        $report.JUnitXml | Should -Match '<testsuites'
        $report.HasFailures | Should -BeFalse
        @($report.Counts).Count | Should -BeGreaterThan 0
    }

    It 'Flags HasFailures and a JUnit failure for a Failed state' {
        $failed = [PSCustomObject]@{ ClusterName = 'clusterC'; Version = '12.0'; State = 'Failed'; OwningMachine = 'agent1'; TotalBytes = [long]0; CopiedBytes = [long]0; Mbps = 0; EtaUtc = ''; Retries = 3; Message = 'copy failed' }
        ($failed | ConvertTo-Json) | Set-Content -LiteralPath (Join-Path $script:SideloadStateDir 'clusterC.json') -Encoding ASCII

        $report = Export-AzLocalSideloadStatusReport -StateRoot $script:SideloadStateRoot

        $report.HasFailures | Should -BeTrue
        $report.JUnitXml | Should -Match 'SideloadFailed'
    }

    It 'Surfaces plan error rows (UnknownAuthAccountId / NoCatalogEntry) in the report' {
        $planErrors = @(
            [PSCustomObject]@{ ClusterName = 'clusterD'; Status = 'UnknownAuthAccountId'; Message = 'unknown account' },
            [PSCustomObject]@{ ClusterName = 'clusterE'; Status = 'NoCatalogEntry'; Message = 'no catalog entry' }
        )

        $report = Export-AzLocalSideloadStatusReport -StateRoot $script:SideloadStateRoot -Plan $planErrors

        $report.HasFailures | Should -BeTrue
        $report.Markdown | Should -Match 'Plan warnings / errors'
        $report.Markdown | Should -Match 'UnknownAuthAccountId'
        $report.Markdown | Should -Match 'NoCatalogEntry'
    }

    It 'Writes sideload-status.md and sideload-junit.xml when OutputPath is supplied' {
        $imported = [PSCustomObject]@{ ClusterName = 'clusterB'; Version = '12.0'; State = 'Imported'; OwningMachine = 'agent2'; TotalBytes = [long]0; CopiedBytes = [long]0; Mbps = 0; EtaUtc = ''; Retries = 0; Message = 'done' }
        ($imported | ConvertTo-Json) | Set-Content -LiteralPath (Join-Path $script:SideloadStateDir 'clusterB.json') -Encoding ASCII
        $outDir = Join-Path $script:SideloadStateRoot 'report'

        $null = Export-AzLocalSideloadStatusReport -StateRoot $script:SideloadStateRoot -OutputPath $outDir

        Test-Path -LiteralPath (Join-Path $outDir 'sideload-status.md') | Should -BeTrue
        Test-Path -LiteralPath (Join-Path $outDir 'sideload-junit.xml') | Should -BeTrue
    }
}

Describe 'Sideload (v0.8.7): Add-AzLocalSideloadStepSummary' {

    It 'Calls Export-AzLocalSideloadStatusReport and appends the markdown to the step summary' {
        InModuleScope AzLocal.UpdateManagement {
            Mock Export-AzLocalSideloadStatusReport {
                [PSCustomObject]@{ Markdown = '## Sideload status'; JUnitXml = '<testsuites/>'; Counts = @(); HasFailures = $false }
            }
            Mock Add-AzLocalPipelineStepSummary { }

            $report = Add-AzLocalSideloadStepSummary -StateRoot 'TestDrive:\state'

            $report.Markdown | Should -Be '## Sideload status'
            Assert-MockCalled Export-AzLocalSideloadStatusReport -Times 1 -Scope It
            Assert-MockCalled Add-AzLocalPipelineStepSummary -Times 1 -Scope It
        }
    }
}

#endregion On-Prem Sideloading Automation (v0.8.7)

#region v0.8.80 Pipeline-failure rendering improvements (Q1 / Q2 / Q3)

Describe 'v0.8.80 Q3: Get-DeepestErrorMessage -IncludeDescription' {

    It 'Returns a string by default (back-compat)' {
        InModuleScope AzLocal.UpdateManagement {
            $steps = @(
                [PSCustomObject]@{
                    name = 'L1'; status = 'Failed'; description = 'L1 desc'; errorMessage = 'L1 trace'
                }
            )
            $r = Get-DeepestErrorMessage -Steps $steps
            $r | Should -BeOfType ([string])
            $r | Should -Be 'L1 trace'
        }
    }

    It 'Returns a hashtable with Msg + Description when -IncludeDescription is set' {
        InModuleScope AzLocal.UpdateManagement {
            $steps = @(
                [PSCustomObject]@{
                    name = 'L1'; status = 'Failed'; description = 'outer desc'; errorMessage = 'outer trace'
                    steps = @(
                        [PSCustomObject]@{
                            name = 'L2'; status = 'Error'; description = 'inner desc'; errorMessage = 'inner trace'
                        }
                    )
                }
            )
            $r = Get-DeepestErrorMessage -Steps $steps -IncludeDescription
            $r | Should -BeOfType ([hashtable])
            $r.Msg | Should -Be 'inner trace'
            $r.Description | Should -Be 'inner desc'
        }
    }

    It 'Returns hashtable with empty string fields when no failed step is found (-IncludeDescription)' {
        InModuleScope AzLocal.UpdateManagement {
            $r = Get-DeepestErrorMessage -Steps @() -IncludeDescription
            $r | Should -BeOfType ([hashtable])
            $r.Msg | Should -Be ''
            $r.Description | Should -Be ''
        }
    }

    It 'Should NOT throw on a Failed step that lacks a description property (strict-mode guard)' {
        InModuleScope AzLocal.UpdateManagement {
            $steps = @(
                [PSCustomObject]@{
                    name = 'L1'; status = 'Failed'; errorMessage = 'no desc here'
                }
            )
            { Get-DeepestErrorMessage -Steps $steps -IncludeDescription } | Should -Not -Throw
            $r = Get-DeepestErrorMessage -Steps $steps -IncludeDescription
            $r.Msg | Should -Be 'no desc here'
            $r.Description | Should -Be ''
        }
    }
}

Describe 'v0.8.80 Q3: Resolve-AzLocalUpdateRunDeepestError captures Description' {

    It 'Should emit a Description field on the result hashtable' {
        InModuleScope AzLocal.UpdateManagement {
            $steps = @(
                [PSCustomObject]@{
                    name = 'Outer'; status = 'Failed'; description = 'outer desc'; errorMessage = 'outer trace'
                    steps = @(
                        [PSCustomObject]@{
                            name = 'Deepest'; status = 'Error'; description = 'deepest desc'; errorMessage = 'deepest trace'
                        }
                    )
                }
            )
            $r = Resolve-AzLocalUpdateRunDeepestError -Steps $steps
            $r | Should -BeOfType ([hashtable])
            $r.ContainsKey('Description') | Should -BeTrue
            $r.Description | Should -Be 'deepest desc'
            $r.Msg | Should -Be 'deepest trace'
        }
    }
}

Describe 'v0.8.80 Q3: Format-AzLocalUpdateRun emits ErrorDescription' {

    It 'Should always emit an ErrorDescription property (empty string when no error)' {
        InModuleScope AzLocal.UpdateManagement {
            $run = [PSCustomObject]@{
                name = '2026-01-01T00:00:00Z'
                properties = [PSCustomObject]@{
                    state = 'Succeeded'
                    timeStarted = (Get-Date).ToUniversalTime().ToString('o')
                    lastUpdatedTime = (Get-Date).ToUniversalTime().ToString('o')
                    steps = @()
                }
            }
            $out = Format-AzLocalUpdateRun -Run $run
            $out.PSObject.Properties.Name | Should -Contain 'ErrorDescription'
            $out.PSObject.Properties.Name | Should -Contain 'ErrorMessage'
        }
    }

    It 'Should populate ErrorDescription from the deepest Failed step description' {
        InModuleScope AzLocal.UpdateManagement {
            $run = [PSCustomObject]@{
                name = '2026-01-01T00:00:00Z'
                properties = [PSCustomObject]@{
                    state = 'Failed'
                    timeStarted = (Get-Date).ToUniversalTime().ToString('o')
                    lastUpdatedTime = (Get-Date).ToUniversalTime().ToString('o')
                    progress = [PSCustomObject]@{
                        steps = @(
                            [PSCustomObject]@{
                                name = 'Stage'; status = 'Failed'; description = 'Outer stage desc'; errorMessage = 'outer trace'
                                steps = @(
                                    [PSCustomObject]@{
                                        name = 'Inner'; status = 'Error'; description = 'Inner step desc'; errorMessage = 'inner trace'
                                    }
                                )
                            }
                        )
                    }
                }
            }
            $out = Format-AzLocalUpdateRun -Run $run
            $out.ErrorDescription | Should -Be 'Inner step desc'
            $out.ErrorMessage | Should -Be 'inner trace'
        }
    }
}

